'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { saveTokens } from '@/lib/auth-token';

export default function LoginPage() {
  const router = useRouter();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const msg = urlParams.get('msg');
    if (msg) setError(msg);
  }, []);

  const handleSubmit = async () => {
    if (!email || !password) return;
    setLoading(true);
    setError('');
    try {
      const res = await fetch(`${process.env.API_URL}/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || 'Login failed');
      // Save tokens to localStorage AND shared .nglob.com cookie so portal
      // subdomains (driver / admin / manager) can read them.
      saveTokens(data.accessToken, data.refreshToken, data.user?.role);

      // Store user info for quick role checks
      if (data.user) {
        localStorage.setItem('userRole', data.user.role);
        localStorage.setItem('userName', data.user.name || '');
      }

      // Role-based redirect
      const urlParams = new URLSearchParams(window.location.search);
      const redirectUrl = urlParams.get('redirect');

      if (redirectUrl) {
        const allParams = new URLSearchParams(window.location.search);
        allParams.delete('redirect');
        const paramStr = allParams.toString();
        router.push(paramStr ? `${redirectUrl}?${paramStr}` : redirectUrl);
      } else {
        const isLocal = window.location.host.includes('localhost');
        const baseDomain = isLocal ? 'nglob.localhost:3000' : 'nglob.com';
        const protocol = window.location.protocol;

        const role = data.user?.role;
        if (role === 'ADMIN') {
          window.location.href = `${protocol}//admin.${baseDomain}/`;
        } else if (role === 'DRIVER') {
          window.location.href = `${protocol}//driver.${baseDomain}/`;
        } else if (role === 'MANAGER') {
          window.location.href = `${protocol}//manager.${baseDomain}/`;
        } else if (role === 'AFFILIATE') {
          window.location.href = `${protocol}//app.${baseDomain}/affiliate`;
        } else {
          window.location.href = `${protocol}//app.${baseDomain}/`;
        }
      }
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-white flex p-4 md:p-6">
      {/* ═══ LEFT SIDE: SIGN IN FORM ═══ */}
      <main className="flex-1 flex flex-col items-center justify-center px-6 lg:px-12 py-12 relative z-10">
        <div className="w-full max-w-sm">
          <Link href="/" className="inline-flex items-center gap-2.5 group mb-12">
            <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-blue-600 to-blue-700 text-sm font-bold text-white shadow-md shadow-blue-600/20 transition-transform group-hover:scale-105">
              N
            </span>
            <span className="text-2xl font-extrabold tracking-tight text-gray-900">NGLOB</span>
          </Link>

          <h1 className="text-4xl font-extrabold text-gray-900 tracking-tight mb-2">Welcome back.</h1>
          <p className="text-base font-medium text-gray-500 mb-8">
            Don't have an account?{' '}
            <Link href="/register" className="text-blue-600 hover:text-blue-700 font-bold underline decoration-blue-600/30 underline-offset-4 transition-colors">
              Register here
            </Link>
          </p>

          <div className="space-y-5">
            {/* ═══ QUICK LOGIN SHORTCUTS (TESTING ONLY) ═══ */}
            <div className="bg-blue-50/50 p-4 rounded-xl border border-blue-100/50">
              <div className="text-[10px] font-extrabold text-blue-600 uppercase tracking-widest mb-3 text-center">Quick Login (Test Accounts)</div>
              <div className="grid grid-cols-3 gap-2">
                <button
                  onClick={(e) => { e.preventDefault(); setEmail('admin@test.com'); setPassword('password123'); }}
                  className="bg-white border border-blue-100 text-blue-700 py-2 rounded-lg text-xs font-bold hover:bg-blue-600 hover:text-white hover:border-blue-600 transition-all shadow-sm"
                  type="button"
                >
                  Admin
                </button>
                <button
                  onClick={(e) => { e.preventDefault(); setEmail('manager@test.com'); setPassword('password123'); }}
                  className="bg-white border border-blue-100 text-blue-700 py-2 rounded-lg text-xs font-bold hover:bg-blue-600 hover:text-white hover:border-blue-600 transition-all shadow-sm"
                  type="button"
                >
                  Manager
                </button>
                <button
                  onClick={(e) => { e.preventDefault(); setEmail('driver@test.com'); setPassword('password123'); }}
                  className="bg-white border border-blue-100 text-blue-700 py-2 rounded-lg text-xs font-bold hover:bg-blue-600 hover:text-white hover:border-blue-600 transition-all shadow-sm"
                  type="button"
                >
                  Driver
                </button>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-extrabold text-gray-400 uppercase tracking-widest">Email Address</label>
              <input
                type="email"
                value={email}
                onChange={e => setEmail(e.target.value)}
                className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3.5 text-gray-900 font-medium focus:outline-none focus:border-blue-600 focus:ring-4 focus:ring-blue-600/10 transition-all shadow-sm placeholder:text-gray-400"
                placeholder="your@email.com"
                onKeyDown={e => e.key === 'Enter' && handleSubmit()}
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-extrabold text-gray-400 uppercase tracking-widest">Password</label>
              <input
                type="password"
                value={password}
                onChange={e => setPassword(e.target.value)}
                className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3.5 text-gray-900 font-medium focus:outline-none focus:border-blue-600 focus:ring-4 focus:ring-blue-600/10 transition-all shadow-sm placeholder:text-gray-400"
                placeholder="••••••••"
                onKeyDown={e => e.key === 'Enter' && handleSubmit()}
              />
            </div>

            {error && <p className="text-sm font-semibold text-red-500 bg-red-50 px-4 py-3 rounded-xl border border-red-100">{error}</p>}

            <button
              onClick={handleSubmit}
              disabled={loading || !email || !password}
              className="w-full bg-gray-900 text-white py-4 rounded-xl text-base font-bold hover:bg-blue-600 disabled:opacity-50 disabled:hover:bg-gray-900 transition-all shadow-xl hover:-translate-y-0.5"
            >
              {loading ? 'Logging in...' : 'Log In to Account'}
            </button>

            <div className="relative my-8">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-gray-100" />
              </div>
              <div className="relative text-center">
                <span className="bg-white px-4 text-[10px] font-extrabold uppercase tracking-widest text-gray-400">or continue with</span>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <button onClick={() => window.location.href = `${process.env.API_URL}/auth/google`} className="w-full bg-white border border-gray-200 text-gray-700 py-3 rounded-xl text-sm font-bold hover:border-gray-400 hover:bg-gray-50 transition-all shadow-sm flex items-center justify-center gap-2">
                <span className="font-extrabold text-blue-600 text-lg leading-none">G</span>
                Google
              </button>

              <button onClick={() => window.location.href = `${process.env.API_URL}/auth/apple`} className="w-full bg-white border border-gray-200 text-gray-700 py-3 rounded-xl text-sm font-bold hover:border-gray-400 hover:bg-gray-50 transition-all shadow-sm flex items-center justify-center gap-2">
                <span className="font-extrabold text-gray-900 text-lg leading-none">🍎</span>
                Apple
              </button>
            </div>

            <button onClick={() => window.location.href = `${process.env.API_URL}/auth/facebook`} className="w-full bg-white border border-gray-200 text-gray-700 py-3 rounded-xl text-sm font-bold hover:border-gray-400 hover:bg-gray-50 transition-all shadow-sm flex items-center justify-center gap-2">
              <span className="text-blue-800 font-extrabold text-lg leading-none">f</span>
              Facebook
            </button>

          </div>

          <div className="mt-8 text-center">
            <Link href="/forgot-password" className="text-sm font-semibold text-gray-500 hover:text-gray-900 transition-colors">
              Forgot your password?
            </Link>
          </div>
        </div>
      </main>

      {/* ═══ RIGHT SIDE: IMAGE ═══ */}
      <div className="hidden lg:block w-1/2 relative rounded-[3rem] overflow-hidden shadow-2xl">
        <img src="/images/hero_home_move_1777334642122.png" alt="NGLOB Moving" className="absolute inset-0 w-full h-full object-cover" />
        <div className="absolute inset-0 bg-gradient-to-t from-gray-900/90 via-gray-900/20 to-transparent"></div>
        <div className="absolute bottom-0 left-0 right-0 p-16">
          <div className="flex items-center gap-3 mb-6">
            <span className="w-12 h-[3px] bg-blue-500 rounded-full"></span>
            <p className="uppercase tracking-[0.2em] text-[11px] font-extrabold text-blue-400">NGLOB Dashboard</p>
          </div>
          <h2 className="text-5xl font-extrabold text-white tracking-tighter mb-4 leading-[1.1]">
            Manage your move <br />with zero stress.
          </h2>
          <p className="text-lg text-gray-300 font-medium max-w-md">
            Log in to track your deliveries in real-time, manage storage units, and access premium customer support.
          </p>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';

export default function RegisterPage() {
  const router = useRouter();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [referralCode, setReferralCode] = useState<string | null>(null);

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const msg = urlParams.get('msg');
    const ref = urlParams.get('ref');
    if (msg) setError(msg);
    if (ref) setReferralCode(ref);
  }, []);

  const handleSubmit = async () => {
    if (!name || !email || !password) return;
    setLoading(true);
    setError('');
    try {
      const res = await fetch(`${process.env.API_URL}/auth/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          name, 
          email, 
          password, 
          phone: phone || undefined,
          referralCode: referralCode || undefined
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || 'Registration failed');
      localStorage.setItem('accessToken', data.accessToken);
      localStorage.setItem('refreshToken', data.refreshToken);

      const urlParams = new URLSearchParams(window.location.search);
      const redirectUrl = urlParams.get('redirect');

      if (redirectUrl) {
        const allParams = new URLSearchParams(window.location.search);
        allParams.delete('redirect');
        const paramStr = allParams.toString();
        router.push(paramStr ? `${redirectUrl}?${paramStr}` : redirectUrl);
      } else {
        const isLocal = window.location.host.includes('localhost');
        const baseDomain = isLocal ? 'nglob.localhost:3000' : 'nglob.com';
        window.location.href = `${window.location.protocol}//app.${baseDomain}/`;
      }
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-white flex p-4 md:p-6">
      {/* ═══ LEFT SIDE: REGISTRATION FORM ═══ */}
      <main className="flex-1 flex flex-col items-center justify-center px-6 lg:px-12 py-12 relative z-10">
        <div className="w-full max-w-sm">
          <Link href="/" className="inline-flex items-center gap-2.5 group mb-8">
            <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-blue-600 to-blue-700 text-sm font-bold text-white shadow-md shadow-blue-600/20 transition-transform group-hover:scale-105">
              N
            </span>
            <span className="text-2xl font-extrabold tracking-tight text-gray-900">NGLOB</span>
          </Link>

          <h1 className="text-4xl font-extrabold text-gray-900 tracking-tight mb-2">Create account.</h1>
          <p className="text-base font-medium text-gray-500 mb-6">
            Already have an account?{' '}
            <Link href="/login" className="text-blue-600 hover:text-blue-700 font-bold underline decoration-blue-600/30 underline-offset-4 transition-colors">
              Log in here
            </Link>
          </p>

          {referralCode ? (
            <div className="bg-emerald-50 border border-emerald-100 rounded-xl p-4 mb-6 text-xs text-emerald-700 shadow-sm">
              🎁 <span className="font-extrabold text-emerald-800">You've been referred!</span> Complete registration to get 10% off your first booking.
            </div>
          ) : (
            <div className="bg-blue-50 border border-blue-100 rounded-xl p-4 mb-6 text-xs text-blue-700 shadow-sm">
              🎁 Register now to get started and start earning rewards for every move.
            </div>
          )}

          <div className="space-y-4">
            <div className="space-y-1.5">
              <label className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest">Full Name</label>
              <input
                value={name}
                onChange={e => setName(e.target.value)}
                className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3.5 text-gray-900 font-medium focus:outline-none focus:border-blue-600 focus:ring-4 focus:ring-blue-600/10 transition-all shadow-sm placeholder:text-gray-400"
                placeholder="Jane Smith"
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest">Email Address</label>
              <input
                type="email"
                value={email}
                onChange={e => setEmail(e.target.value)}
                className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3.5 text-gray-900 font-medium focus:outline-none focus:border-blue-600 focus:ring-4 focus:ring-blue-600/10 transition-all shadow-sm placeholder:text-gray-400"
                placeholder="your@email.com"
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest">Phone Number (Optional)</label>
              <input
                type="tel"
                value={phone}
                onChange={e => setPhone(e.target.value)}
                className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3.5 text-gray-900 font-medium focus:outline-none focus:border-blue-600 focus:ring-4 focus:ring-blue-600/10 transition-all shadow-sm placeholder:text-gray-400"
                placeholder="07xxx xxxxxx"
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest">Password</label>
              <input
                type="password"
                value={password}
                onChange={e => setPassword(e.target.value)}
                className="w-full bg-gray-50 border border-gray-200 rounded-xl px-4 py-3.5 text-gray-900 font-medium focus:outline-none focus:border-blue-600 focus:ring-4 focus:ring-blue-600/10 transition-all shadow-sm placeholder:text-gray-400"
                placeholder="At least 8 characters"
              />
            </div>

            {error && <p className="text-sm font-semibold text-red-500 bg-red-50 px-4 py-3 rounded-xl border border-red-100">{error}</p>}

            <button
              onClick={handleSubmit}
              disabled={loading || !name || !email || !password}
              className="w-full bg-gray-900 text-white py-4 rounded-xl text-base font-bold hover:bg-blue-600 disabled:opacity-50 disabled:hover:bg-gray-900 transition-all shadow-xl hover:-translate-y-0.5 mt-2"
            >
              {loading ? 'Creating account...' : 'Create Account'}
            </button>

            <div className="relative my-6">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-gray-100" />
              </div>
              <div className="relative text-center">
                <span className="bg-white px-4 text-[10px] font-extrabold uppercase tracking-widest text-gray-400">or continue with</span>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <button onClick={() => window.location.href = `${process.env.API_URL}/auth/google`} className="w-full bg-white border border-gray-200 text-gray-700 py-3 rounded-xl text-sm font-bold hover:border-gray-400 hover:bg-gray-50 transition-all shadow-sm flex items-center justify-center gap-2">
                <span className="font-extrabold text-blue-600 text-lg leading-none">G</span>
                Google
              </button>

              <button onClick={() => window.location.href = `${process.env.API_URL}/auth/apple`} className="w-full bg-white border border-gray-200 text-gray-700 py-3 rounded-xl text-sm font-bold hover:border-gray-400 hover:bg-gray-50 transition-all shadow-sm flex items-center justify-center gap-2">
                <span className="font-extrabold text-gray-900 text-lg leading-none">🍎</span>
                Apple
              </button>
            </div>

            <button onClick={() => window.location.href = `${process.env.API_URL}/auth/facebook`} className="w-full bg-white border border-gray-200 text-gray-700 py-3 rounded-xl text-sm font-bold hover:border-gray-400 hover:bg-gray-50 transition-all shadow-sm flex items-center justify-center gap-2">
              <span className="text-blue-800 font-extrabold text-lg leading-none">f</span>
              Facebook
            </button>

          </div>

          <p className="mt-8 text-[11px] font-semibold text-gray-400 text-center leading-relaxed">
            By creating an account you agree to our{' '}
            <Link href="/terms" className="text-gray-600 underline hover:text-gray-900">Terms of Use</Link> and{' '}
            <Link href="/privacy" className="text-gray-600 underline hover:text-gray-900">Privacy Policy</Link>
          </p>
        </div>
      </main>

      {/* ═══ RIGHT SIDE: IMAGE ═══ */}
      <div className="hidden lg:block w-1/2 relative rounded-[3rem] overflow-hidden shadow-2xl">
        <img src="/images/svc_moving_home_1777334683252.png" alt="NGLOB Moving Service" className="absolute inset-0 w-full h-full object-cover" />
        <div className="absolute inset-0 bg-gradient-to-t from-gray-900/90 via-gray-900/20 to-transparent"></div>
        <div className="absolute bottom-0 left-0 right-0 p-16">
          <div className="flex items-center gap-3 mb-6">
            <span className="w-12 h-[3px] bg-blue-500 rounded-full"></span>
            <p className="uppercase tracking-[0.2em] text-[11px] font-extrabold text-blue-400">Join NGLOB</p>
          </div>
          <h2 className="text-5xl font-extrabold text-white tracking-tighter mb-4 leading-[1.1]">
            Experience moving <br />like never before.
          </h2>
          <p className="text-lg text-gray-300 font-medium max-w-md">
            Join over 150,000 customers who trust NGLOB for their transparent pricing, insured moves, and 99% on-time guarantee.
          </p>
        </div>
      </div>
    </div>
  );
}

'use client';
import { getAccessToken } from '@/lib/auth-token';

import { useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';

function StatusBadge({ status }: { status: string }) {
  const map: Record<string, string> = {
    CONFIRMED:  'bg-amber-50 text-amber-700 border-amber-200',
    SCHEDULED:  'bg-blue-50 text-blue-700 border-blue-200',
    DELIVERED:  'bg-green-50 text-green-700 border-green-200',
    CANCELLED:  'bg-red-50 text-red-700 border-red-200',
    PENDING:    'bg-gray-100 text-gray-600 border-gray-200',
  };
  return (
    <span className={`inline-flex px-2.5 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider border ${map[status] || 'bg-gray-100 text-gray-500 border-gray-200'}`}>
      {status}
    </span>
  );
}

function InfoRow({ label, value }: { label: string; value?: string | null }) {
  return (
    <div className="flex items-start justify-between gap-4 py-3 border-b border-gray-50 last:border-0">
      <span className="text-[11px] font-bold text-gray-400 uppercase tracking-wider shrink-0">{label}</span>
      <span className="text-[13px] font-semibold text-gray-900 text-right">{value || '—'}</span>
    </div>
  );
}

export default function AdminOrderDetailsPage() {
  const { id } = useParams();
  const router = useRouter();
  const [booking, setBooking] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchBookingDetails();
  }, [id]);

  const fetchBookingDetails = async () => {
    try {
      const res = await fetch(`${process.env.API_URL}/admin/bookings/${id}`, {
        headers: { Authorization: `Bearer ${getAccessToken()}` }
      });
      if (!res.ok) throw new Error('Failed to fetch booking details');
      const data = await res.json();
      setBooking(data);
    } catch (err: any) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  if (loading) return (
    <div className="space-y-6 animate-fade-in">
      <div className="h-10 bg-gray-200 rounded-xl w-56 animate-pulse" />
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-5">
        <div className="xl:col-span-2 space-y-5">
          <div className="h-48 bg-white rounded-2xl border border-gray-200 animate-pulse" />
          <div className="h-64 bg-white rounded-2xl border border-gray-200 animate-pulse" />
        </div>
        <div className="space-y-5">
          <div className="h-40 bg-white rounded-2xl border border-gray-200 animate-pulse" />
          <div className="h-48 bg-white rounded-2xl border border-gray-200 animate-pulse" />
        </div>
      </div>
    </div>
  );

  if (!booking) return (
    <div className="flex flex-col items-center justify-center py-24 text-center">
      <p className="text-[15px] font-bold text-gray-900 mb-2">Order Not Found</p>
      <p className="text-[13px] text-gray-400 mb-6">This booking does not exist or has been removed.</p>
      <button onClick={() => window.location.href = '/admin/bookings'} className="px-5 py-2.5 bg-gray-900 text-white rounded-xl text-[13px] font-bold hover:bg-gray-800 transition-colors">
        ← Back to Orders
      </button>
    </div>
  );

  const base = Math.round(((booking.totalPrice || 0) / 1.2) * 100) / 100;
  const vat = Math.round(((booking.totalPrice || 0) - base) * 100) / 100;

  return (
    <div className="animate-fade-in space-y-6">

      {/* Page header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <button
            onClick={() => window.location.href = '/admin/bookings'}
            className="w-9 h-9 rounded-xl border border-gray-200 bg-white flex items-center justify-center hover:bg-gray-50 transition-colors shrink-0"
          >
            <svg width="15" height="15" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <path d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
          </button>
          <div>
            <h1 className="text-2xl font-black text-gray-900 tracking-tight">Order #{booking.bookingRef}</h1>
            <div className="flex items-center gap-2 mt-1">
              <StatusBadge status={booking.status} />
              <span className="text-[11px] text-gray-400 font-medium">
                Created {new Date(booking.createdAt).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}
              </span>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-5">

