'use client';
import { getAccessToken } from '@/lib/auth-token';

import React, { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';

interface PendingItem {
  id: string;
  name: string;
  volumeM3: number;
  photoUrl: string | null;
  priceDelta: number;
}

interface ApprovalBooking {
  id: string;
  pickupAddress: string;
  destinationAddress: string;
  totalPrice: number;
  pendingItems: PendingItem[];
}

export default function ApprovalsPage() {
  const [bookings, setBookings] = useState<ApprovalBooking[]>([]);
  const [loading, setLoading] = useState(true);
  const router = useRouter();

  const fetchPending = async () => {
    const token = getAccessToken();
    if (!token) {
      router.push('/?login=true');
      return;
    }
    try {
      // Find bookings where the user is the customer
      // Since our GET /bookings/:id/pending-items needs an ID, we'll fetch the user's bookings first
      const bRes = await fetch(`${process.env.API_URL}/bookings/my-bookings`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (!bRes.ok) throw new Error('Failed to fetch bookings');

      const bData = await bRes.json();

      // For each active booking, fetch pending items
      const withPending: ApprovalBooking[] = [];
      for (const b of bData) {
        if (b.status === 'COMPLETED' || b.status === 'CANCELLED') continue;

        const iRes = await fetch(`${process.env.API_URL}/approval/bookings/${b.id}/pending-items`, {
          headers: { Authorization: `Bearer ${token}` }
        });

        if (iRes.ok) {
          const items = await iRes.json();
          if (items.length > 0) {
            withPending.push({
              id: b.id,
              pickupAddress: b.pickupAddress,
              destinationAddress: b.destinationAddress,
              totalPrice: b.totalPrice,
              pendingItems: items
            });
          }
        }
      }
      setBookings(withPending);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPending();
  }, [router]);

  const handleDecision = async (bookingId: string, itemId: string, decision: 'approve' | 'reject') => {
    const token = getAccessToken();
    if (!token) return;
    try {
      const res = await fetch(`${process.env.API_URL}/approval/bookings/${bookingId}/items/${itemId}/${decision}`, {
        method: 'PATCH',
        headers: { Authorization: `Bearer ${token}` }
      });
      if (res.ok) {
        // Refresh
        fetchPending();
      }
    } catch (err) {
      console.error(err);
    }
  };

  if (loading) {
    return <div className="p-8 text-center text-gray-500">Checking for approvals...</div>;
  }

  return (
    <div className="max-w-4xl mx-auto py-12 px-6">
      <h1 className="text-3xl font-bold text-gray-900 mb-8">Pending Approvals</h1>

      {bookings.length === 0 ? (
        <div className="bg-white rounded-2xl p-8 border border-gray-100 text-center shadow-sm">
          <p className="text-gray-500 mb-4">You have no items pending approval.</p>
          <button 
            onClick={() => window.location.href = '/app/'}
            className="bg-blue-600 text-white px-6 py-2 rounded-lg font-medium hover:bg-blue-700"
          >
            Go to Dashboard
          </button>
        </div>
      ) : (
        <div className="space-y-8">
          {bookings.map(b => (
            <div key={b.id} className="bg-white border border-gray-200 rounded-2xl p-6 shadow-sm">
              <div className="mb-4 pb-4 border-b border-gray-100">
                <p className="text-xs text-gray-400 font-semibold uppercase tracking-wider mb-2">
                  Booking #{b.id.split('-')[0]}
                </p>
                <div className="flex items-center gap-3">
                  <span className="font-medium text-gray-900">{b.pickupAddress}</span>
                  <span className="text-gray-400">→</span>
                  <span className="font-medium text-gray-900">{b.destinationAddress}</span>
                </div>
              </div>

              <div className="space-y-4">
                <p className="text-sm font-semibold text-gray-700">The driver added the following items to your inventory:</p>

                {b.pendingItems.map(item => (
                  <div key={item.id} className="flex flex-col md:flex-row gap-4 items-center bg-gray-50 rounded-xl p-4 border border-gray-100">
                    <div className="w-full md:w-32 h-32 bg-gray-200 rounded-lg flex items-center justify-center overflow-hidden flex-shrink-0">
                      {item.photoUrl ? (
                        <img src={item.photoUrl} alt={item.name} className="w-full h-full object-cover" />
                      ) : (
                        <span className="text-4xl">📸</span>
                      )}
                    </div>
                    <div className="flex-1 text-center md:text-left">
                      <p className="font-bold text-gray-900 text-lg mb-1">{item.name}</p>
                      <p className="text-sm text-gray-500 mb-2">Volume: {item.volumeM3} m³</p>
                      <p className="text-sm font-medium text-amber-600 bg-amber-50 inline-block px-3 py-1 rounded-full border border-amber-200">
                        Price adjustment: +£{item.priceDelta}
                      </p>
                    </div>
                    <div className="flex w-full md:w-auto flex-col gap-2">
                      <button 
                        onClick={() => handleDecision(b.id, item.id, 'approve')}
                        className="w-full md:w-32 bg-green-600 text-white px-4 py-2.5 rounded-lg font-bold text-sm hover:bg-green-700 transition-colors shadow-sm"
                      >
                        Approve
                      </button>
                      <button 
                        onClick={() => handleDecision(b.id, item.id, 'reject')}
                        className="w-full md:w-32 bg-white text-gray-600 border border-gray-300 px-4 py-2.5 rounded-lg font-bold text-sm hover:bg-gray-50 transition-colors"
                      >
                        Reject
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

