  setStorageAdded: (v: boolean) => void;
  packingAdded: boolean;
  setPackingAdded: (v: boolean) => void;
  materialsAdded: boolean;
  setMaterialsAdded: (v: boolean) => void;
  withStorage: boolean;
  isStorageForced: boolean;
  storageSqft: number;
  setStorageSqft: (v: number) => void;
  stairsFlights: number;
  setStairsFlights: (v: number) => void;
  hasLift: boolean;
  setHasLift: (v: boolean) => void;
  parkingDistance: number;
  setParkingDistance: (v: number) => void;
  notesForDriver: string;
  setNotesForDriver: (v: string) => void;
  packingTier?: any;
  setPackingTier?: (t: any) => void;
}

function BookingHeroForm(props: BookingFormProps) {
  const {
    tab, setTab, pickup, setPickup, destination, setDestination,
    setPickupCoords, setDestCoords,
    dateTime, setDateTime, homeSize, setHomeSize, movers, setMovers,
    items, setItems, storageAdded, setStorageAdded,
    packingAdded, setPackingAdded, materialsAdded, setMaterialsAdded, withStorage, isStorageForced, storageSqft, setStorageSqft,
    stairsFlights, setStairsFlights, hasLift, setHasLift, parkingDistance, setParkingDistance, notesForDriver, setNotesForDriver,
    packingTier, setPackingTier
  } = props;

  const [showAddItems, setShowAddItems] = useState(false);
  const [showPackingMaterials, setShowPackingMaterials] = useState(false);

  const HOME_SIZES: HomeSize[] = ['Studio', '1', '2', '3', '4+ bedrooms'];
  const MOVERS: MoversCount[] = ['1 Mover', '2 Movers', '3 Movers'];

  const moversCount = parseInt(movers) || 1;

  const updateItemQty = (id: string, qty: number) => {
    if (qty <= 0) setItems(items.filter(i => i.id !== id));
    else setItems(items.map(i => i.id === id ? { ...i, qty } : i));
  };

  const removeItem = (id: string) => setItems(items.filter(i => i.id !== id));

  return (
    <div className="bg-white rounded-2xl shadow-lg p-5 md:p-8">
      <h1 className="text-3xl font-bold text-gray-900 text-center mb-6">
        Start your booking here
      </h1>

      {/* Tabs */}
      <div className="flex rounded-xl bg-gray-100 p-1 mb-6">
        {([['moving_home', 'Moving home'], ['moving_few_items', 'Moving a few items']] as const).map(([t, label]) => (
          <button
            key={t}
            onClick={() => setTab(t)}
            className={`flex-1 py-2.5 rounded-lg text-sm font-medium transition-all ${
              tab === t ? 'bg-blue-600 text-white shadow-sm' : 'text-gray-600 hover:text-gray-900'
            }`}
          >
            {label}
          </button>
        ))}
      </div>

      <div className="space-y-4">
        {/* Addresses */}
        <AddressAutocomplete
          id="pickup-address"
          label="Pick-up address"
          value={pickup}
          onChange={(v) => { setPickup(v); if (!v) setPickupCoords(null); }}
          onSelectWithCoords={(_, lat, lon) => setPickupCoords({ lat, lng: lon })}
          placeholder="Start typing address or postcode..."
        />
        <AddressAutocomplete
          id="destination-address"
          label="Destination address"
          value={destination}
          onChange={(v) => { setDestination(v); if (!v) setDestCoords(null); }}
          onSelectWithCoords={(_, lat, lon) => setDestCoords({ lat, lng: lon })}
          placeholder="Start typing address or postcode..."
        />

        {/* Date — using real DateTimePicker */}
        <div>
          <label className="text-xs font-medium text-gray-500 mb-1.5 block">Date and time slot</label>
          <DateTimePicker
            value={dateTime}
            onChange={(v) => {
              setDateTime(v);
              if (v.storageRequired) {
                setStorageAdded(true);
              }
            }}
            withStorage={withStorage}
          />
        </div>

        {/* Home size + movers (moving home only) */}
        {tab === 'moving_home' && (
          <>
            <div>
              <label className="text-xs font-medium text-gray-500 mb-2 block">Home size</label>
              <div className="flex gap-2 flex-wrap">
                {HOME_SIZES.map(s => (
                  <button
                    key={s}
                    onClick={() => setHomeSize(s)}
                    className={`px-4 py-2 rounded-full text-sm border  transition-all ${
                      homeSize === s
                        ? 'border-blue-600 bg-blue-50 text-blue-700 font-medium'
                        : 'border-gray-200 text-gray-600 hover:border-gray-400'
                    }`}
                  >
                    {s}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <label className="text-xs font-medium text-gray-500 mb-2 block">Movers</label>
              <div className="flex gap-2">
                {MOVERS.map(m => (
                  <button
                    key={m}
                    onClick={() => setMovers(m)}
                    className={`flex-1 py-2.5 rounded-full text-sm border transition-all ${
                      movers === m
                        ? 'border-blue-600 bg-white text-blue-700 font-medium'
                        : 'border-gray-200 text-gray-600 hover:border-gray-400'
                    }`}
                  >
                    {m}
                  </button>
                ))}
              </div>
            </div>
          </>
        )}

        {/* Items flow (moving a few items only) */}
        {tab === 'moving_few_items' && (
          <div>
            {items.length === 0 ? (
              <button
                onClick={() => setShowAddItems(true)}
                className="w-full border-2 border-dashed border-blue-200 bg-blue-50/30 rounded-xl py-4 text-sm font-medium text-blue-600 hover:bg-blue-50 transition-colors"
              >
                + Add items for moving
              </button>
            ) : (
              <div>
                <div className="space-y-4 mb-3">
                  {Object.entries(
                    items.reduce((acc, item) => {
                      const room = item.room || 'Other';
                      if (!acc[room]) acc[room] = [];
                      acc[room].push(item);
                      return acc;
                    }, {} as Record<string, SelectedItem[]>)
                  ).map(([room, roomItems]) => (
                    <div key={room} className="bg-gray-50/50 rounded-xl p-3 border border-gray-100">
                      <h4 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3 px-1">{room}</h4>
                      <div className="space-y-2">
                        {roomItems.map(item => (
                          <div key={item.id} className="flex items-center gap-3 py-1">
                            <div className="w-10 h-10 bg-white rounded-lg flex items-center justify-center text-lg flex-shrink-0 border border-gray-100 shadow-sm">
                              {item.photo || '📦'}
                            </div>
                            <div className="flex-1 min-w-0 flex items-center gap-2">
                              <div>
                                <p className="text-sm font-medium text-gray-800 flex items-center gap-2">
                                  {item.name}
                                  {item.isOversized && <span className="bg-amber-100 text-amber-700 text-[10px] font-bold px-1.5 py-0.5 rounded uppercase">Oversized</span>}
                                </p>
                                <p className="text-xs text-gray-400">{item.volumeM3} m³ · £{item.price}</p>
                              </div>
                            </div>
                            <div className="flex items-center gap-1.5 bg-white border border-gray-200 rounded-lg px-1 py-0.5 shadow-sm">
                              <button onClick={() => updateItemQty(item.id, item.qty - 1)}
                                className="w-6 h-6 flex items-center justify-center text-gray-500 hover:text-gray-900 hover:bg-gray-50 rounded text-xs transition-colors">−</button>
                              <span className="text-sm font-medium w-5 text-center">{item.qty}</span>
                              <button onClick={() => updateItemQty(item.id, item.qty + 1)}
                                className="w-6 h-6 flex items-center justify-center text-gray-500 hover:text-gray-900 hover:bg-gray-50 rounded text-xs transition-colors">+</button>
                            </div>
                            <span className="text-sm font-medium text-gray-700 w-12 text-right">£{(item.price * item.qty).toFixed(0)}</span>
                            <button onClick={() => removeItem(item.id)} className="text-gray-300 hover:text-red-500 transition-colors w-6 h-6 flex items-center justify-center text-lg rounded-full hover:bg-red-50">×</button>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
                <button
                  onClick={() => setShowAddItems(true)}
                  className="text-sm text-blue-600 hover:text-blue-700 font-medium"
                >
                  + Add more items
                </button>
              </div>
            )}
          </div>
        )}

        {/* Extra Information */}
        <div className="pt-4 border-t border-gray-100 space-y-4">
          <div>
            <label className="text-xs font-medium text-gray-500 mb-2 block">Stairs (total flights)</label>
            <div className="flex gap-2 flex-wrap">
              {[0, 1, 2, 3, 4, 5].map(n => (
                <button
                  key={n}
                  onClick={() => setStairsFlights(n)}
                  className={`px-4 py-2 rounded-full text-sm border transition-all ${
                    stairsFlights === n
                      ? 'border-blue-600 bg-blue-50 text-blue-700 font-medium'
                      : 'border-gray-200 text-gray-600 hover:border-gray-400'
                  }`}
                >
                  {n === 0 ? 'None / Lift' : n}
                </button>
              ))}
            </div>
          </div>
          <div>
            <label className="text-xs font-medium text-gray-500 mb-2 block">Parking distance from door</label>
            <div className="flex gap-2 flex-wrap">
              {[
                { label: '0-20m', value: 10 },
                { label: '20-50m', value: 30 },
                { label: '50m+', value: 60 }
              ].map(opt => (
                <button
                  key={opt.value}
                  onClick={() => setParkingDistance(opt.value)}
                  className={`px-4 py-2 rounded-full text-sm border transition-all ${
                    (parkingDistance > 0 && parkingDistance <= 20 && opt.value === 10) ||
                    (parkingDistance > 20 && parkingDistance <= 50 && opt.value === 30) ||
                    (parkingDistance > 50 && opt.value === 60)
                      ? 'border-blue-600 bg-blue-50 text-blue-700 font-medium'
                      : 'border-gray-200 text-gray-600 hover:border-gray-400'
                  }`}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </div>
          <div>
            <label className="text-xs font-medium text-gray-500 mb-2 block">Notes for Driver</label>
            <textarea
              className="w-full border border-gray-200 rounded-lg p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="E.g., call upon arrival, access code, etc."
              rows={2}
              value={notesForDriver}
              onChange={(e) => setNotesForDriver(e.target.value)}
            />
          </div>
        </div>

        {/* Our services accordion */}
        <ServicesAccordion
          tab={tab}
          moversCount={moversCount}
          storageAdded={storageAdded}
          setStorageAdded={setStorageAdded}
          packingAdded={packingAdded}
          setPackingAdded={setPackingAdded}
          materialsAdded={materialsAdded}
          setMaterialsAdded={setMaterialsAdded}
          onOpenMaterials={() => setShowPackingMaterials(true)}
          destination={destination}
          isStorageForced={isStorageForced}
          storageSqft={storageSqft}
          setStorageSqft={setStorageSqft}
          stairsFlights={stairsFlights}
          setStairsFlights={setStairsFlights}
          hasLift={hasLift}
          setHasLift={setHasLift}
          parkingDistance={parkingDistance}
          setParkingDistance={setParkingDistance}
          packingTier={packingTier}
          setPackingTier={setPackingTier}
        />
      </div>

      {/* Modals */}
      <NGLOBAddItemsModal
        open={showAddItems}
        onClose={() => setShowAddItems(false)}
        selectedQtys={items.reduce((acc, item) => ({...acc, [item.id]: item.qty}), {})}
        onConfirm={(confirmed) => {
          const newItems: SelectedItem[] = confirmed.map(c => ({
            id: c.item.id,
            name: c.item.name,
            price: c.item.price,
            volumeM3: c.item.volumeM3,
            widthCm: c.item.widthCm,
            heightCm: c.item.heightCm,
            depthCm: c.item.depthCm,
            qty: c.qty,
            photo: c.item.photo,
            room: 'General',
            isOversized: false,
          }));
          const updatedItems = [...items];
          newItems.forEach(newItem => {
            const existingIndex = updatedItems.findIndex(i => i.id === newItem.id);
            if (existingIndex >= 0) {
              updatedItems[existingIndex].qty += newItem.qty;
            } else {
              updatedItems.push(newItem);
            }
          });
          setItems(updatedItems.filter(i => i.qty > 0));
        }}
      />
      <NGLOBPackingMaterialsModal
        open={showPackingMaterials}
        onClose={() => setShowPackingMaterials(false)}
        onConfirm={() => setMaterialsAdded(true)}
      />
    </div>
  );
}

// ─── Services accordion (below form) ─────────────────────────
interface ServicesAccordionProps {
  tab: BookingTab;
  moversCount: number;
  storageAdded: boolean;
  setStorageAdded: (v: boolean) => void;
  packingAdded: boolean;
  setPackingAdded: (v: boolean) => void;
  materialsAdded: boolean;
  setMaterialsAdded: (v: boolean) => void;
  onOpenMaterials: () => void;
  destination: string;
  isStorageForced: boolean;
  storageSqft: number;
  setStorageSqft: (v: number) => void;
  stairsFlights: number;
  setStairsFlights: (v: number) => void;
  hasLift: boolean;
  setHasLift: (v: boolean) => void;
  parkingDistance: number;
  setParkingDistance: (v: number) => void;
  packingTier?: any;
  setPackingTier?: (t: any) => void;
}

function ServicesAccordion({
  tab, moversCount, storageAdded, setStorageAdded,
  packingAdded, setPackingAdded, materialsAdded, setMaterialsAdded,
  onOpenMaterials, destination, isStorageForced, storageSqft, setStorageSqft,
  stairsFlights, setStairsFlights, hasLift, setHasLift, parkingDistance, setParkingDistance,
  packingTier, setPackingTier
}: ServicesAccordionProps) {
  const [open, setOpen] = useState<string | null>(null);
  const [returnAddress, setReturnAddress] = useState(destination || '');

  // Update return address when destination changes
  useEffect(() => {
    if (destination) setReturnAddress(destination);
  }, [destination]);

  const services = [
    {
      id: 'storage',
      title: 'Storage',
      subtitle: 'From £40 per week for 1-bedroom home',
    },
    ...(tab === 'moving_home' ? [{
      id: 'packing',
      title: 'Full packing service',
      subtitle: 'From £250 for 1-bedroom home, done in 2 hours',
    }] : []),
    {
      id: 'materials',
      title: 'Packing materials',
      subtitle: 'In case you need spare materials on the moving day',
    },
  ];

  return (
    <div className="border-t border-gray-100 pt-4 mt-2">
      <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-3">Our services</p>
      <div className="space-y-1">
        {services.map(svc => (
          <div key={svc.id} className="border border-gray-100 rounded-xl overflow-hidden">
            <button
              onClick={() => setOpen(open === svc.id ? null : svc.id)}
              className="w-full flex items-center justify-between px-4 py-3.5 text-left hover:bg-gray-50 transition-colors"
            >
              <div>
                <p className="text-sm font-medium text-gray-800">{svc.title}</p>
                <p className="text-xs text-gray-400 mt-0.5">{svc.subtitle}</p>
              </div>
              <svg
                className={`w-4 h-4 text-gray-400 transition-transform ${open === svc.id ? 'rotate-180' : ''}`}
                fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}
              >
                <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7"/>
              </svg>
            </button>

            {/* Expanded content */}
            {open === svc.id && svc.id === 'storage' && (
              <StorageAccordionExpanded
                sqft={storageSqft}
                onSqftChange={setStorageSqft}
                returnAddress={returnAddress}
                onReturnAddressChange={setReturnAddress}
                added={storageAdded}
                onAdd={() => setStorageAdded(true)}
                onRemove={() => {
                  if (isStorageForced) {
                    alert('Storage is required because pickup and delivery are on different dates.');
                    return;
                  }
                  setStorageAdded(false);
                }}
              />
            )}
            {open === svc.id && svc.id === 'packing' && (
              <div className="px-4 pb-4 border-t border-gray-50">
                <PackingServicePanel
                  moversCount={moversCount}
                  confirmed={packingAdded}
                  onConfirm={() => setPackingAdded(true)}
                  onRemove={() => setPackingAdded(false)}
                  onUpdate={() => {}}
                  stairsFlights={stairsFlights}
                  setStairsFlights={setStairsFlights}
                  hasLift={hasLift}
                  setHasLift={setHasLift}
                  parkingDistance={parkingDistance}
                  setParkingDistance={setParkingDistance}
                  tier={packingTier || 'FULL'}
                  setTier={setPackingTier || (() => {})}
                />
              </div>
            )}
            {open === svc.id && svc.id === 'materials' && (
              <div className="px-4 pb-4 text-sm text-gray-500 leading-relaxed border-t border-gray-50">
                <p className="pt-3">Save your time, we'll deliver materials for you. Medium boxes, large boxes, bubble wrap, paper rolls, tape — order any combination.</p>
                <button onClick={onOpenMaterials} className="mt-3 text-blue-600 text-sm font-medium hover:text-blue-700">
                  Add packing materials →
                </button>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

// ─── Quote panel (hero right) ────────────────────────────────
interface QuotePanelProps {
  tab: BookingTab;
  pickup: string;
  destination: string;
  homeSize: HomeSize;
  movers: MoversCount;
  items: SelectedItem[];
  preparing: boolean;
  ready: boolean;
  storageAdded: boolean;
  packingAdded: boolean;
  onPayNow: () => void;
  quoteData: any;
  storageDays?: number;
  dateTime?: any;
  /** User-chosen duration in minutes (pickup slot start → delivery slot end) */
  bookedDurationMins?: number;
  materialsAdded?: boolean;
  storageSqft?: number;
  pickupCoords?: any;
  destCoords?: any;
}

function QuotePanel({ tab, pickup, destination, homeSize, movers, items, preparing, ready, storageAdded, packingAdded, onPayNow, quoteData, storageDays, dateTime, materialsAdded, storageSqft, pickupCoords, destCoords, bookedDurationMins }: QuotePanelProps) {
  if (!preparing && !ready) {
    return (
      <div className="bg-stone-50 rounded-3xl overflow-hidden p-6 lg:p-10 h-full flex flex-col justify-center min-h-[400px]">
        <div className="relative w-full aspect-square rounded-2xl overflow-hidden shadow-md mx-auto max-w-md">
          <div className="absolute inset-0 bg-cover bg-center" style={{ backgroundImage: "url('/images/hero_home_move_1777334642122.png')" }} />
          <div className="absolute  top-0 left-0 h-full w-full bg-black/30"></div>
          <div className="absolute  top-8 left-8">
            <p className="text-white font-bold text-2xl leading-tight drop-shadow-sm">We can move your home</p>
            <p className="text-white text-sm mt-1 font-medium drop-shadow-sm">from £180 per studio</p>
          </div>
        </div>
      </div>
    );
  }

  if (preparing || !quoteData) {
    return (
      <div className="bg-white border border-gray-200 rounded-3xl p-8 shadow-sm">
        <p className="font-bold text-gray-900 mb-2">Preparing your quote</p>
        <p className="text-sm text-gray-500 mb-6">Calculating real-time distance and costs. Almost done…</p>
        <div className="h-2 bg-gray-100 rounded-full overflow-hidden">
          <div className="h-full bg-blue-600 rounded-full animate-pulse" style={{ width: '60%' }} />
        </div>

        {/* Save money card */}
        <div className="mt-8 border border-gray-100 rounded-2xl p-5 flex items-start gap-4">
          <div className="w-10 h-10 bg-blue-50 rounded-full flex items-center justify-center flex-shrink-0 text-lg">💰</div>
          <div className="flex-1">
            <p className="text-sm font-bold text-gray-900 mb-1">Save money with deals</p>
            <p className="text-xs text-gray-500 mb-3">Register and unlock member deals and rewards</p>
            <button className="text-xs font-semibold text-blue-600 hover:text-blue-700 transition-colors">
              How it works →
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (tab === 'moving_home') {
    return (
      <div className="bg-white border border-gray-200 rounded-2xl p-6">
        <p className="font-semibold text-gray-900 mb-4">Your quote</p>
        <div className="space-y-3 mb-4 text-sm">
          <div className="flex justify-between">
            <span className="text-gray-600">
              {(() => {
                if (bookedDurationMins && bookedDurationMins > 0) {
                  const hrs = Math.floor(bookedDurationMins / 60);
                  const mins = bookedDurationMins % 60;
                  const label = hrs > 0 && mins > 0 ? `${hrs} hr ${mins} min` : hrs > 0 ? `${hrs} hr` : `${mins} min`;
                  return `Booked window: ${label}`;
                }
                return `Estimated booking time ${quoteData.totalDurationDisplay || ''}`;
              })()}
            </span>
            <button className="text-blue-600 text-xs">Time calculation</button>
          </div>
          <div className="flex justify-between">
            <span className="text-gray-600">{movers} & Medium van</span>
            <span className="font-medium">£{quoteData.baseCost + quoteData.additionalMoverCost}</span>
          </div>
          <div className="flex justify-between">
            <span className="text-gray-600">Mileage (Distance)</span>
            <span className="font-medium">£{quoteData.fuelCost}</span>
          </div>
          {packingAdded && (
            <div className="flex justify-between">
              <span className="text-gray-600">Full packing service</span>
              <span className="font-medium">£{quoteData.fullPackingCost}</span>
            </div>
          )}
          {materialsAdded && !packingAdded && (
            <div className="flex justify-between">
              <span className="text-gray-600">Packing materials</span>
              <span className="font-medium">£{quoteData.materialsCost ?? quoteData.packingMaterialsCost ?? 0}</span>
            </div>
          )}
          {storageAdded && (
            <div className="flex justify-between text-gray-400">
              <span>Storage {storageDays ? `(${storageDays} days)` : ''}</span>
              <span>£{quoteData.storageCost}</span>
            </div>
          )}
        </div>
        <div className="border-t border-gray-100 pt-3 flex justify-between font-semibold text-base mb-4">
          <span>Estimated total cost</span>
          <span>£{quoteData.totalToPay}</span>
        </div>
        <button onClick={onPayNow} className="w-full bg-blue-600 text-white py-3 rounded-xl font-medium hover:bg-blue-700 transition-colors">
          Pay now
        </button>

        {/* Save money card */}
        <div className="mt-4 border border-gray-100 rounded-xl p-4 flex items-start gap-3">
          <div className="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center flex-shrink-0 text-sm">💰</div>
          <div className="flex-1">
            <p className="text-sm font-medium text-gray-800">Save money with deals</p>
            <p className="text-xs text-gray-400">Register and unlock member deals and rewards</p>
          </div>
          <button className="text-xs border border-gray-200 text-gray-600 px-3 py-1.5 rounded-lg hover:border-gray-400 whitespace-nowrap">
            How it works
          </button>
        </div>
      </div>
    );
  }

  // Items mode quote
  const totalItemCount = items.reduce((a, i) => a + i.qty, 0);

  return (
    <div className="bg-white border border-gray-200 rounded-2xl p-6">
      <p className="font-semibold text-gray-900 mb-4">Your quote</p>
      <div className="space-y-3 mb-4 text-sm">
        <div className="flex justify-between">
          <span className="text-gray-600">Mileage (Distance)</span>
          <span className="font-medium">£{quoteData.fuelCost}</span>
        </div>
        <div className="flex justify-between">
          <span className="text-gray-600">Items ({totalItemCount} item{totalItemCount !== 1 ? 's' : ''})</span>
          <span className="font-medium">£{quoteData.baseCost}</span>
        </div>
      </div>
      <div className="border-t border-gray-100 pt-3 flex justify-between font-semibold text-base mb-4">
        <span>Estimated total</span>
        <span>£{quoteData.totalToPay}</span>
      </div>
      <button onClick={onPayNow} className="w-full bg-blue-600 text-white py-3 rounded-xl font-medium hover:bg-blue-700 transition-colors">
        Book now
      </button>

      <button 
        onClick={async () => {
          const token = getAccessToken();
          if (!token) {
            alert('Please log in first to save your quote.');
            return;
          }
          try {
            await fetch(`${process.env.API_URL}/quotes/draft`, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                Authorization: `Bearer ${token}`
              },
              body: JSON.stringify({
                stateData: JSON.stringify({
                  tab,
                  pickup,          // R1-15: resume reads state.pickup (not state.pickupAddress)
                  destination,     // R1-15: resume reads state.destination
                  homeSize,
                  movers,
                  items,
                  storageAdded,
                  packingAdded,
                  dateTime,        // R1-15: include date so quote can reprice
                  materialsAdded,
                  storageSqft,
                  storageWeeks: dateTime?.storageWeeks,
                  pickupCoords,
                  destCoords,
                }),
                pickup,
                destination,
                totalPrice: quoteData.totalToPay
              })
            });
            alert('Quote saved successfully! You can resume it from your account later.');
          } catch (e) {
            alert('Failed to save quote.');
          }
        }}
        className="w-full mt-3 border-2 border-gray-900 bg-white text-gray-900 py-3 rounded-xl font-bold text-sm tracking-wide shadow-sm hover:bg-gray-50 transition-colors"
      >
        Save quote for later
      </button>
    </div>
  );
}

