// ─── Page ────────────────────────────────────────────────────
export default function HomePage() {
  const [tab, setTab] = useState<BookingTab>('moving_home');
  const [pickup, setPickup] = useState('');
  const [destination, setDestination] = useState('');
  const [dateTime, setDateTime] = useState<{ date: string; pickupSlot: TimeSlot; deliveryDate?: string; deliverySlot?: string; exactTime?: string; exactDeliveryTime?: string; storageDays?: number; storageWeeks?: number; storageRequired?: boolean; durationMins?: number } | null>(null);
  const [homeSize, setHomeSize] = useState<HomeSize>('1');
  const [movers, setMovers] = useState<MoversCount>('1 Mover');
  const [items, setItems] = useState<SelectedItem[]>([]);
  const [storageAdded, setStorageAdded] = useState(false);
  const [storageSqft, setStorageSqft] = useState(75);
  const [packingAdded, setPackingAdded] = useState(false);
  const [materialsAdded, setMaterialsAdded] = useState(false);

  const [preparing, setPreparing] = useState(false);
  const [quoteReady, setQuoteReady] = useState(false);
  const [checkoutOpen, setCheckoutOpen] = useState(false);
  const [checkoutSummary, setCheckoutSummary] = useState({ subtotal: 0, vat: 0, total: 0 });
  const [stairsFlights, setStairsFlights] = useState(0);
  const [hasLift, setHasLift] = useState(false);
  const [parkingDistance, setParkingDistance] = useState(10);
  const [notesForDriver, setNotesForDriver] = useState('');
  const router = useRouter();

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const draftId = urlParams.get('resumeDraft');

    if (draftId) {
      const token = getAccessToken();
      if (token) {
        fetch(`${process.env.API_URL}/quotes/drafts/${draftId}`, {
          headers: { Authorization: `Bearer ${token}` }
        })
        .then(res => res.ok ? res.json() : null)
        .then(draft => {
          if (draft && draft.stateData) {
            try {
              const state = JSON.parse(draft.stateData);
              if (state.pickup || state.pickupAddress) setPickup(state.pickup || state.pickupAddress);
              if (state.destination || state.destinationAddress) setDestination(state.destination || state.destinationAddress);
              if (state.homeSize) setHomeSize(state.homeSize);
              if (state.movers) setMovers(state.movers);
              if (state.items) setItems(state.items);
              if (state.notesForDriver) setNotesForDriver(state.notesForDriver);
              if (state.tab) setTab(state.tab);
              if (state.storageAdded !== undefined) setStorageAdded(state.storageAdded);
              if (state.packingAdded !== undefined) setPackingAdded(state.packingAdded);
              if (state.dateTime) setDateTime(state.dateTime);
            } catch(e) {
              console.error('Failed to parse draft state');
            }
          }
        })
        .catch(err => console.error('Error fetching draft:', err));
      }
    }
  }, []);

  const [pickupCoords, setPickupCoords] = useState<{ lat: number; lng: number } | null>(null);
  const [destCoords, setDestCoords] = useState<{ lat: number; lng: number } | null>(null);
  const [quoteData, setQuoteData] = useState<any>(null);
  const [distanceKm, setDistanceKm] = useState<number>(20);

  const isStorageForced = dateTime?.storageRequired === true;
  const effectiveStorageAdded = storageAdded || isStorageForced;

  // Auto calculate quote via backend
  useEffect(() => {
    if (pickupCoords && destCoords) {
      setPreparing(true);
      setQuoteReady(false);

      const fetchPrice = async () => {
        try {
          const route = await getDrivingDistance(pickupCoords, destCoords);

          if (!route) {
            alert('Unable to calculate a valid route. Please check the addresses and try again.');
            throw new Error("Route not found");
          }

          const dist = route.distanceMeters / 1000;
          setDistanceKm(dist);

          const mappedHomeSize = homeSize === 'Studio' ? 'STUDIO' : 
                                 homeSize === '1' ? 'ONE' : 
                                 homeSize === '2' ? 'TWO' : 
                                 homeSize === '3' ? 'THREE' : 'FOUR_PLUS';

          const res = await fetch(`${process.env.API_URL}/pricing/calculate`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              pickupAddress: pickup || 'Unknown Pickup',
              destinationAddress: destination || 'Unknown Destination',
              pickupLat: pickupCoords.lat,
              pickupLng: pickupCoords.lng,
              destLat: destCoords.lat,
              destLng: destCoords.lng,
              homeSize: tab === 'moving_home' ? mappedHomeSize : undefined,
              moversCount: parseInt(movers[0]) || 1,
              extras: packingAdded ? 'FULL_PACKING' : materialsAdded ? 'MATERIALS_ONLY' : 'NONE',
              withStorage: effectiveStorageAdded,
              storageSqft: storageSqft,
              bookedDurationMins: dateTime?.durationMins || undefined,
              storageDays: dateTime?.storageDays,
              storageWeeks: dateTime?.storageWeeks,
              exactPickupTime: dateTime?.exactTime || undefined,
              stairsFlights: stairsFlights,
              parkingDistance: parkingDistance,
              items: tab === 'moving_few_items' ? items.map(i => ({
                volumeM3: i.volumeM3 || 0.1,
                quantity: i.qty,
              })) : [],
            })
          });

          if (res.ok) {
            const data = await res.json();
            setQuoteData(data);
          }
        } catch (e) {
          console.error("Price estimation failed", e);
        } finally {
          setPreparing(false);
          setQuoteReady(true);
        }
      };

      const t = setTimeout(() => fetchPrice(), 1000);
      return () => clearTimeout(t);
    } else {
      setPreparing(false);
      setQuoteReady(false);
      setQuoteData(null);
    }
  }, [pickupCoords, destCoords, tab, homeSize, movers, items, packingAdded, materialsAdded, effectiveStorageAdded, storageSqft, dateTime?.storageDays, dateTime?.storageWeeks, dateTime?.exactTime, dateTime?.pickupSlot, dateTime?.deliverySlot, dateTime?.durationMins, stairsFlights, parkingDistance]);

  const initPayment = async (isDeposit: boolean, existingBookingId: string | null) => {
    const token = getAccessToken();
    if (!token) throw new Error("Not logged in");

    let bId = existingBookingId;

    if (!bId) {
      const mappedHomeSize = homeSize === 'Studio' ? 'STUDIO' : 
                             homeSize === '1' ? 'ONE' : 
                             homeSize === '2' ? 'TWO' : 
                             homeSize === '3' ? 'THREE' : 'FOUR_PLUS';

      const mapSlotToBackend = (slot?: string) => {
        if (slot === '08:00 - 12:00') return 'SLOT_08_12';
        if (slot === '10:00 - 14:00') return 'SLOT_10_14';
        if (slot === '12:00 - 16:00') return 'SLOT_12_16';
        if (slot === '14:00 - 18:00') return 'SLOT_14_18';
        if (slot === '16:00 - 20:00') return 'SLOT_16_20';
        return 'SLOT_08_12';
      };

      const res = await fetch(`${process.env.API_URL}/bookings`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({
          type: tab === 'moving_home' ? 'FULL_HOUSE' : 'FEW_ITEMS',
          pickupAddress: pickup,
          destinationAddress: destination,
          pickupLat: pickupCoords?.lat,
          pickupLng: pickupCoords?.lng,
          destLat: destCoords?.lat,
          destLng: destCoords?.lng,
          pickupDate: dateTime ? new Date(dateTime.date).toISOString() : new Date().toISOString(),
          pickupTimeSlot: dateTime?.exactTime ? 'EXACT' : mapSlotToBackend(dateTime?.pickupSlot),
          exactPickupTime: dateTime?.exactTime || undefined,
          homeSize: tab === 'moving_home' ? mappedHomeSize : undefined,
          moversCount: parseInt(movers[0]) || 1,
          extras: packingAdded ? 'FULL_PACKING' : 'MATERIALS_ONLY',
          withStorage: effectiveStorageAdded,
          stairsFlights,
          parkingDistance,
          notesForDriver,
          ...(effectiveStorageAdded ? { storageSqft: storageSqft, storageDays: dateTime?.storageDays, storageWeeks: dateTime?.storageWeeks } : {}),
          items: items.map(i => ({ 
            name: i.name, 
            category: 'DECOR_OTHER', 
            widthCm: i.widthCm || 50, 
            heightCm: i.heightCm || 50, 
            depthCm: i.depthCm || 50, 
            quantity: i.qty,
            isAiScanned: i.isAiScanned || false,
            photoUrl: i.photoUrl || undefined
          })),
          photoScanUrl: items.find(i => i.isAiScanned && i.photoUrl)?.photoUrl || undefined
        })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || 'Failed to create booking');
      bId = data.booking.id;
    }

    const intentRes = await fetch(`${process.env.API_URL}/payments/intent`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`
      },
      body: JSON.stringify({ bookingId: bId, isDeposit })
    });
    const intentData = await intentRes.json();
    if (!intentRes.ok) throw new Error(intentData.message || 'Failed to initialize payment');

    return { clientSecret: intentData.clientSecret, bookingId: bId! };
  };

  const handlePaymentSuccess = (bookingId: string) => {
    setCheckoutOpen(false);
    router.push(`/app/confirmation?bookingId=${bookingId}`);
  };

  return (
    <div className="flex-1 flex flex-col bg-white">

      {/* Hero section */}
      <section className="pt-16 lg:pt-24 pb-16 px-6 bg-white">
        <div className="max-w-7xl mx-auto grid lg:grid-cols-2 gap-10 items-start">
          <BookingHeroForm
            tab={tab} setTab={setTab}
            pickup={pickup} setPickup={setPickup}
            destination={destination} setDestination={setDestination}
            setPickupCoords={setPickupCoords}
            setDestCoords={setDestCoords}
            dateTime={dateTime} setDateTime={setDateTime}
            homeSize={homeSize} setHomeSize={setHomeSize}
            movers={movers} setMovers={setMovers}
            items={items} setItems={setItems}
            storageAdded={effectiveStorageAdded} setStorageAdded={setStorageAdded}
            packingAdded={packingAdded} setPackingAdded={setPackingAdded}
            materialsAdded={materialsAdded} setMaterialsAdded={setMaterialsAdded}
            withStorage={effectiveStorageAdded}
            isStorageForced={isStorageForced}
            storageSqft={storageSqft}
            setStorageSqft={setStorageSqft}
            stairsFlights={stairsFlights} setStairsFlights={setStairsFlights}
            hasLift={hasLift} setHasLift={setHasLift}
            parkingDistance={parkingDistance} setParkingDistance={setParkingDistance}
            notesForDriver={notesForDriver} setNotesForDriver={setNotesForDriver}
          />
          <div className="md:sticky md:top-24">
            <QuotePanel
              tab={tab}
              pickup={pickup}
              destination={destination}
              homeSize={homeSize}
              movers={movers}
              items={items}
              preparing={preparing}
              ready={quoteReady}
              storageAdded={effectiveStorageAdded}
