// ─── Types ───────────────────────────────────────────────────
type BookingTab = 'moving_home' | 'moving_few_items';
type HomeSize = 'Studio' | '1' | '2' | '3' | '4+';
type MoversCount = '1 Mover' | '2 Movers' | '3 Movers';

interface SelectedItem {
  id: string;
  name: string;
  price: number;
  volumeM3: number;
  widthCm?: number;
  heightCm?: number;
  depthCm?: number;
  qty: number;
  photo: string;
}

function getBookingItemDimensions(item: SelectedItem) {
  if (item.widthCm && item.heightCm && item.depthCm) {
    return { widthCm: item.widthCm, heightCm: item.heightCm, depthCm: item.depthCm };
  }

  const sideCm = Math.max(1, Math.round(Math.cbrt((item.volumeM3 || 0.1) * 1_000_000)));
  return { widthCm: sideCm, heightCm: sideCm, depthCm: sideCm };
}

// ─── Booking form (hero left side) ───────────────────────────
interface BookingFormProps {
  tab: BookingTab;
  setTab: (t: BookingTab) => void;
  pickup: string;
  setPickup: (v: string) => void;
  destination: string;
  setDestination: (v: string) => void;
  pickupCoords: { lat: number; lng: number } | null;
  setPickupCoords: (c: { lat: number; lng: number } | null) => void;
  destCoords: { lat: number; lng: number } | null;
  setDestCoords: (c: { lat: number; lng: number } | null) => void;
  dateTime: { date: string; pickupSlot: TimeSlot; deliveryDate?: string; deliverySlot?: string; exactTime?: string; exactDeliveryTime?: string; durationMins?: number } | null;
  setDateTime: (v: { date: string; pickupSlot: TimeSlot; deliveryDate?: string; deliverySlot?: string; exactTime?: string; exactDeliveryTime?: string; durationMins?: number } | null) => void;
  homeSize: HomeSize;
  setHomeSize: (v: HomeSize) => void;
  movers: MoversCount;
  setMovers: (v: MoversCount) => void;
  items: SelectedItem[];
  setItems: (v: SelectedItem[]) => void;
  withStorage: boolean;
  onOpenAddItems: () => void;
  onDatePickerOpenChange?: (isOpen: boolean) => void;
  specialInstructions: string;
  setSpecialInstructions: (v: string) => void;
  storageSqft?: number;
  storageDays?: number;
  storageWeeks?: number;
  setStorageWeeks?: (v: number) => void;
  storageRequired?: boolean;
  mobileStep?: number;
}

function BookingHeroForm(props: BookingFormProps) {
  const { prices } = usePrices();
  const {
    tab, setTab, pickup, setPickup, destination, setDestination,
    pickupCoords, setPickupCoords, destCoords, setDestCoords,
    dateTime, setDateTime, homeSize, setHomeSize, movers, setMovers,
    items, setItems, withStorage, onOpenAddItems, onDatePickerOpenChange,
    specialInstructions, setSpecialInstructions,
    storageSqft, storageDays, storageWeeks, storageRequired
  } = props;

  useEffect(() => {
    if (storageRequired && storageDays && storageDays > 0) {
      const minW = Math.max(1, Math.ceil(storageDays / 7));
      if (storageWeeks !== undefined && storageWeeks < minW && props.setStorageWeeks) {
        props.setStorageWeeks(minW);
      }
    }
  }, [storageRequired, storageDays, storageWeeks, props]);

  const HOME_SIZES: HomeSize[] = ['Studio', '1', '2', '3', '4+'];
  const MOVERS: MoversCount[] = ['1 Mover', '2 Movers', '3 Movers'];

  const moversCount = parseInt(movers) || 1;
  const storagePricePerWeek = Math.round((storageSqft || 0) * prices.storageRatePerSqftPerWeek * 10) / 10;
  const storagePrice = Math.round(storagePricePerWeek * (storageWeeks || 1) * 10) / 10;

  const updateItemQty = (id: string, qty: number) => {
    if (qty <= 0) setItems(items.filter(i => i.id !== id));
    else setItems(items.map(i => i.id === id ? { ...i, qty } : i));
  };

  const removeItem = (id: string) => setItems(items.filter(i => i.id !== id));

  let currentStep = 1;
  if (pickupCoords) currentStep = 2;
  if (pickupCoords && destCoords) currentStep = 3;
  if (pickupCoords && destCoords && dateTime) currentStep = 4;

  const [locationLoading, setLocationLoading] = useState(false);
  const [locationError, setLocationError] = useState('');

  const useCurrentLocation = () => {
    if (!navigator.geolocation) {
      setLocationError('Location is not supported by this browser.');
      return;
    }

    setLocationLoading(true);
    setLocationError('');
    navigator.geolocation.getCurrentPosition(async ({ coords }) => {
      try {
        const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${coords.latitude}&lon=${coords.longitude}&zoom=18&addressdetails=1`, {
          headers: { 'Accept-Language': 'en' }
        });
        const data = await response.json();
        setPickup(data.display_name || `${coords.latitude.toFixed(5)}, ${coords.longitude.toFixed(5)}`);
        setPickupCoords({ lat: coords.latitude, lng: coords.longitude });
      } catch {
        setLocationError('Could not turn your location into an address.');
      } finally {
        setLocationLoading(false);
      }
    }, () => {
      setLocationLoading(false);
      setLocationError('Please allow location access to use this.');
    }, { enableHighAccuracy: true, timeout: 10000, maximumAge: 300000 });
  };

  const getStepWrapperClass = (step: number) => {
    return 'relative transition-all duration-500 ease-[cubic-bezier(0.32,0.72,0,1)]';
  };

  const getInputHighlightClass = (step: number) => {
    if (currentStep === step) {
      // Glow animation handled by tailwind animation class defined in style tag
      return 'ring-2 ring-[#5993CC] ring-offset-2 ring-offset-[#ffffff] border-[#5993CC] animate-pulse-glow z-20 relative';
    }
    return '';
  };

  useEffect(() => {
    const container = document.getElementById('left-scroll-container');
    const stepEl = document.getElementById(`booking-step-${currentStep}`);
    if (container && stepEl && currentStep > 1) {
      gsap.to(container, {
        scrollTop: stepEl.offsetTop - 32, // Offset for padding
        duration: 0.8,
        ease: 'power3.out',
        overwrite: 'auto'
      });
    }
  }, [currentStep]);

  return (
    <div>
      <div className="space-y-6">
        {/* Step 1: Pick-up */}
        {(!props.mobileStep || props.mobileStep === 1) && (
          <div id="booking-step-1" className={getStepWrapperClass(1)}>
            <div className="flex justify-between items-center ">
              <label className="text-[14px] font-semibold text-[#071A3A] px-1">Collection address</label>
            </div>
            {locationError && <p className="px-1 mt-2 text-xs font-medium text-red-500">{locationError}</p>}
            <AddressAutocomplete
              id="pickup-address"
              label=""
              value={pickup}
              onChange={(v) => { setPickup(v); if (!v) setPickupCoords(null); }}
              onSelectWithCoords={(_, lat, lon) => setPickupCoords({ lat, lng: lon })}
              placeholder="Start typing address or postcode..."
              className={" bg-white border-[#DDE4EE] rounded-[20px]"}
            />
          </div>
        )}

        {/* Storage Pit Stop (if storage is added or required) */}
        {(!props.mobileStep || props.mobileStep === 1) && (withStorage || storageRequired) && (
          <div className="mb-3  animate-in fade-in slide-in-from-top-2 duration-300">
            <div className="flex items-center justify-between mb-2">
              <h4 className="text-[13px] font-bold text-[#071A3A]">Storage facility</h4>
              <span className="flex items-center gap-1 text-[12px] font-semibold text-[#735487]">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M20 6L9 17l-5-5" />
                </svg>
                Added
              </span>
            </div>

            <div className="flex items-center gap-3 bg-[#735487]/10 rounded-[16px] px-4 py-3 border border-[#DDE4EE]">
              <div className="w-10 h-10 rounded-xl bg-white border border-[#DDE4EE] flex items-center justify-center text-[#735487] flex-shrink-0">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M3 21h18M4 21V9l8-6 8 6v12M9 21v-6h6v6" />
                </svg>
              </div>
              <div className="flex flex-col">
                <p className="text-[14px] font-bold text-[#071A3A] leading-tight">
                  Nglob Secure Facility
                </p>
                <p className="text-[12px] text-[#667085] font-medium leading-tight">
                  {storageSqft} sq ft · {storageRequired ? `${storageDays} days` : `${storageWeeks} week${(storageWeeks ?? 1) > 1 ? 's' : ''}`} · £{storagePrice}
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Step 2: Destination */}
        {(!props.mobileStep || props.mobileStep === 1) && (
          <div id="booking-step-2" className={getStepWrapperClass(2)}>
            <label className="text-[14px] font-semibold text-[#071A3A] block px-1">Delivery address</label>
            <AddressAutocomplete
              id="destination-address"
              label=""
              value={destination}
              onChange={(v) => { setDestination(v); if (!v) setDestCoords(null); }}
              onSelectWithCoords={(_, lat, lon) => setDestCoords({ lat, lng: lon })}
              placeholder="Start typing address or postcode..."
              className={" bg-white border-[#DDE4EE] rounded-[20px]"}
            />
          </div>
        )}

        {/* Step 3: Date */}
        {(!props.mobileStep || props.mobileStep === 1) && (
          <div id="booking-step-3" className={getStepWrapperClass(3)}>
            <label className="text-[14px] font-semibold text-[#071A3A] block px-1">Date & time window</label>
            <DateTimePicker
              value={dateTime}
              onChange={(v) => setDateTime(v)}
              withStorage={withStorage}
              className={" bg-white border-[#DDE4EE] rounded-[20px]"}
              onOpenChange={onDatePickerOpenChange}
            />
          </div>
        )}

        {/* Step 4: Home size + movers (moving home only) */}
        {(!props.mobileStep || props.mobileStep === 2) && tab === 'moving_home' && (
          <div id="booking-step-4" className={"space-y-5 sticky bottom-0 bg-white z-20 pb-4 pt-4 "}>
            <div>
              <label className="text-[13px] font-semibold text-[#86868b] uppercase tracking-wide mb-3 block px-1">Home size</label>
              <div className="flex gap-2 overflow-x-auto pb-2 -mx-4 px-4 sm:mx-0 sm:px-0 no-scrollbar snap-x">
                {HOME_SIZES.map(s => (
                  <button
                    key={s}
                    onClick={() => setHomeSize(s)}
                    className={`flex-shrink-0 snap-start px-5 py-3 rounded-[16px] text-[14px] transition-all duration-300 border shadow-sm ${homeSize === s
                      ? 'border-[#3F78B1] bg-[#E6F0FF] text-[#3F78B1] font-bold ring-1 ring-[#3F78B1]'
                      : 'border-[#DDE4EE] bg-white text-[#667085] hover:border-[#3F78B1] hover:text-[#071A3A]'
                      }`}
                  >
                    {s}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <div className="flex justify-between items-center px-1 mt-4 mb-3">
                <label className="text-[13px] font-semibold text-[#86868b] uppercase tracking-wide block">Crew</label>
                <span className="text-[11px] font-medium text-[#94A3B8] bg-[#F4F8FF] px-2 py-0.5 rounded-full">Included in item prices</span>
              </div>
              <div className="grid grid-cols-3 gap-2">
                {MOVERS.map(m => {
                  const num = m.charAt(0);
                  const label = m === '1 Mover' ? '1 Mover' : m === '2 Movers' ? '2 Movers' : '3 Movers';

                  return (
                    <button
                      key={m}
                      onClick={() => setMovers(m)}
                      className={`flex flex-col items-center justify-center py-3.5 px-1 rounded-[16px] text-center border transition-all duration-300 shadow-sm ${movers === m
                        ? 'border-[#3F78B1] bg-[#E6F0FF] text-[#3F78B1] ring-1 ring-[#3F78B1]'
                        : 'border-[#DDE4EE] bg-white text-[#667085] hover:border-[#3F78B1] hover:bg-[#F8FAFC]'
                        }`}
                    >
                      <div className="flex -space-x-1 mb-1.5 opacity-80">
                        {Array.from({ length: parseInt(num) }).map((_, i) => (
                          <div key={i} className={`w-5 h-5 rounded-full border-2 ${movers === m ? 'border-[#E6F0FF] bg-[#3F78B1]' : 'border-white bg-[#CBD5E1]'}`}>
                            <svg viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2.5" className="w-full h-full p-0.5">
                              <path strokeLinecap="round" strokeLinejoin="round" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                            </svg>
                          </div>
                        ))}
                      </div>
                      <div className={`text-[12px] font-bold ${movers === m ? 'text-[#3F78B1]' : 'text-[#071A3A]'}`}>{label}</div>
                    </button>
                  );
                })}
              </div>
            </div>
          </div>
        )}

        {/* Step 4: Items flow (moving a few items only) */}
        {(!props.mobileStep || props.mobileStep === 2) && tab === 'moving_few_items' && (
          <div id="booking-step-4" className={getStepWrapperClass(4) + " sticky bottom-0 bg-white z-20 pb-4 pt-4 border-t border-[#DDE4EE] mt-4"}>
            <div className="p-5 bg-[#F4F8FF] rounded-[20px] border border-[#DDE4EE] flex items-center justify-between">
              <div>
                <h4 className="text-[14px] font-bold text-[#071A3A] mb-1">Select your items</h4>
                <p className="text-[12px] text-[#667085]">Add items on the right panel to continue.</p>
              </div>
              <div className="w-10 h-10 bg-white rounded-full shadow-[0_2px_8px_rgba(7,26,58,0.08)] flex items-center justify-center text-[#3F78B1]">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14M12 5l7 7-7 7" /></svg>
              </div>
            </div>
          </div>
        )}

      </div>

      {(!props.mobileStep || props.mobileStep === 2) && (
        <div className="mt-6">
          <label className="text-[14px] font-semibold text-[#071A3A]  block px-1">Notes for the crew (optional)</label>

          <div className="relative">
            <textarea
              value={specialInstructions}
              onChange={e => setSpecialInstructions(e.target.value.slice(0, 200))}
              placeholder="Fragile items, access or special instructions..."
              className="w-full h-28 bg-white border border-[#DDE4EE] rounded-[20px] p-4 text-[14px] text-[#071A3A] placeholder:text-[#94A3B8] focus:outline-none focus:border-[#3F78B1] focus:ring-1 focus:ring-[#DDE4EE] resize-none transition-all"
            />
            <div className="absolute bottom-3 left-4 text-[12px] text-gray-500 flex items-center gap-1">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 6L9 17l-5-5" /></svg>
              Saved automatically
            </div>
            <div className="absolute bottom-3 right-4 text-[12px] text-gray-400">
              {specialInstructions.length} / 200
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

