function FewItemsConfigOnly(props: {
  items: SelectedItem[];
  setItems: (items: SelectedItem[]) => void;
  onOpenAddItems: () => void;
}) {
  const updateItemQty = (id: string, qty: number) => {
    if (qty <= 0) props.setItems(props.items.filter(i => i.id !== id));
    else props.setItems(props.items.map(i => i.id === id ? { ...i, qty } : i));
  };

  const removeItem = (id: string) => props.setItems(props.items.filter(i => i.id !== id));

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-500 flex flex-col h-full">

      {/* Header */}

      <div className="sticky top-0 bg-white z-10 -mt-5 pt-5 pb-2 border-b border-black/5 mb-4 flex-shrink-0">
        <h3 className="text-[18px] font-bold text-gray-900">Choose the items you're moving</h3>
        <p className="text-[13px] text-gray-500 mt-0.5">See the moving price before you add each item. All prices include VAT.</p>
      </div>

      {/* Catalog — always rendered inline, no button/click needed */}

      <div className="flex-shrink-0">
        <NGLOBAddItemsModal
          open={true}
          onClose={props.onOpenAddItems}
          selectedQtys={props.items.reduce((acc, item) => ({ ...acc, [item.id]: item.qty }), {})}
          onConfirm={(confirmed) => {
            const newItems: SelectedItem[] = confirmed.map(c => ({
              id: c.item.id,
              name: c.item.name,
              price: c.item.price,
              volumeM3: c.item.volumeM3,
              widthCm: c.item.widthCm,
              heightCm: c.item.heightCm,
              depthCm: c.item.depthCm,
              qty: c.qty,
              photo: c.item.photo,
            }));
            const updatedItems = [...props.items];
            newItems.forEach(newItem => {
              const existingIndex = updatedItems.findIndex(i => i.id === newItem.id);
              if (existingIndex >= 0) {
                updatedItems[existingIndex].qty += newItem.qty;
              } else {
                updatedItems.push(newItem);
              }
            });
            props.setItems(updatedItems.filter(i => i.qty > 0));
          }}
          inline={true}
        />
      </div>

      {/* Selected items — scrollable, capped height so it never overflows the panel */}

