        <div className="mt-4 flex flex-col min-h-0 flex-1">
          <div className="flex items-center justify-between mb-3 border-b border-[#E5ECF7] pb-2 flex-shrink-0">
            <h4 className="text-[14px] font-semibold text-[#071A3A]">Selected items</h4>
