// ── AI Scan Detection (Middle Column) ──

function AIScanDetection(props: { items: SelectedItem[]; setItems: (v: SelectedItem[]) => void; onOpenAddItems: () => void }) {
  const { items, setItems, onOpenAddItems } = props;

  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [imageSize, setImageSize] = useState<{ w: number; h: number } | null>(null);
  const [scanStatus, setScanStatus] = useState<'idle' | 'scanning' | 'success' | 'error'>('idle');
  // Gemini API — no local model to load
  const [scanProgress, setScanProgress] = useState(0);
  const [detectedObjects, setDetectedObjects] = useState<any[]>([]);
  // Index into detectedObjects queue; null = overview mode
  const [reviewIdx, setReviewIdx] = useState<number | null>(null);
  const guessedItem = reviewIdx !== null ? detectedObjects[reviewIdx] ?? null : null;

  // Progress bar paced to Gemini API latency (~2-5 s)
  useEffect(() => {
    if (scanStatus !== 'scanning') { setScanProgress(0); return; }
    setScanProgress(8);
    const ticks = [
      setTimeout(() => setScanProgress(35), 800),
      setTimeout(() => setScanProgress(60), 2000),
      setTimeout(() => setScanProgress(80), 3500),
      setTimeout(() => setScanProgress(92), 5000),
    ];
    return () => ticks.forEach(clearTimeout);
  }, [scanStatus]);



  const handlePhoto = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const img = new window.Image();
    img.onload = async () => {
      const canvas = document.createElement('canvas');
      // Max resolution set to 800px to ensure base64 string stays under 1MB Next.js API limits
      const MAX_SIZE = 800;
      let width = img.width;
      let height = img.height;

      if (width > height) {
        if (width > MAX_SIZE) { height = Math.round((height * MAX_SIZE) / width); width = MAX_SIZE; }
      } else {
        if (height > MAX_SIZE) { width = Math.round((width * MAX_SIZE) / height); height = MAX_SIZE; }
      }

      setImageSize({ w: width, h: height });
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(img, 0, 0, width, height);
        // Lower quality to 0.8 to heavily reduce payload size
        const url = canvas.toDataURL('image/jpeg', 0.8);
        setPreviewUrl(url);
        setScanStatus('scanning');
        setReviewIdx(null);
        setDetectedObjects([]);

        try {
          const { detectFurniture } = await import('@/lib/ai-vision');
          const results = await detectFurniture(url, width, height);
          if (results && results.length > 0) {
            const mapped = results.map((r: any, idx: number) => {
              const vol = Math.min(Math.max(0.01, r.volumeM3), 15);
              return {
                ...r,
                id: r.id || `det-${idx}-${Date.now()}`,
                volumeM3: vol,
                price: Math.max(10, Math.round(vol * 22)),
              };
            });
            setScanProgress(100);
            setTimeout(() => {
              setDetectedObjects(mapped);
              setScanStatus('success');
              // Auto-select if only one item found
              if (mapped.length === 1) setReviewIdx(0);
            }, 400);
          } else {
            setScanStatus('error');
          }
        } catch (err) {
          console.error('Scanning error:', err);
          setScanStatus('error');
        }
      }
    };
    img.src = URL.createObjectURL(file);
    e.target.value = '';
  };

  const handleDimensionChange = (dim: 'l' | 'w' | 'h', val: string) => {
    if (reviewIdx === null) return;
    const num = val === '' ? '' : Math.max(0, parseInt(val) || 0);
    const updated = { ...guessedItem, dimensions: { ...guessedItem.dimensions, [dim]: num } };
    const l = Number(updated.dimensions.l) || 0;
    const w = Number(updated.dimensions.w) || 0;
    const h = Number(updated.dimensions.h) || 0;
    const vol = Math.min(Math.max(0.01, parseFloat(((l * w * h) / 1_000_000).toFixed(3))), 15);
    updated.volumeM3 = parseFloat(vol.toFixed(2));
    updated.price = Math.max(10, Math.round(vol * 22));
    setDetectedObjects(prev => prev.map((o, i) => i === reviewIdx ? updated : o));
  };

  const handleNameChange = (val: string) => {
    if (reviewIdx === null) return;
    setDetectedObjects(prev => prev.map((o, i) => i === reviewIdx ? { ...o, name: val } : o));
  };

  const addCurrentItem = () => {
    if (!guessedItem) return;
    const newItem: SelectedItem = {
      id: `ai-${Date.now()}`,
      name: guessedItem.name,
      price: guessedItem.price,
      volumeM3: guessedItem.volumeM3,
      widthCm: Number(guessedItem.dimensions.w) || 0,
      heightCm: Number(guessedItem.dimensions.h) || 0,
      depthCm: Number(guessedItem.dimensions.l) || 0,
      qty: 1,
      photo: guessedItem.photo || previewUrl || '/few_items/boxes_custom_size.png',
    };
    setItems([...items, newItem]);
    const remaining = detectedObjects.filter((_, i) => i !== reviewIdx);
    setDetectedObjects(remaining);
    // Move to next or close sheet
    if (remaining.length === 0) { setReviewIdx(null); }
    else { setReviewIdx(Math.min(reviewIdx!, remaining.length - 1)); }
  };

  const addAllItems = () => {
    const newItems: SelectedItem[] = detectedObjects.map(obj => ({
      id: `ai-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      name: obj.name,
      price: obj.price,
      volumeM3: obj.volumeM3,
      widthCm: Number(obj.dimensions.w) || 0,
      heightCm: Number(obj.dimensions.h) || 0,
      depthCm: Number(obj.dimensions.l) || 0,
      qty: 1,
      photo: obj.photo || previewUrl || '/few_items/boxes_custom_size.png',
    }));
    setItems([...items, ...newItems]);
    setDetectedObjects([]);
    setReviewIdx(null);
  };

  const skipCurrentItem = () => {
    if (reviewIdx === null) return;
    const remaining = detectedObjects.filter((_, i) => i !== reviewIdx);
    setDetectedObjects(remaining);
    if (remaining.length === 0) { setReviewIdx(null); }
    else { setReviewIdx(Math.min(reviewIdx!, remaining.length - 1)); }
  };

  const resetScanner = () => {
    setPreviewUrl(null);
    setImageSize(null);
    setScanStatus('idle');
    setReviewIdx(null);
    setDetectedObjects([]);
  };

  const updateItemQty = (id: string, qty: number) => {
    if (qty <= 0) setItems(items.filter(i => i.id !== id));
    else setItems(items.map(i => i.id === id ? { ...i, qty } : i));
  };
  const removeItem = (id: string) => setItems(items.filter(i => i.id !== id));

  // Volume quality indicator
  const getDimAccuracy = (obj: any) => {
    const l = Number(obj?.dimensions?.l) || 0;
    const w = Number(obj?.dimensions?.w) || 0;
    const h = Number(obj?.dimensions?.h) || 0;
    if (l > 0 && w > 0 && h > 0) return 'good';
    if ((l > 0 ? 1 : 0) + (w > 0 ? 1 : 0) + (h > 0 ? 1 : 0) >= 2) return 'ok';
    return 'poor';
  };

  const totalVolume = items.reduce((s, i) => s + i.volumeM3 * i.qty, 0);

  return (
    <div className="flex flex-col h-full animate-in fade-in zoom-in-95 duration-500 ease-[cubic-bezier(0.32,0.72,0,1)]">
      <style>{`
        @keyframes aiScanLine { 0% { top: 0%; } 100% { top: 100%; } }
        @keyframes scanPulse { 0%,100% { opacity: 0.4; transform: scale(1); } 50% { opacity: 1; transform: scale(1.05); } }
        @keyframes cornerPulse { 0%,100% { border-color: rgba(255,255,255,0.3); } 50% { border-color: rgba(63,120,177,0.9); } }
      `}</style>

      {/* ── Status Bar ── */}
      <div className="bg-white/60 backdrop-blur-xl rounded-[20px] px-4 py-3 border border-black/[0.05] flex items-center justify-between mb-4 shadow-sm flex-shrink-0">
        <div className="flex items-center gap-2.5">
          <div className={`w-2 h-2 rounded-full flex-shrink-0 ${scanStatus === 'scanning' ? 'bg-blue-400 animate-ping' : 'bg-emerald-500'}`} />
          <span className="text-[13px] font-bold text-[#1d1d1f] tracking-tight">
            {scanStatus === 'scanning' ? 'Gemini is scanning…' : 'Gemini Vision Ready'}
          </span>
        </div>
        <div className="flex items-center gap-2">
          {items.length > 0 && (
            <span className="text-[12px] font-bold text-[#3F78B1] bg-[#3F78B1]/10 px-2.5 py-1 rounded-full">
              {items.length} item{items.length !== 1 ? 's' : ''} · {totalVolume.toFixed(1)}m³
            </span>
          )}
          <span className="text-[10px] font-bold text-[#86868b] bg-black/[0.05] px-2 py-0.5 rounded-full tracking-tight hidden sm:inline">Gemini 2.5 Flash</span>
        </div>
      </div>

      {/* ── Scanner / Preview area ── */}
      {!previewUrl ? (
        /* ── Idle upload prompt ── */
        <div className="relative w-full flex-1 min-h-[280px] rounded-[28px] overflow-hidden bg-gradient-to-br from-[#0d0f14] via-[#111318] to-[#0a0c10] mb-4 shadow-[0_16px_48px_rgba(0,0,0,0.18)] flex flex-col items-center justify-center text-center p-8 group border border-white/[0.03]">
          {/* Ambient glow */}
          <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_60%_40%,rgba(63,120,177,0.22)_0%,transparent_65%)] pointer-events-none" />
          {/* Animated scan-frame corners */}
          <div className="absolute top-6 left-6 w-10 h-10 border-l-2 border-t-2 border-white/25 rounded-tl-xl pointer-events-none" style={{ animation: 'cornerPulse 3s ease-in-out infinite' }} />
          <div className="absolute top-6 right-6 w-10 h-10 border-r-2 border-t-2 border-white/25 rounded-tr-xl pointer-events-none" style={{ animation: 'cornerPulse 3s ease-in-out infinite 0.75s' }} />
          <div className="absolute bottom-6 left-6 w-10 h-10 border-l-2 border-b-2 border-white/25 rounded-bl-xl pointer-events-none" style={{ animation: 'cornerPulse 3s ease-in-out infinite 1.5s' }} />
          <div className="absolute bottom-6 right-6 w-10 h-10 border-r-2 border-b-2 border-white/25 rounded-br-xl pointer-events-none" style={{ animation: 'cornerPulse 3s ease-in-out infinite 2.25s' }} />

          <div className="w-20 h-20 bg-white/5 rounded-full flex items-center justify-center mb-5 backdrop-blur-xl border border-white/10 transition-all group-hover:scale-110 group-hover:bg-white/10 duration-500 relative">
            <div className="absolute inset-0 rounded-full border-[1.5px] border-dashed border-white/20 animate-[spin_12s_linear_infinite]" />
            <svg className="w-9 h-9 text-white relative z-10" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="1.5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
              <path strokeLinecap="round" strokeLinejoin="round" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
          </div>
          <h3 className="text-white font-bold text-[20px] tracking-tight mb-2">Scan your items</h3>
          <p className="text-white/55 text-[13px] font-medium mb-7 max-w-[240px] leading-relaxed">AI detects furniture & appliances and estimates real dimensions instantly.</p>

          <div className="flex gap-3 relative z-10 w-full max-w-[290px]">
            <label className="flex-1 cursor-pointer bg-white text-[#1d1d1f] py-3.5 rounded-[18px] text-[14px] font-bold hover:bg-white/90 active:scale-[0.97] transition-all shadow-[0_8px_24px_rgba(255,255,255,0.15)] flex items-center justify-center gap-2">
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5">
                <path strokeLinecap="round" strokeLinejoin="round" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
              </svg>
              Camera
              <input type="file" accept="image/*" capture="environment" className="sr-only" onChange={handlePhoto} />
            </label>
            <label className="flex-1 cursor-pointer bg-white/10 text-white py-3.5 rounded-[18px] text-[14px] font-bold hover:bg-white/18 active:scale-[0.97] transition-all border border-white/10 backdrop-blur-md flex items-center justify-center gap-2">
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5">
                <path strokeLinecap="round" strokeLinejoin="round" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
              Upload
              <input type="file" accept="image/*" className="sr-only" onChange={handlePhoto} />
            </label>
          </div>
        </div>
      ) : (
        /* ── Photo preview with bounding boxes ── */
        <div className="w-full flex justify-center bg-[#0a0a0c] mb-4 shadow-[0_12px_40px_rgba(0,0,0,0.14)] border border-white/[0.03] rounded-[28px] overflow-hidden flex-shrink-0">
