                  style={{
                    left: `${obj.box.xmin}%`,
                    top: `${obj.box.ymin}%`,
                    width: `${obj.box.xmax - obj.box.xmin}%`,
                    height: `${obj.box.ymax - obj.box.ymin}%`,
