                >
                  {/* Label chip */}
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap max-w-full truncate leading-tight transition-all ${isSelected
                      ? 'bg-[#3F78B1] text-white shadow-sm'
                      : 'bg-black/75 text-white/90 group-hover:bg-black'
                    }`}>
                    {obj.name}
                  </span>
                </button>
              );
            })}


            {/* Tap hint */}
            {scanStatus === 'success' && reviewIdx === null && detectedObjects.length > 0 && (
              <div className="absolute top-4 left-1/2 -translate-x-1/2 bg-black/70 backdrop-blur-xl text-white px-4 py-2 rounded-full text-[12px] font-semibold shadow-xl border border-white/10 animate-in fade-in slide-in-from-top-3 whitespace-nowrap z-30">
                Tap a box to review · {detectedObjects.length} item{detectedObjects.length !== 1 ? 's' : ''} found
              </div>
            )}

            {/* All-added confirmation */}
            {scanStatus === 'success' && detectedObjects.length === 0 && (
              <div className="absolute inset-0 flex items-center justify-center z-30">
                <div className="bg-[#3F78B1]/90 backdrop-blur-xl text-white px-6 py-3.5 rounded-2xl text-[14px] font-bold shadow-2xl border border-[#3F78B1]/40 flex items-center gap-2.5 animate-in zoom-in-95 fade-in">
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" /></svg>
                  All items added to quote!
                </div>
              </div>
            )}

            {/* Scanning overlay */}
            {scanStatus === 'scanning' && (
              <div className="absolute inset-0 z-30 flex flex-col items-center justify-center">
                <div className="absolute inset-0 bg-black/50 backdrop-blur-[6px]" />
                <div className="w-full h-[2px] bg-gradient-to-r from-transparent via-[#3F78B1] to-transparent absolute left-0 shadow-[0_0_16px_4px_rgba(63,120,177,0.8)]"
                  style={{ animation: 'aiScanLine 1.8s cubic-bezier(0.4,0,0.2,1) infinite alternate' }} />
                <div className="bg-[#1d1d1f]/90 backdrop-blur-2xl text-white px-6 py-4 rounded-2xl text-[13px] font-semibold flex flex-col items-center gap-3 shadow-2xl border border-white/10 relative z-40 min-w-[220px]">
                  <div className="flex items-center justify-between w-full gap-3">
                    <div className="flex items-center gap-2.5">
                      <div className="w-4 h-4 border-[2px] border-white/20 border-t-[#3F78B1] rounded-full animate-spin flex-shrink-0" />
                      <span>Gemini AI Analysing…</span>
                    </div>
                    <span className="text-[11px] text-white/50 font-bold tabular-nums">{scanProgress}%</span>
                  </div>
                  {/* Progress bar */}
                  <div className="w-full h-1.5 bg-white/10 rounded-full overflow-hidden">
                    <div className="h-full bg-gradient-to-r from-[#3F78B1] to-[#6ba3d6] rounded-full transition-all duration-700 ease-out" style={{ width: `${scanProgress}%` }} />
                  </div>
                  <p className="text-[10px] text-white/35 font-medium">Detecting items &amp; estimating dimensions</p>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ── Item Review Sheet (inline, below photo) ── */}
      {scanStatus === 'success' && guessedItem && (
        <div className="bg-white rounded-[24px] border border-black/[0.05] shadow-[0_8px_32px_rgba(0,0,0,0.08)] p-5 mb-4 flex-shrink-0 animate-in slide-in-from-bottom-4 fade-in duration-400 ease-[cubic-bezier(0.32,0.72,0,1)]">
          {/* Header row */}
          <div className="flex items-start justify-between mb-4">
            <div className="flex items-center gap-3">
              {/* Cropped thumbnail */}
              {guessedItem.photo && (
                <div className="w-14 h-14 rounded-[14px] overflow-hidden bg-[#f5f5f7] flex-shrink-0 shadow-sm border border-black/[0.04]">
                  <img src={guessedItem.photo} alt={guessedItem.name} className="w-full h-full object-cover" />
                </div>
              )}
              <div>
                <div className="flex items-center gap-1.5 mb-0.5">
                  <span className="bg-[#3F78B1] text-white text-[9px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full">AI Detected</span>
                  <span className={`text-[9px] font-bold px-2 py-0.5 rounded-full ${getDimAccuracy(guessedItem) === 'good' ? 'bg-emerald-100 text-emerald-700' :
                      getDimAccuracy(guessedItem) === 'ok' ? 'bg-amber-100 text-amber-700' :
                        'bg-red-100 text-red-700'
                    }`}>
                    {Math.round(guessedItem.score * 100)}% confident
                  </span>
                </div>
                <input
                  type="text"
                  value={guessedItem.name}
                  onChange={(e) => handleNameChange(e.target.value)}
                  className="text-[18px] font-extrabold text-[#1d1d1f] bg-transparent border-none focus:outline-none tracking-tight w-full"
                />
              </div>
            </div>
            <div className="flex items-center gap-1 flex-shrink-0 ml-2">
              {/* Prev/next */}
              {detectedObjects.length > 1 && (
                <>
                  <button
                    onClick={() => setReviewIdx(Math.max(0, reviewIdx! - 1))}
                    disabled={reviewIdx === 0}
                    className="w-8 h-8 flex items-center justify-center rounded-full bg-black/5 hover:bg-black/10 disabled:opacity-30 transition-all text-[#1d1d1f] active:scale-90"
                  >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" /></svg>
                  </button>
                  <span className="text-[11px] font-bold text-[#86868b] min-w-[28px] text-center">{reviewIdx! + 1}/{detectedObjects.length}</span>
                  <button
                    onClick={() => setReviewIdx(Math.min(detectedObjects.length - 1, reviewIdx! + 1))}
                    disabled={reviewIdx === detectedObjects.length - 1}
                    className="w-8 h-8 flex items-center justify-center rounded-full bg-black/5 hover:bg-black/10 disabled:opacity-30 transition-all text-[#1d1d1f] active:scale-90"
                  >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" /></svg>
                  </button>
                </>
              )}
              <button onClick={() => setReviewIdx(null)} className="w-8 h-8 flex items-center justify-center rounded-full bg-black/5 hover:bg-black/10 text-[#86868b] hover:text-[#1d1d1f] transition-all active:scale-90 ml-1">
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
          </div>

          {/* Dimension inputs */}
          <div className="grid grid-cols-3 gap-2.5 mb-4">
            {(['l', 'w', 'h'] as const).map((dim, di) => {
              const labels = { l: { full: 'Depth', short: 'D' }, w: { full: 'Width', short: 'W' }, h: { full: 'Height', short: 'H' } };
              const val = guessedItem.dimensions[dim];
              return (
                <div key={dim} className="flex flex-col bg-[#f9f9fb] border border-black/[0.05] rounded-[16px] p-3 focus-within:ring-2 focus-within:ring-[#3F78B1]/30 focus-within:bg-white transition-all">
                  <label className="text-[9px] uppercase font-black text-[#86868b] mb-1.5 tracking-wider">{labels[dim].full}</label>
                  <div className="flex items-end gap-1">
                    <input
                      type="number"
                      min="1"
                      max="999"
                      value={val ?? ''}
                      onChange={(e) => handleDimensionChange(dim, e.target.value)}
                      className="w-full bg-transparent border-none text-[18px] font-extrabold text-[#1d1d1f] focus:outline-none p-0 [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                      placeholder="—"
                    />
                    <span className="text-[10px] font-bold text-[#86868b] mb-0.5 flex-shrink-0">cm</span>
                  </div>
                </div>
