        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${getAccessToken()}`
        },
        body: JSON.stringify({ code: promoCode.trim(), bookingTotal: quoteData?.totalToPay })
      });
      const data = await res.json();
      if (res.ok && data.valid) {
        setPromoValid(true);
        setPromoMessage(`✨ ${data.displayText || 'Discount applied!'}`);
      } else {
        setPromoValid(false);
        setPromoMessage(`❌ ${data.message || 'Invalid promo code'}`);
      }
    } catch {
      setPromoValid(false);
      setPromoMessage('❌ Failed to check code');
    } finally {
      setCheckingPromo(false);
    }
  };

  useEffect(() => {
    if (promoValid) {
      setPromoValid(false);
      setPromoMessage('');
    }
  }, [promoCode]);

  // Local fallback estimates so extras appear in the price before locations are entered
  let fallbackBaseCost = 0;
  let fallbackAdditionalMoverCost = 0;

  if (!quoteData) {
    let loadingTimeMins = 30;
    if (tab === 'moving_few_items') {
      const vol = items.reduce((a, i) => a + (i.volumeM3 || 0.1) * i.qty, 0);
      loadingTimeMins = Math.max(30, vol * 30);
    } else if (tab === 'moving_home') {
      const sizeMins: any = { 'Studio': 60, '1': 90, '2': 120, '3': 180, '4+': 240 };
      loadingTimeMins = sizeMins[homeSize] || 60;
    }
    const hours = loadingTimeMins / 60;

    let homeSizeFee = 0;
    if (tab === 'moving_home') {
      if (homeSize === '1') homeSizeFee = prices?.fee1Bed || 30;
      else if (homeSize === '2') homeSizeFee = prices?.fee2Bed || 60;
      else if (homeSize === '3') homeSizeFee = prices?.fee3Bed || 100;
      else if (homeSize === '4+') homeSizeFee = prices?.fee4Bed || 150;
    }

    fallbackBaseCost = (hours * (prices?.hourlyRate || 60)) + homeSizeFee;

    const moversNum = parseInt(movers[0] || '1');
    if (moversNum > 1) {
      fallbackAdditionalMoverCost = hours * (prices?.additionalMoverRate || 15) * (moversNum - 1);
    }
  }

  const baseCost = quoteData?.baseCost ?? fallbackBaseCost;
  const additionalMoverCost = quoteData?.additionalMoverCost ?? fallbackAdditionalMoverCost;
  const displayBaseCost = baseCost + additionalMoverCost;

  const fuelCost = quoteData?.fuelCost ?? 0;

  // Use || instead of ?? so a backend-returned 0 (from a stripped packingTier) still
  // falls through to the locally-computed packingPrice from PackingServicePanel.
  const packingCost = (packingAdded && tab === 'moving_home')
    ? (quoteData?.fullPackingCost || packingPrice || prices?.fullPackingService || 230)
    : 0;

  const materialsCost = quoteData?.packingMaterialsCost ?? (materialsAdded && packingMaterialsList ? packingMaterialsList.reduce((acc, m) => {
    const t = m.type || m.item?.id;
    const q = m.quantity ?? m.qty ?? 0;
    let u = 0;
    if (t === 'MEDIUM_BOX') u = prices?.materialMediumBox || 4.0;
    else if (t === 'LARGE_BOX') u = prices?.materialLargeBox || 7.0;
    else if (t === 'BUBBLE_WRAP') u = prices?.materialBubbleWrap || 7.0;
    else if (t === 'PAPER_ROLL') u = prices?.materialPaperRoll || 5.0;
    else if (t === 'TAPE') u = prices?.materialTape || 1.0;
    return acc + u * q;
  }, 0) : 0);

  let fallbackStorageCost = 0;
  if (storageAdded || storageRequired) {
    const weekly = (storageSqft || 0) * (prices?.storageRatePerSqftPerWeek || 0.8);
    if (storageWeeks && storageWeeks > 0) fallbackStorageCost = weekly * storageWeeks;
    else if (storageDays && storageDays > 0) fallbackStorageCost = (weekly / 7) * storageDays;
    else fallbackStorageCost = weekly;
  }
  const storageCost = quoteData?.storageCost ?? fallbackStorageCost;

  const discountAmount = quoteData?.discountAmount ?? 0;

  const rawFallbackTotal = baseCost + additionalMoverCost + fuelCost + packingCost + materialsCost + storageCost - discountAmount;
  const fallbackVat = rawFallbackTotal * (20 / 120);

  // Bug fix: when the backend returned quoteData but fullPackingCost was 0 (stripped
  // packing tier), quoteData.totalToPay excludes packing. In that case we add the
  // locally-computed packingCost on top so the grand total is always correct.
  const packingMissedByBackend =
    quoteData && packingAdded && tab === 'moving_home' && !(quoteData.fullPackingCost > 0)
      ? packingCost
      : 0;

  const vatAmount = quoteData
    ? (quoteData.vatAmount ?? fallbackVat) + packingMissedByBackend * (20 / 120)
    : fallbackVat;
  const totalWithStorage = quoteData
    ? (quoteData.totalToPay ?? rawFallbackTotal) + packingMissedByBackend
    : rawFallbackTotal;

  const canProceed = ready && (!storageRequired || storageSqft > 0);

  const totalItemsCount = items.reduce((a, i) => a + i.qty, 0);

  return (
    <div className="w-full h-full min-h-0 bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden flex flex-col">
      <div className="p-5 md:p-6 flex-1 min-h-0 flex flex-col overflow-y-auto custom-scrollbar">

        {/* ── Header ── */}
        <div className="flex items-center justify-between mb-1">
          <span className="text-[20px] font-bold text-[#071A3A]">Estimated total</span>
          <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-full border border-[#DDE4EE] bg-[#F4F8FF] flex-shrink-0">
            <span className="w-2 h-2 rounded-full bg-[#16B364] animate-pulse"></span>
            <span className="text-[10px] font-semibold text-[#667085] uppercase tracking-wide">Live total</span>
          </div>
        </div>

        {/* ── Price ── */}
        <div className="mb-5">
          <div className="text-[38px] font-bold tracking-tight text-[#071A3A] leading-tight">
            £{preparing ? '...' : totalWithStorage.toFixed(2)}
          </div>
          <div className="text-[13px] text-[#667085] font-medium leading-5 mt-0.5">
            Due today · Includes £{preparing ? '...' : vatAmount.toFixed(2)} VAT
            <div>Updates instantly as you edit</div>
          </div>
        </div>

        {/* ── Line items ── */}
        <div className="flex flex-col gap-3 text-[14px]">
          <div className="flex justify-between items-center text-[#071A3A] font-semibold">
            <span className="text-[13px] text-[#344054]">{tab === 'moving_home' ? (() => {
              const dm = dateTime?.durationMins;
              if (dm && dm > 0) {
                const hrs = Math.floor(dm / 60);
                const mins = dm % 60;
                const label = hrs > 0 && mins > 0 ? `${hrs} hr ${mins} min` : hrs > 0 ? `${hrs} hr` : `${mins} min`;
                return `${movers} · ${label}`;
              }
              return `${movers} · ${quoteData?.totalDurationDisplay || '...'}`;
            })() : `Move items - ${totalItemsCount} pieces`}</span>
            <span>£{preparing ? '...' : displayBaseCost.toFixed(2)}</span>
          </div>
          <div className="flex justify-between items-center text-[#071A3A] font-semibold">
            <span className="text-[13px] text-[#344054]">Mileage - {(distanceKm * 0.621371).toFixed(1)} mi</span>
            <span>£{preparing ? '...' : fuelCost.toFixed(2)}</span>
          </div>

          {packingAdded && tab === 'moving_home' && (
            <div className="flex justify-between items-center">
              <span className="text-[13px] text-[#344054] font-semibold">Full packing service</span>
              <span className="font-semibold text-[#3F78B1]">£{preparing ? '...' : packingCost.toFixed(2)}</span>
            </div>
          )}
          {materialsAdded && (
            <div className="flex justify-between items-center">
              <span className="text-[13px] text-[#344054] font-semibold">Packing materials</span>
              <span className="font-semibold text-[#3F78B1]">£{preparing ? '...' : materialsCost.toFixed(2)}</span>
            </div>
          )}
          {(storageRequired || storageAdded) && (
            <div className="flex justify-between items-center">
              <span className="text-[13px] text-[#344054] font-semibold">Storage</span>
              <span className="font-semibold text-[#3F78B1]">£{preparing ? '...' : storageCost.toFixed(2)}</span>
            </div>
          )}
          {promoValid && discountAmount > 0 && (
            <div className="flex justify-between items-center text-green-600">
              <span className="text-[13px] font-semibold">Promo discount</span>
              <span className="font-semibold">-£{preparing ? '...' : discountAmount.toFixed(2)}</span>
            </div>
          )}
        </div>

        {/* ── Promo code ── */}
        <div className="mt-4">
          {!showPromoInput ? (
            <button onClick={() => setShowPromoInput(true)} className="text-[13px] font-semibold text-[#5993CC] hover:underline">
              Have a promo code?
            </button>
          ) : (
            <div className="animate-in fade-in slide-in-from-top-2 duration-300">
              <div className="flex gap-2">
                <input
                  type="text"
                  value={promoCode}
                  onChange={e => setPromoCode(e.target.value)}
                  placeholder="Enter code"
                  className="flex-1 bg-[#f5f5f7] border border-transparent rounded-xl px-4 py-2 text-sm font-medium focus:outline-none focus:border-[#5993CC] focus:bg-white transition-all uppercase"
                />
                <button
                  onClick={handleCheckPromo}
                  disabled={checkingPromo || !promoCode.trim()}
                  className="bg-[#1d1d1f] text-white px-4 py-2 rounded-xl text-[13px] font-semibold hover:bg-[#333] transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {checkingPromo ? '...' : 'Apply'}
                </button>
              </div>
              {promoMessage && (
                <p className={`text-[11px] font-semibold mt-2 ${promoValid ? 'text-green-600' : 'text-red-500'}`}>
                  {promoMessage}
                </p>
              )}
            </div>
          )}
        </div>

        {/* ── Divider + "What can change this total?" ── */}
        <div className="mt-5 pt-4 border-t border-[#DDE4EE]">
          <button
            onClick={() => setShowBreakdown(v => !v)}
            className="flex items-center gap-1.5 text-[13px] font-semibold text-[#3F78B1] hover:underline"
          >
            What can change this total?
            <svg
              width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"
              className={`transition-transform duration-200 ${showBreakdown ? 'rotate-180' : ''}`}
            >
              <path d="M6 9l6 6 6-6" />
            </svg>
          </button>

          {showBreakdown && (
            <div className="mt-4 rounded-2xl overflow-hidden border border-[#DDE4EE] h-[190px]">
              <MapPreview pickupStr={pickup} destinationStr={destination} />
            </div>
          )}
        </div>

        {/* ── Storage sqft input (required when dates differ) ── */}
        {/* {storageRequired && (
          <div className="mt-5 p-4 bg-gradient-to-br from-[#f8f9fa] to-[#f1f3f5] rounded-2xl border border-black/5">
            <div className="flex items-center gap-2 mb-3">
              <div className="w-6 h-6 rounded-full bg-white shadow-sm flex items-center justify-center flex-shrink-0 text-[#5993CC]">
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z" /></svg>
              </div>
              <div>
                <h3 className="text-[13px] font-bold text-[#1d1d1f]">Storage required</h3>
                <p className="text-[10px] font-medium text-[#86868b] uppercase tracking-wider">{storageDays} days between dates</p>
              </div>
            </div>

            <div className="flex items-center justify-between mb-2">
              <span className="text-[12px] font-semibold text-[#1d1d1f]">Space needed</span>
              <span className="text-[12px] font-bold text-[#5993CC] bg-[#5993CC]/10 px-2 py-0.5 rounded-md">{storageSqft} sq ft</span>
            </div>
            <input
              type="range" min="0" max="300" step="25"
              value={storageSqft}
              onChange={(e) => setStorageSqft(Number(e.target.value))}
              className="w-full h-1.5 bg-black/10 rounded-lg cursor-pointer accent-[#5993CC]"
            />
          </div>
        )} */}

      </div>

      {/* ── Sticky footer: pay button ── */}
      <div className="p-5 md:p-6 flex-shrink-0 bg-white border-t border-[#DDE4EE]">
        <button
          onClick={canProceed ? () => onPayNow(discountAmount, totalWithStorage) : undefined}
          disabled={!canProceed}
          className={`w-full py-4 rounded-[10px] font-semibold flex items-center justify-center gap-2 transition-all duration-200 text-[15px] ${canProceed
            ? 'bg-[#0B1F44] text-white hover:bg-[#081733]'
            : 'bg-[#EAF2FF] text-[#9CA3AF] cursor-not-allowed'
            }`}
        >
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path></svg>
          {preparing ? 'Calculating...' : `Pay £${totalWithStorage.toFixed(2)}`}
        </button>

        <div className="mt-4 flex items-center justify-center gap-1.5 text-gray-500 text-[11px] font-medium">
