// ─── Page ────────────────────────────────────────────────────
const DRAFT_KEY = 'nglob_booking_draft';

export default function HomePage() {
  const { prices } = usePrices();
  const [tab, setTab] = useState<BookingTab>('moving_home');
  const [pickup, setPickup] = useState('');
  const [destination, setDestination] = useState('');
  const [dateTime, setDateTime] = useState<{ date: string; pickupSlot: TimeSlot; deliveryDate?: string; deliverySlot?: string; exactTime?: string; exactDeliveryTime?: string; storageDays?: number; storageRequired?: boolean; durationMins?: number } | null>(null);
  const [packingTier, setPackingTier] = useState<TierId>('FULL');
  const [homeSize, setHomeSize] = useState<HomeSize>('1');
  const [movers, setMovers] = useState<MoversCount>('1 Mover');
  const [items, setItems] = useState<SelectedItem[]>([]);
  const [storageAdded, setStorageAdded] = useState(false);
  const [packingAdded, setPackingAdded] = useState(false);
  const [packingHours, setPackingHours] = useState(2.5);
  const [packingPrice, setPackingPrice] = useState(0);
  const [packingMaterialsList, setPackingMaterialsList] = useState<any[]>([]);
  const [materialsAdded, setMaterialsAdded] = useState(false);
  const [storageSqft, setStorageSqft] = useState(75);
  const [storageWeeks, setStorageWeeks] = useState(1);
  const [promoCode, setPromoCode] = useState('');
  const [hydrated, setHydrated] = useState(false);
  const [showPackingMaterials, setShowPackingMaterials] = useState(false);
  const [showAddItems, setShowAddItems] = useState(false);
  const [isDatePickerOpen, setIsDatePickerOpen] = useState(false);
  const [specialInstructions, setSpecialInstructions] = useState('');

  const [stairsFlights, setStairsFlights] = useState(0);
  const [hasLift, setHasLift] = useState(false);
  const [parkingDistance, setParkingDistance] = useState(10);
  const [notesForDriver, setNotesForDriver] = useState('');

  const [preparing, setPreparing] = useState(false);
  const [quoteReady, setQuoteReady] = useState(false);
  const [checkoutOpen, setCheckoutOpen] = useState(false);
  const [checkoutSummary, setCheckoutSummary] = useState({ subtotal: 0, vat: 0, total: 0 });
  const router = useRouter();

  const [pickupCoords, setPickupCoords] = useState<{ lat: number; lng: number } | null>(null);
  const [destCoords, setDestCoords] = useState<{ lat: number; lng: number } | null>(null);
  const [quoteData, setQuoteData] = useState<any>(null);
  const [distanceKm, setDistanceKm] = useState<number | null>(null);
  const [routingError, setRoutingError] = useState<string | null>(null);
  // Persists the booking ID across checkout modal open/close cycles so we never
  // create a second booking if the user closes and re-opens the checkout modal.
  const pendingBookingIdRef = useRef<string | null>(null);

  const [scrollProgress, setScrollProgress] = useState(0);

  useEffect(() => {
    const container = document.getElementById('left-scroll-container');
    if (!container) return;

    let targetScroll = container.scrollTop;

    const handleWheel = (e: WheelEvent) => {
      // Don't intercept scroll inside interactive elements or natively scrollable areas
      const target = e.target as HTMLElement;
      if (target.closest('input, textarea, select, [role="listbox"], [role="menu"], .dropdown-list, .pac-container, [data-radix-popper-content-wrapper]') ||
        (target.scrollHeight > target.clientHeight && window.getComputedStyle(target).overflowY !== 'hidden')) {
        return; // Let native scroll handle it
      }

      // Calculate scroll limits
      const maxScroll = container.scrollHeight - container.clientHeight;
      if (maxScroll <= 0) return;

      e.preventDefault(); // Stop native scrolling only for smooth scroll

      targetScroll += e.deltaY;
      targetScroll = Math.max(0, Math.min(targetScroll, maxScroll));

      gsap.to(container, {
        scrollTop: targetScroll,
        duration: 0.8,
        ease: 'power3.out',
        overwrite: 'auto',
        onUpdate: () => {
          setScrollProgress(maxScroll > 0 ? container.scrollTop / maxScroll : 0);
        }
      });
    };

    // Sync targetScroll when scroll happens natively (e.g. Firefox fallback)
    const handleScroll = () => {
      targetScroll = container.scrollTop;
      const maxScroll = container.scrollHeight - container.clientHeight;
      setScrollProgress(maxScroll > 0 ? container.scrollTop / maxScroll : 0);
    };

    container.addEventListener('wheel', handleWheel, { passive: false });
    container.addEventListener('scroll', handleScroll, { passive: true });
    return () => {
      container.removeEventListener('wheel', handleWheel);
      container.removeEventListener('scroll', handleScroll);
    };
  }, []);

  // ── Hydrate from sessionStorage on mount & on custom event ──
  useEffect(() => {
    const loadDraft = () => {
      try {
        const raw = sessionStorage.getItem(DRAFT_KEY);
        if (raw) {
          const d = JSON.parse(raw);
          if (d.tab) setTab(d.tab);
          if (d.pickup) setPickup(d.pickup);
          if (d.destination) setDestination(d.destination);
          if (d.dateTime) setDateTime(d.dateTime);
          if (d.homeSize) setHomeSize(d.homeSize);
          if (d.movers) setMovers(d.movers);
          if (d.items?.length) setItems(d.items);
          if (d.storageAdded !== undefined) setStorageAdded(d.storageAdded);
          if (d.packingAdded !== undefined) setPackingAdded(d.packingAdded);
          if (d.packingHours !== undefined) setPackingHours(d.packingHours);
          if (d.packingMaterialsList) setPackingMaterialsList(d.packingMaterialsList);
          if (d.materialsAdded !== undefined) setMaterialsAdded(d.materialsAdded);
          if (d.storageSqft !== undefined) setStorageSqft(d.storageSqft);
          if (d.storageWeeks !== undefined) setStorageWeeks(d.storageWeeks);
          if (d.pickupCoords) setPickupCoords(d.pickupCoords);
          if (d.destCoords) setDestCoords(d.destCoords);
          if (d.specialInstructions) setSpecialInstructions(d.specialInstructions);
          // Bug fix: restore distanceKm & packingPrice so mileage/packing cost
          // survive a page refresh without waiting for a fresh API round-trip.
          if (d.distanceKm != null) setDistanceKm(d.distanceKm);
          if (d.packingPrice != null) setPackingPrice(d.packingPrice);
          if (d.quoteData) {
            setQuoteData(d.quoteData);
            setQuoteReady(true);
          }
        }
      } catch { }
    };

    loadDraft();
    setHydrated(true);

    window.addEventListener('nglob_draft_updated', loadDraft);
    return () => window.removeEventListener('nglob_draft_updated', loadDraft);
  }, []);

  // ── Save draft to sessionStorage on every change ──
  useEffect(() => {
    if (!hydrated) return;
    try {
      sessionStorage.setItem(DRAFT_KEY, JSON.stringify({
        tab, pickup, destination, dateTime, homeSize, movers, items,
        storageAdded, packingAdded, packingHours, packingMaterialsList, materialsAdded, storageSqft, storageWeeks,
        pickupCoords, destCoords, quoteData, specialInstructions, packingTier,
        distanceKm, packingPrice
      }));
    } catch { }
  }, [hydrated, tab, pickup, destination, dateTime, homeSize, movers, items, storageAdded, packingAdded, packingHours, packingMaterialsList, materialsAdded, storageSqft, storageWeeks, pickupCoords, destCoords, quoteData, specialInstructions, distanceKm, packingPrice]);

  const clearBookingDraft = () => {
    try { sessionStorage.removeItem(DRAFT_KEY); } catch { }
  };

  // Detect storage requirement from dateTime
  const storageDays = (() => {
    if (!dateTime?.date || !dateTime?.deliveryDate) return 0;
    const pickup = new Date(dateTime.date);
    const delivery = new Date(dateTime.deliveryDate);
    const msPerDay = 86400000;
    const pStart = new Date(pickup.getFullYear(), pickup.getMonth(), pickup.getDate()).getTime();
    const dStart = new Date(delivery.getFullYear(), delivery.getMonth(), delivery.getDate()).getTime();
    return Math.max(0, Math.round((dStart - pStart) / msPerDay));
  })();
  const storageRequiredByDates = storageDays > 0;

  // Auto calculate quote via backend
  useEffect(() => {
    if (pickupCoords && destCoords) {
      setPreparing(true);
      setQuoteReady(false);
      setRoutingError(null);

      const fetchPrice = async () => {
        try {
          const route = await getDrivingDistance(pickupCoords, destCoords);

          if (!route) {
            // Routing failure — do NOT substitute a fake distance.
            // Display an error and block the quote so the user sees an honest
            // message rather than a price based on a phantom 12.4-mile route.
            setRoutingError(
              'Could not calculate a driving route between the two addresses. ' +
              'Please check both addresses are valid UK postcodes or specific locations.',
            );
            setQuoteData(null);
            setQuoteReady(false);
            return;
          }

          const dist = route.distanceMeters / 1000;
          setDistanceKm(dist);

          const mappedHomeSize = homeSize === 'Studio' ? 'STUDIO' :
            homeSize === '1' ? 'ONE' :
              homeSize === '2' ? 'TWO' :
                homeSize === '3' ? 'THREE' : 'FOUR_PLUS';

          const res = await fetch(`${process.env.API_URL}/pricing/calculate`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              homeSize: tab === 'moving_home' ? mappedHomeSize : undefined,
              moversCount: tab === 'moving_home' ? (parseInt(movers[0]) || 1) : 1,
              extras: (tab === 'moving_home' && packingAdded) ? 'FULL_PACKING' : materialsAdded ? 'MATERIALS_ONLY' : 'NONE',
              pickupAddress: pickup || 'Unknown Pickup',
              destinationAddress: destination || 'Unknown Destination',
              packingTimeHours: (tab === 'moving_home' && packingAdded) ? packingHours : undefined,
              packingMaterials: ((tab === 'moving_home' && packingAdded) || materialsAdded) ? packingMaterialsList.map(p => ({
                type: p.type || p.item?.id,
                quantity: p.quantity !== undefined ? p.quantity : p.qty
              })) : undefined,
              packingTier: (tab === 'moving_home' && packingAdded) ? packingTier : undefined,
              items: tab === 'moving_few_items' ? items.map(i => ({
                volumeM3: i.volumeM3 || 0.1,
                quantity: i.qty
              })) : [],
              withStorage: storageAdded || storageDays > 0,
              storageSqft: storageSqft,
              storageDays: storageDays,
              storageWeeks: storageWeeks,
              bookedDurationMins: dateTime?.durationMins || undefined,
              // R1-13: include hasLift so the server can waive the stairs fee when a lift is available
              stairsFlights: hasLift ? 0 : stairsFlights,
              // promoCode is passed to the backend so discount math happens server-side.
              // The frontend never applies a percentage itself.
              promoCode: promoCode.trim() || undefined,
            })
          });

          if (res.ok) {
            const data = await res.json();
            setQuoteData(data);
          } else {
            console.error("Price calculation failed, server returned:", res.status);
            // Only clear quoteData if it's completely invalid, otherwise keep old data to prevent UI flash
            if (!quoteData) setQuoteData(null);
          }
        } catch (e: any) {
          console.error("Price estimation failed", e);
          if (!quoteData) setQuoteData(null);
        } finally {
          setPreparing(false);
          setQuoteReady(true);
        }
      };

      const t = setTimeout(() => fetchPrice(), 1000);
      return () => clearTimeout(t);
    } else {
      setPreparing(false);
      setQuoteReady(false);
      setQuoteData(null);
      setRoutingError(null);
      setDistanceKm(null);
    }
  }, [pickupCoords, destCoords, tab, homeSize, movers, items, packingAdded, packingHours, packingMaterialsList, materialsAdded, storageAdded, storageSqft, storageDays, storageWeeks, promoCode, packingTier, stairsFlights, hasLift, parkingDistance, dateTime?.durationMins, dateTime?.pickupSlot, dateTime?.deliverySlot]);

  const initPayment = async (isDeposit: boolean, existingBookingId: string | null) => {
    const token = getAccessToken();
    if (!token) throw new Error("Not logged in");

    // Prefer the caller-supplied ID, then fall back to the page-level ref so that
    // re-opening the checkout modal (which resets the modal's own ref) reuses the
    // booking already created rather than POSTing a new one.
    let bId = existingBookingId || pendingBookingIdRef.current;

    if (!bId) {
      const mappedHomeSize = homeSize === 'Studio' ? 'STUDIO' :
        homeSize === '1' ? 'ONE' :
          homeSize === '2' ? 'TWO' :
            homeSize === '3' ? 'THREE' : 'FOUR_PLUS';

      const mapSlotToBackend = (slot?: string) => {
        if (slot === '08:00 - 12:00') return 'SLOT_08_12';
        if (slot === '10:00 - 14:00') return 'SLOT_10_14';
        if (slot === '12:00 - 16:00') return 'SLOT_12_16';
        if (slot === '14:00 - 18:00') return 'SLOT_14_18';
        if (slot === '16:00 - 20:00') return 'SLOT_16_20';
        return 'SLOT_08_12';
      };

      const res = await fetch(`${process.env.API_URL}/bookings`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({
          type: tab === 'moving_home' ? 'FULL_HOUSE' : 'FEW_ITEMS',
          pickupAddress: pickup || 'Unknown Pickup',
          destinationAddress: destination || 'Unknown Destination',
          pickupDate: dateTime ? new Date(dateTime.date).toISOString() : new Date().toISOString(),
          pickupTimeSlot: dateTime?.exactTime ? 'EXACT' : mapSlotToBackend(dateTime?.pickupSlot),
          exactPickupTime: dateTime?.exactTime || undefined,
          notesForDriver: notesForDriver,
          parkingDistance: parkingDistance,
          homeSize: tab === 'moving_home' ? mappedHomeSize : undefined,
          moversCount: tab === 'moving_home' ? (parseInt(movers[0]) || 1) : 1,
          extras: (tab === 'moving_home' && packingAdded) ? 'FULL_PACKING' : 'MATERIALS_ONLY',
          // R1-13: send stairsFlights=0 when user confirmed there is a lift
          stairsFlights: hasLift ? 0 : stairsFlights,
          withStorage: storageAdded || storageRequiredByDates,
          ...((storageAdded || storageRequiredByDates) ? {
            storageSqft,
            storageDays,
            storageWeeks,
            returnAddress: destination || 'Unknown Destination',
            returnDate: dateTime?.deliveryDate ? new Date(dateTime.deliveryDate).toISOString() : undefined,
            returnTimeSlot: dateTime?.deliverySlot || 'SLOT_08_12'
          } : {}),
          packingTimeHours: (tab === 'moving_home' && packingAdded) ? packingHours : undefined,
          packingMaterials: ((tab === 'moving_home' && packingAdded) || materialsAdded) ? packingMaterialsList.map(p => ({
            type: p.type || p.item?.id,
            quantity: p.quantity !== undefined ? p.quantity : p.qty
          })) : undefined,
          packingTier: (tab === 'moving_home' && packingAdded) ? packingTier : undefined,
          items: tab === 'moving_few_items' ? items.map(i => ({
            name: i.name,
            category: 'DECOR_OTHER',
            ...getBookingItemDimensions(i),
            quantity: i.qty
          })) : [],
          promoCode: promoCode.trim() || undefined
        })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || 'Failed to create booking');
      bId = data.booking.id;
      pendingBookingIdRef.current = bId; // persist so re-open reuses this booking
    }

    const intentRes = await fetch(`${process.env.API_URL}/payments/intent`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`
      },
      body: JSON.stringify({ bookingId: bId, isDeposit })
    });
    const intentData = await intentRes.json();
    if (!intentRes.ok) throw new Error(intentData.message || 'Failed to initialize payment');

    return { clientSecret: intentData.clientSecret, bookingId: bId! };
  };

  const handlePaymentSuccess = (bookingId: string) => {
    pendingBookingIdRef.current = null; // clear so next booking starts fresh
    setCheckoutOpen(false);
    clearBookingDraft();
    router.push(`/app/confirmation?bookingId=${bookingId}`);
  };

  return (
    <>
      <div
        className="flex-1 flex flex-col bg-[#F5F6F7] overflow-hidden main-container-height"
      >

        {/* ═══ Entrance animation keyframes ═══ */}
        <style>{`

        body::-webkit-scrollbar { display: none; }
        body { -ms-overflow-style: none; scrollbar-width: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background-color: rgba(0,0,0,0.1); border-radius: 10px; }
        #left-scroll-container::-webkit-scrollbar { display: none; }
        #left-scroll-container { -ms-overflow-style: none; scrollbar-width: none; }
        /* Safari viewport fix: dvh is unreliable on Safari, svh is safer */
        @supports (-webkit-touch-callout: none) {
          .safari-full-height { height: -webkit-fill-available !important; }
        }
        @keyframes heroMapIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes heroCardIn { from { opacity: 0; transform: translateY(32px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes pulseGlow {
          0% { box-shadow: 0 0 0 0 rgba(89, 147, 204, 0.4); }
          70% { box-shadow: 0 0 0 10px rgba(89, 147, 204, 0); }
          100% { box-shadow: 0 0 0 0 rgba(89, 147, 204, 0); }
        }
        .animate-pulse-glow { animation: pulseGlow 2s infinite; }
        .hero-map-enter { animation: heroMapIn 0.6s ease-out both; }
        .hero-card-enter { animation: heroCardIn 0.5s ease-out 0.15s both; }
        .hero-field-stagger > * { animation: heroCardIn 0.4s ease-out both; }
        .hero-field-stagger > *:nth-child(1) { animation-delay: 0.25s; }
        .hero-field-stagger > *:nth-child(2) { animation-delay: 0.30s; }
        .hero-field-stagger > *:nth-child(3) { animation-delay: 0.35s; }
        .hero-field-stagger > *:nth-child(4) { animation-delay: 0.40s; }
        .hero-field-stagger > *:nth-child(5) { animation-delay: 0.45s; }

      `}</style>

        {/* ═══ HERO 3-Column Layout ═══ */}
        <section className="relative w-full flex-1 min-h-0 bg-[#F7F9FC] lg:px-6 ">

          {/* Mobile View */}
          <div className="block lg:hidden h-full">
            <MobileBookingWizard
              totalPrice={(() => {
                if (!quoteData) return 0;
                return quoteData.totalToPay;
              })()}
              steps={[
                {
                  title: 'Move Details',
                  content: (
                    <div className="p-1">
                      <BookingHeroForm
                        tab={tab} setTab={setTab}
                        pickup={pickup} setPickup={setPickup}
                        destination={destination} setDestination={setDestination}
                        pickupCoords={pickupCoords} setPickupCoords={setPickupCoords}
                        destCoords={destCoords} setDestCoords={setDestCoords}
                        dateTime={dateTime} setDateTime={setDateTime}
                        homeSize={homeSize} setHomeSize={setHomeSize}
                        movers={movers} setMovers={setMovers}
                        items={items} setItems={setItems}
                        withStorage={storageAdded}
                        onOpenAddItems={() => setShowAddItems(true)}
                        onDatePickerOpenChange={setIsDatePickerOpen}
                        specialInstructions={specialInstructions}
                        setSpecialInstructions={setSpecialInstructions}
                        storageSqft={storageSqft}
                        storageDays={storageDays}
                        storageWeeks={storageWeeks}
                        storageRequired={storageRequiredByDates}
                        mobileStep={1}
                      />
                    </div>
                  ),
                  isValid: !!(pickupCoords && destCoords && dateTime)
                },
                {
                  title: tab === 'moving_home' ? 'Home Size' : 'Items',
                  content: (
                    <div className="p-1">
                      <BookingHeroForm
                        tab={tab} setTab={setTab}
                        pickup={pickup} setPickup={setPickup}
                        destination={destination} setDestination={setDestination}
                        pickupCoords={pickupCoords} setPickupCoords={setPickupCoords}
                        destCoords={destCoords} setDestCoords={setDestCoords}
                        dateTime={dateTime} setDateTime={setDateTime}
                        homeSize={homeSize} setHomeSize={setHomeSize}
                        movers={movers} setMovers={setMovers}
                        items={items} setItems={setItems}
                        withStorage={storageAdded}
                        onOpenAddItems={() => setShowAddItems(true)}
                        onDatePickerOpenChange={setIsDatePickerOpen}
                        specialInstructions={specialInstructions}
                        setSpecialInstructions={setSpecialInstructions}
                        storageSqft={storageSqft}
                        storageDays={storageDays}
                        storageWeeks={storageWeeks}
                        storageRequired={storageRequiredByDates}
                        mobileStep={2}
                      />
                    </div>
                  ),
                  isValid: tab === 'moving_home' ? true : items.length > 0,
                  nextLabel: 'Continue to Services'
                },
                {
                  title: 'Services & Extras',
                  content: (
                    <WorkspacePanel
                      tab={tab}
                      homeSize={homeSize}
                      moversCount={parseInt(movers[0]) || 1}
                      storageAdded={storageAdded}
                      setStorageAdded={setStorageAdded}
                      packingAdded={packingAdded}
                      setPackingAdded={setPackingAdded}
                      materialsAdded={materialsAdded}
                      setMaterialsAdded={setMaterialsAdded}
