"use client";
import React, { useState, useEffect, useRef } from 'react';
import { TeamForm } from './ContactForms';
import { Icon } from './Icon';
import { assets } from './assets';
import type { ContactUsPageProps } from './types';
import { withRequestDeadline } from './requestDeadline';

export type ChatView = 'assistant' | 'team';
type ChatMessage = { id: number; speaker: 'You' | 'Nglob assistant'; text: string };

type ContactChatProps = Pick<ContactUsPageProps,
  'onTeamSubmit' | 'onTeamStatus' | 'onAssistantMessage' | 'requestTimeoutMs'> & {
    open: boolean;
    mobile: boolean;
    view: ChatView;
    onViewChange: (view: ChatView) => void;
    onClose: () => void;
    onPanelRef: (element: HTMLElement) => void;
    onTitleRef: (view: ChatView, element: HTMLHeadingElement) => void;
    idPrefix: string;
    showDemoNotice: boolean;
  };

export function ContactChat(props: ContactChatProps) {
  const [draft, setDraft] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [pending, setPending] = useState(false);
  const [notice, setNotice] = useState('');
  const composerRef = useRef<HTMLTextAreaElement>(null);
  const bodyRef = useRef<HTMLDivElement>(null);
  const requestRef = useRef<AbortController | undefined>(undefined);
  const nextMessageIdRef = useRef(0);
  const disposedRef = useRef(false);
  const panelRef = useRef<HTMLElement>(null);

  useEffect(() => {
    disposedRef.current = false;
    return () => {
      disposedRef.current = true;
      requestRef.current?.abort();
      requestRef.current = undefined;
    };
  }, []);

  useEffect(() => {
    if (props.open && props.view === 'assistant' && (messages.length || notice)) {
      bodyRef.current?.scrollTo({ top: bodyRef.current.scrollHeight });
    }
  }, [props.open, props.view, messages, notice]);

  async function sendMessage() {
    const message = draft.trim();
    if (!message || requestRef.current) return;
    const handler = props.onAssistantMessage;
    if (!handler) {
      setNotice('Design reference only. Nothing has been sent.');
      return;
    }
    const controller = new AbortController();
    requestRef.current = controller;
    setPending(true);
    setNotice('');
    try {
      const reply = await withRequestDeadline(signal => handler(message, { signal }), controller, props.requestTimeoutMs);
      if (disposedRef.current || requestRef.current !== controller) return;
      if (typeof reply !== 'string' || !reply.trim()) throw new Error('Empty reply');
      setMessages(current => [...current,
        { id: nextMessageIdRef.current++, speaker: 'You', text: message },
        { id: nextMessageIdRef.current++, speaker: 'Nglob assistant', text: reply },
      ]);
      setDraft('');
    } catch {
      if (!disposedRef.current && requestRef.current === controller) {
        setNotice("We couldn't get a reply. Your message is still here. You can try again or message our team.");
      }
    } finally {
      if (!disposedRef.current && requestRef.current === controller) {
        requestRef.current = undefined;
        setPending(false);
      }
    }
  }

  return (
    <section className="chat-panel" id={`${props.idPrefix}-chat`}
      ref={(element) => { if (element) props.onPanelRef(element); }}
      hidden={!props.open}
      role={props.mobile ? 'dialog' : 'region'}
      aria-modal={props.mobile && props.open ? true : undefined}
      aria-label={props.view === 'team' ? 'Message the Nglob team' : 'Nglob chat'}>
      <header className="chat-header">
        <div className="brand-avatar"><img src={assets.satinMark.src} width={107} height={88} alt="" /></div>
        <div><h2>{props.view === 'team' ? 'Nglob support' : 'Nglob assistant'}</h2><p>{props.view === 'team' ? 'Reply by email' : 'AI assistant'}</p></div>
        <button type="button" className="minimise" aria-label="Minimise chat" onClick={() => props.onClose()}><Icon name="minimise" /></button>
      </header>
      {props.showDemoNotice ? (<p className="chat-reference">Design reference · no messages are sent</p>) : null}
      <div className="chat-body" ref={bodyRef} hidden={props.view !== 'assistant'}>
        <h3 className="chat-title" tabIndex={-1} ref={(element) => { if (element) props.onTitleRef('assistant', element); }}>What can I help with?</h3>
        <p>Ask about moving, delivery, storage or getting ready for your booking.</p>
        <div className="chat-chips" role="group" aria-label="Suggested topics">
          {['Choosing the right service', 'Getting ready for a move', 'Help with a booking'].map(topic => (
            <button key={topic} type="button" disabled={pending} onClick={() => {
              setDraft(topic);
              setNotice('');
              composerRef.current?.focus();
            }}>{topic}</button>
          ))}
        </div>
        <div className="chat-human"><p>Our team can help by email.</p>
          <button className="text-button" type="button" onClick={() => props.onViewChange('team')}>Message our team</button>
        </div>
        {messages.length > 0 ? (
          <div className="chat-transcript" role="log" aria-label="Conversation" aria-live="polite" aria-relevant="additions">
            {messages.map(message => (
              <div key={message.id} className={`chat-message ${message.speaker === 'You' ? 'from-client' : ''}`}>
                <p className="chat-speaker">{message.speaker}</p><p>{message.text}</p>
              </div>
            ))}
          </div>
        ) : null}
        {pending ? (<p className="reference-inline" role="status">Waiting for a reply…</p>) : null}
        {notice ? (<p className="reference-inline" role="status">{notice}</p>) : null}
      </div>
      <div className="chat-body" hidden={props.view !== 'team'}>
        <button type="button" className="text-button team-back" onClick={() => props.onViewChange('assistant')}>← Switch to AI chat</button>
        <h3 className="chat-title" tabIndex={-1} ref={(element) => { if (element) props.onTitleRef('team', element); }}>Message our team</h3>
        <p>Tell us what you need help with. We'll reply by email.</p>
        <TeamForm idPrefix={props.idPrefix} onSubmit={props.onTeamSubmit} onCheckStatus={props.onTeamStatus} requestTimeoutMs={props.requestTimeoutMs} />
      </div>
      <div className="chat-composer" hidden={props.view !== 'assistant'}>
        <p className="chat-privacy">We use your messages to handle your enquiry.<br />
          <a href="https://www.nglob.com/privacy" target="_blank" rel="noopener" aria-label="Privacy Policy, opens in a new tab">Privacy Policy</a> <span aria-hidden="true">↗</span>
        </p>
        <div className="composer-row">
          <textarea aria-label="Your message" placeholder="Type your message" rows={1} ref={composerRef}
            value={draft} disabled={pending}
            onChange={event => { setDraft(event.currentTarget.value); setNotice(''); }} />
          <button type="button" className="send-message" aria-label="Send message" disabled={pending || !draft.trim()}
            aria-busy={pending || undefined} onClick={() => { void sendMessage(); }}><Icon name="send" /></button>
        </div>
      </div>
    </section>
  );
}

