"use client";
import React, { useState, useEffect, useRef, useCallback, useId } from 'react';
import { CallbackForm } from './ContactForms';
import { ContactChat } from './ContactChat';
import type { ChatView } from './ContactChat';
import { SiteFooter, SiteHeader } from './SiteChrome';
import { Icon } from './Icon';
import { assets } from './assets';
import type { ContactUsPageProps } from './types';
import './ContactUsPage.css';

const EMAILJS_SERVICE_ID  = 'service_s4kddfl';
const EMAILJS_TEMPLATE_ID = 'template_d7g85dl';
const EMAILJS_PUBLIC_KEY  = 'mRj0Ui91cV5sLDWMw';

type EmailStatus = 'idle' | 'sending' | 'success' | 'error';

function ContactUsForm(props: { idPrefix: string }) {
  const formRef = useRef<HTMLFormElement>(null);
  const [status, setStatus] = useState<EmailStatus>('idle');
  const [errorMsg, setErrorMsg] = useState('');
  const [fields, setFields] = useState({ name: '', email: '', subject: '', message: '' });

  // Load EmailJS SDK once
  useEffect(() => {
    if (document.getElementById('emailjs-sdk')) return;
    const script = document.createElement('script');
    script.id = 'emailjs-sdk';
    script.src = 'https://cdn.jsdelivr.net/npm/@emailjs/browser@4/dist/email.min.js';
    script.async = true;
    document.head.appendChild(script);
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setFields(f => ({ ...f, [e.target.name]: e.target.value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus('sending');
    setErrorMsg('');
    try {
      const emailjs = (window as any).emailjs;
      if (!emailjs) throw new Error('Email service not loaded. Please refresh and try again.');
      await emailjs.sendForm(EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, formRef.current!, EMAILJS_PUBLIC_KEY);
      setStatus('success');
      setFields({ name: '', email: '', subject: '', message: '' });
    } catch (err: any) {
      setStatus('error');
      setErrorMsg(err?.text || err?.message || 'Something went wrong. Please try again.');
    }
  };

  const id = (name: string) => `${props.idPrefix}-cuf-${name}`;

  if (status === 'success') {
    return (
      <div className="form-outcome success" role="status" aria-live="polite">
        <Icon name="check" />
        <div>
          <h3>Message sent!</h3>
          <p>We&apos;ll get back to you at the email address you provided.</p>
          <button className="text-button" type="button" onClick={() => setStatus('idle')}>Send another message</button>
        </div>
      </div>
    );
  }

  return (
    <form className="callback-form" ref={formRef} onSubmit={handleSubmit} noValidate>
      <p className="form-caption">Fill in the form and we&apos;ll get back to you within 1–2 business days.</p>
      <div className="form-grid">
        <div className={`field${fields.name === '' && status === 'error' ? ' has-error' : ''}`}>
          <label htmlFor={id('name')}>Your name</label>
          <input id={id('name')} name="name" type="text" autoComplete="name" required
            placeholder="Full name" value={fields.name} onChange={handleChange} />
        </div>
        <div className={`field${fields.email === '' && status === 'error' ? ' has-error' : ''}`}>
          <label htmlFor={id('email')}>Your email</label>
          <input id={id('email')} name="email" type="email" autoComplete="email" required
            placeholder="you@example.com" value={fields.email} onChange={handleChange} />
        </div>
        <div className="field">
          <label htmlFor={id('subject')}>Subject</label>
          <select id={id('subject')} name="subject" value={fields.subject} onChange={handleChange} required>
            <option value="" disabled>Select a topic…</option>
            <option value="Booking enquiry">Booking enquiry</option>
            <option value="Moving & delivery">Moving &amp; delivery</option>
            <option value="Storage">Storage</option>
            <option value="Pricing & quotes">Pricing &amp; quotes</option>
            <option value="Driver / Partner application">Driver / Partner application</option>
            <option value="Complaint">Complaint</option>
            <option value="Other">Other</option>
          </select>
        </div>
        <div className={`field${fields.message === '' && status === 'error' ? ' has-error' : ''}`}>
          <label htmlFor={id('message')}>Message</label>
          <textarea id={id('message')} name="message" maxLength={2000} rows={4} required
            placeholder="Tell us how we can help…" value={fields.message} onChange={handleChange} />
          <p className="field-note">Up to 2,000 characters.</p>
        </div>
      </div>
      {status === 'error' && (
        <p className="field-note error" role="alert" style={{ marginBottom: '12px' }}>{errorMsg}</p>
      )}
      <button className="button" type="submit" disabled={status === 'sending'}>
        {status === 'sending' ? <>Sending…<span className="spinner" aria-hidden="true" /></> : <>Send message<Icon name="arrow" /></>}
      </button>
    </form>
  );
}

/** React component for the Contact / Dialogue page. */
export default function ContactUsPage(props: ContactUsPageProps) {
  const idSuffix = useId();
  const idPrefix = `nglob-${idSuffix.replace(/:/g, '')}`;
  const [contactFormOpen, setContactFormOpen] = useState(false);
  const [callbackOpen, setCallbackOpen] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [chatOpen, setChatOpen] = useState(false);
  const [chatView, setChatView] = useState<ChatView>('assistant');
  const [mobile, setMobile] = useState(false);
  const [belowContact, setBelowContact] = useState(false);

  const hubRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const menuRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLElement | null>(null);
  const titlesRef = useRef<Partial<Record<ChatView, HTMLHeadingElement>>>({});
  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const chatWasOpenRef = useRef(false);
  const focusFrameRef = useRef(0);

  // Mobile detection
  useEffect(() => {
    const media = window.matchMedia('(max-width: 759px)');
    const update = () => {
      setMobile(media.matches);
      if (!media.matches) setMenuOpen(false);
    };
    update();
    media.addEventListener('change', update);
    return () => media.removeEventListener('change', update);
  }, []);

  // Below-contact scroll detection
  useEffect(() => {
    let frame = 0;
    const update = () => {
      frame = 0;
      if (hubRef.current) setBelowContact(hubRef.current.getBoundingClientRect().bottom <= 0);
    };
    const schedule = () => { if (!frame) frame = requestAnimationFrame(update); };
    const region = scrollRef.current;
    window.addEventListener('scroll', schedule, { passive: true });
    window.addEventListener('resize', schedule);
    region?.addEventListener('scroll', schedule, { passive: true });
    const observer = new ResizeObserver(schedule);
    if (hubRef.current) observer.observe(hubRef.current);
    update();
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      window.removeEventListener('scroll', schedule);
      window.removeEventListener('resize', schedule);
      region?.removeEventListener('scroll', schedule);
    };
  }, []);

  // Focus management on chat open/close
  useEffect(() => {
    const open = chatOpen;
    const view = chatView;
    const restore = !open && chatWasOpenRef.current;
    chatWasOpenRef.current = open;
    queueMicrotask(() => {
      if (open !== chatOpen || view !== chatView) return;
      if (open) titlesRef.current[view]?.focus({ preventScroll: true });
      else if (restore) triggerRef.current?.focus({ preventScroll: true });
    });
  }, [chatOpen, chatView, mobile]);

  // Cleanup focus frame
  useEffect(() => {
    return () => {
      if (typeof cancelAnimationFrame === 'function') cancelAnimationFrame(focusFrameRef.current);
    };
  }, []);

  function openChat(trigger: HTMLButtonElement, view: ChatView = chatView) {
    triggerRef.current = trigger;
    const alreadyOpen = chatOpen && view === chatView;
    setChatView(view);
    setChatOpen(true);
    if (alreadyOpen) titlesRef.current[view]?.focus({ preventScroll: true });
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'Escape') {
      if (chatOpen) { event.preventDefault(); setChatOpen(false); }
      else if (menuOpen) { setMenuOpen(false); menuRef.current?.focus(); }
    }
    if (event.key !== 'Tab' || !chatOpen || !mobile || !panelRef.current) return;
    const controls = Array.from(panelRef.current.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),textarea:not(:disabled)'))
      .filter(element => element.getClientRects().length > 0 && !element.closest('[hidden]'));
    const first = controls[0], last = controls.at(-1);
    if (event.shiftKey && (document.activeElement === first || document.activeElement === titlesRef.current[chatView] || !panelRef.current.contains(document.activeElement))) {
      event.preventDefault(); last?.focus();
    } else if (!event.shiftKey && (document.activeElement === last || !panelRef.current.contains(document.activeElement))) {
      event.preventDefault(); first?.focus();
    }
  }

  function keepFocusedControlVisible(event: React.FocusEvent<HTMLDivElement>) {
    const target = event.target;
    if (!mobile || !(target instanceof HTMLElement) || !target.matches('a,button,input,textarea') || !target.closest('.contact-page')) return;
    cancelAnimationFrame(focusFrameRef.current);
    focusFrameRef.current = requestAnimationFrame(() => {
      if (!scrollRef.current) return;
      const control = target.getBoundingClientRect(), region = scrollRef.current.getBoundingClientRect();
      if (control.top < region.top + 12 || control.bottom > region.bottom - 12) target.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    });
  }

  return (
    <div className={`nglob-contact${chatOpen ? ' has-chat' : ''}${props.className ? ` ${props.className}` : ''}`} onKeyDown={handleKeyDown}>
      <div className={`app-shell${callbackOpen ? ' callback-open' : ''}${belowContact ? ' is-below-contact' : ''}`} {...(chatOpen && mobile ? { inert: true } : {})}>
        <a href={`#${idPrefix}-main`} className="skip">Skip to content</a>
        {/* {props.showDemoNotice ?? true ? (<div className="reference-note">Design reference · no messages or requests are sent</div>) : null} */}
        <div className="scroll-region" ref={scrollRef} onFocus={keepFocusedControlVisible}>
          <SiteHeader
            menuOpen={menuOpen}
            onMenuToggle={() => setMenuOpen(open => !open)}
            menuId={`${idPrefix}-menu`}
            menuRef={(element) => { if (element) menuRef.current = element; }}
          />
          <main className="page contact-page" id={`${idPrefix}-main`}>
            <section className="contact-hero" aria-labelledby={`${idPrefix}-heading`}>
              <div className="hero-copy">
                <p className="page-label">Contact us</p>
                <h1 id={`${idPrefix}-heading`}>Let&apos;s talk.</h1>
                <p className="hero-lead">Questions about moving, delivery, storage or your booking? We&apos;re here to help.</p>
                {/* ── Replaced AI chat button with contact form toggle ── */}
                <button
                  type="button"
                  className="button chat-start"
                  aria-expanded={contactFormOpen}
                  aria-controls={`${idPrefix}-contact-form`}
                  onClick={() => setContactFormOpen(open => !open)}
                >
                  {contactFormOpen ? 'Hide contact form' : 'Contact us'}<Icon name="arrow" />
                </button>
                <div className="team-entry">
                  <button className="team-direct" type="button" aria-describedby={`${idPrefix}-reply-note`}
                    aria-controls={`${idPrefix}-chat`} aria-expanded={chatOpen && chatView === 'team'}
                    onClick={event => openChat(event.currentTarget, 'team')}>Message our team<Icon name="arrow" /></button>
                  <span id={`${idPrefix}-reply-note`}>Reply by email</span>
                </div>
              </div>
              <div className="connection-scene" aria-hidden="true">
                <div className="scene-halo" />
                <div className="brand-depth">{Array.from({ length: 30 }, (_, i) => <span key={i} className="depth-mark" />)}</div>
                <img className="moving-art" src={assets.dialogue.src} alt="" width={1536} height={1024} fetchPriority="high" />
              </div>
            </section>

            {/* ── Inline EmailJS contact form (below hero, above hub) ── */}
            <div
              id={`${idPrefix}-contact-form`}
              className="callback-expansion"
              role="region"
              aria-labelledby={`${idPrefix}-contact-form-title`}
              hidden={!contactFormOpen}
            >
              <h2 id={`${idPrefix}-contact-form-title`} className="sr-only">Send us a message</h2>
              <ContactUsForm idPrefix={idPrefix} />
            </div>

            <div className="contact-hub" ref={hubRef}>
              <div className="contact-band">
                <section className="contact-email" aria-labelledby={`${idPrefix}-email-title`}>
                  <h2 id={`${idPrefix}-email-title`}>Email us directly</h2>
                  <a href="mailto:support@nglob.com" className="email-address">support@nglob.com<Icon name="arrow" /></a>
                  <p>Include your booking reference if you have one.</p>
                  <span className="mail-app-note">Opens your email app.</span>
                </section>
                <section className={`callback${callbackOpen ? ' is-open' : ''}`} aria-labelledby={`${idPrefix}-callback-title`}>
                  <div className="callback-head">
                    <h2 id={`${idPrefix}-callback-title`}>Prefer a call?</h2>
                    <button type="button" className="callback-toggle" aria-expanded={callbackOpen}
                      aria-controls={`${idPrefix}-callback`} onClick={() => setCallbackOpen(open => !open)}>
                      <span>{callbackOpen ? 'Hide callback form' : 'Request a callback'}</span><Icon name="chevron" />
                    </button>
                    <p>Leave your number and tell us how we can help.</p>
                  </div>
                </section>
              </div>
              <div id={`${idPrefix}-callback`} className="callback-expansion" role="region" aria-labelledby={`${idPrefix}-callback-title`} hidden={!callbackOpen}>
                <CallbackForm requestTimeoutMs={props.requestTimeoutMs} idPrefix={idPrefix} onSubmit={props.onCallbackSubmit} onCheckStatus={props.onCallbackStatus} />
              </div>
            </div>
            <div className="contact-help"><span>Looking for answers?</span>
              <a href="/faq">Visit our Help Centre<Icon name="arrow" /></a>
            </div>
          </main>
          <SiteFooter />
        </div>
        <div className="chat-dock">
          <button type="button" className="launcher" aria-label="Open Nglob chat" aria-expanded={chatOpen}
            aria-controls={`${idPrefix}-chat`} onClick={event => openChat(event.currentTarget)}><Icon name="chat" /><span>Chat</span></button>
        </div>
      </div>
      <ContactChat requestTimeoutMs={props.requestTimeoutMs} open={chatOpen} mobile={mobile} view={chatView} onViewChange={setChatView} onClose={() => setChatOpen(false)}
        onPanelRef={element => { panelRef.current = element; }} onTitleRef={(view, element) => { titlesRef.current[view] = element; }} idPrefix={idPrefix} showDemoNotice={props.showDemoNotice ?? true}
        onTeamSubmit={props.onTeamSubmit} onTeamStatus={props.onTeamStatus} onAssistantMessage={props.onAssistantMessage} />
    </div>
  );
}

'use client';
import { getAccessToken } from '@/lib/auth-token';

import { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { uploadFile } from '@/app/actions/upload';
import { getImageUrl } from '@/lib/image-url';

const API = process.env.API_URL;

interface DocumentItem {
  id: string;
  docType: string;
  label: string;
  description?: string;
  category: 'driver' | 'vehicle';
  status: 'NOT_PROVIDED' | 'UPLOADED' | 'APPROVED' | 'REJECTED';
  fileName?: string;
  fileUrl?: string;
  reviewNote?: string;
}

// Descriptions for each doc type
const DOC_DESCRIPTIONS: Record<string, { description?: string; category: 'driver' | 'vehicle' }> = {
  dvla_driving_license: { description: 'Must be a full licence, not provisional', category: 'driver' },
  dvla_check_code: { description: 'Must be generated on the government webpage or by calling the DVLA', category: 'driver' },
  pco_driver_badge: { description: 'Your photo, PHL number, name and expiry date must be clearly visible on the document, and not excessively faded', category: 'driver' },
  private_hire_driver_licence: { description: undefined, category: 'driver' },
  bank_statement: { description: 'Submit a bank statement for the account you want your @Removals payments sent to. The bank statement must: be issued in English from a legitimate bank (only personal account is accepted); not be older than 3 months.', category: 'driver' },
  private_hire_vehicle_licence: { description: undefined, category: 'vehicle' },
  mot_test_certificate: { description: 'For Private Hire purposes, the MOT test must be completed every 6 months throughout the validity of your Private Hire License.', category: 'vehicle' },
  v5c_logbook: { description: "We can accept any page of the V5C document or an E-logbook, as long as the following information is included: vehicle Registration Number (VRM), make, and model; registered keeper's details (name and address); V5C document number", category: 'vehicle' },
  insurance_certificate: { description: 'You must be named as the Policyholder, or be listed under the section "Persons entitled to drive". The cover type must explicitly state "Hire and Reward" or "Private Hire".', category: 'vehicle' },
};

export default function DriverDocumentsPage() {
  const router = useRouter();
  const [documents, setDocuments] = useState<DocumentItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [submitError, setSubmitError] = useState('');
  const [uploadingId, setUploadingId] = useState<string | null>(null);
  const [previewDocUrl, setPreviewDocUrl] = useState<string | null>(null);
  const [previewDocName, setPreviewDocName] = useState<string | null>(null);
  const fileInputRefs = useRef<Record<string, HTMLInputElement | null>>({});

  useEffect(() => {
    const token = getAccessToken();
    if (!token) {
      window.location.href = '/driver/apply';
      return;
    }
    fetchDocuments();
  }, [router]);

  const fetchDocuments = async () => {
    const token = getAccessToken();
    try {
      const res = await fetch(`${API}/driver/documents`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error('Failed to fetch documents');
      const data = await res.json();
      // Enrich with descriptions and categories
      const enriched: DocumentItem[] = data.map((d: any) => ({
        ...d,
        description: DOC_DESCRIPTIONS[d.docType]?.description,
        category: DOC_DESCRIPTIONS[d.docType]?.category || 'driver',
        status: d.status || 'NOT_PROVIDED',
      }));
      setDocuments(enriched);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const uploadedCount = documents.filter(d => d.status !== 'NOT_PROVIDED').length;
  const totalCount = documents.length || 9;

  const handleUpload = (docType: string) => {
    const input = fileInputRefs.current[docType];
    if (input) input.click();
  };

  const handleFileChange = async (doc: DocumentItem, files: FileList | null) => {
    if (!files || files.length === 0) return;
    if (files.length > 5) {
      alert('You can only upload up to 5 files at once.');
      return;
    }
    const token = getAccessToken();
    setUploadingId(doc.docType);
    try {
      const fileNames = [];
      const fileUrls = [];

      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        const formData = new FormData();
        formData.append('file', file);
        formData.append('folder', 'nglob/documents');

        let url: string;
        try {
          const uploadRes = await fetch(`${API}/driver/upload-file`, {
            method: 'POST',
            body: formData,
          });
          if (!uploadRes.ok) {
            const errBody = await uploadRes.text().catch(() => '');
            throw new Error(`Upload failed (${uploadRes.status}): ${errBody}`);
          }
          const uploadData = await uploadRes.json();
          url = uploadData.url;
        } catch (directErr: any) {
          console.warn('[DOC UPLOAD] Direct backend upload failed, trying fallback action:', directErr.message);
          url = await uploadFile(formData);
        }

        fileNames.push(file.name);
        fileUrls.push(url);
      }

      // Then send the URLs to the backend
      const res = await fetch(`${API}/driver/documents/upload`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          docType: doc.docType,
          label: doc.label,
          fileName: JSON.stringify(fileNames),
          fileUrl: JSON.stringify(fileUrls),
        }),
      });
      if (!res.ok) {
        const errBody = await res.text().catch(() => '');
        console.error('[DOC UPLOAD] Backend API failed:', res.status, errBody);
        throw new Error(`Backend upload failed (${res.status}): ${errBody}`);
      }
      await fetchDocuments();
    } catch (err: any) {
      console.error('[DOC UPLOAD] Error:', err);
      alert(`Upload failed: ${err.message || 'Unknown error'}`);
    } finally {
      setUploadingId(null);
    }
  };

  const handleReplace = (docType: string) => {
    const input = fileInputRefs.current[docType];
    if (input) {
      input.value = '';
      input.click();
    }
  };

  const handleSubmit = async () => {
    const token = getAccessToken();
    setSubmitting(true);
    setSubmitError('');
    try {
      const res = await fetch(`${API}/driver/documents/submit`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        throw new Error(errorData.message || 'Submit failed');
      }
      setSubmitted(true);
    } catch (err: any) {
      console.error(err);
      setSubmitError(err.message || 'Submit failed');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-gray-200 border-t-blue-600 rounded-full animate-spin" />
      </div>
    );
  }

  if (submitted) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center px-6">
        <div className="text-center max-w-md">
          <div className="w-16 h-16 bg-green-50 rounded-2xl flex items-center justify-center text-3xl mx-auto mb-5">🎉</div>
          <h2 className="text-xl font-bold text-gray-900 mb-2">Documents Submitted!</h2>
          <p className="text-sm text-gray-500 mb-6 leading-relaxed">
            Thank you! Our team will review your documents within 3 business days.
            You&apos;ll receive an email when verification is complete.
          </p>
          <div className="bg-yellow-50 border border-yellow-100 rounded-xl p-4 mb-6">
            <div className="flex items-center justify-center gap-3">
              <span className="w-2.5 h-2.5 bg-yellow-500 rounded-full animate-pulse" />
              <span className="text-sm font-semibold text-yellow-700">Status: Under Review</span>
            </div>
          </div>
          <button
            onClick={() => router.push('/')}
            className="w-full border border-gray-200 text-gray-600 py-3 rounded-xl text-sm font-medium hover:bg-gray-50 transition-colors"
          >
            Back to Home
          </button>
        </div>
      </div>
    );
  }

  const driverDocs = documents.filter(d => d.category === 'driver');
  const vehicleDocs = documents.filter(d => d.category === 'vehicle');

  return (
    <div className="min-h-screen bg-white">
      <div className="max-w-5xl mx-auto px-6 py-12">
        {/* Header */}
        <div className="flex items-start justify-between mb-2">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 mb-2">Complete your driver profile</h1>
            <p className="text-sm text-gray-500">
              Thank you, your email has been verified. You can now continue setting up your driver profile.
            </p>
          </div>
          <div className="text-right flex-shrink-0 ml-8">
            <p className="text-xs text-gray-400 mb-0.5">Progress</p>
            <p className="text-sm font-bold text-gray-900">{uploadedCount}/{totalCount} uploaded</p>
          </div>
        </div>

        {/* Progress bar */}
        <div className="w-full bg-gray-100 rounded-full h-1.5 mb-10">
          <div
            className="bg-blue-600 h-1.5 rounded-full transition-all duration-500"
            style={{ width: `${(uploadedCount / totalCount) * 100}%` }}
          />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
          {/* Left — Documents */}
          <div className="lg:col-span-2">
            {/* Driver documents */}
            <h3 className="text-sm font-bold text-gray-900 mb-4">Driver documents</h3>
            <div className="space-y-3 mb-10">
              {driverDocs.map(doc => (
                <DocumentRow
                  key={doc.docType}
                  doc={doc}
                  isUploading={uploadingId === doc.docType}
                  onUpload={() => handleUpload(doc.docType)}
                  onReplace={() => handleReplace(doc.docType)}
                  fileInputRef={(el) => { fileInputRefs.current[doc.docType] = el; }}
                  onFileChange={(files) => handleFileChange(doc, files)}
                  onPreview={(url, name) => {
                    setPreviewDocUrl(url);
                    setPreviewDocName(name || doc.label);
                  }}
                />
              ))}
            </div>

            {/* Vehicle documents */}
            <h3 className="text-sm font-bold text-gray-900 mb-4">Vehicle documents</h3>
            <div className="space-y-3 mb-10">
              {vehicleDocs.map(doc => (
                <DocumentRow
                  key={doc.docType}
                  doc={doc}
                  isUploading={uploadingId === doc.docType}
                  onUpload={() => handleUpload(doc.docType)}
                  onReplace={() => handleReplace(doc.docType)}
                  fileInputRef={(el) => { fileInputRefs.current[doc.docType] = el; }}
                  onFileChange={(files) => handleFileChange(doc, files)}
                  onPreview={(url, name) => {
                    setPreviewDocUrl(url);
                    setPreviewDocName(name || doc.label);
                  }}
                />
              ))}
            </div>

            {/* Submit */}
            {submitError && (
              <div className="mb-4 text-sm text-red-600 bg-red-50 p-3 rounded-lg border border-red-100">
                {submitError}
              </div>
            )}
            <button
              onClick={handleSubmit}
              disabled={submitting || uploadedCount === 0}
              className="bg-gray-900 text-white px-8 py-3 rounded-lg text-sm font-semibold hover:bg-gray-800 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
            >
              {submitting ? 'Submitting…' : 'Submit for review'}
            </button>
          </div>

          {/* Right — Tips sidebar */}
          <div className="hidden lg:block">
            <div className="bg-blue-50 border border-blue-100 rounded-2xl p-6 sticky top-24">
              <h4 className="text-sm font-bold text-gray-900 mb-3">Upload tips</h4>
              <p className="text-xs text-gray-600 leading-relaxed mb-4">
                Every file must be a good-quality scan or photo of your current original document, with all four corners clearly visible.
              </p>
              <p className="text-xs text-gray-500 mb-5">
                File types: JPG, PNG, PDF. Max 5 MB per file. Up to 5 files per document.
              </p>

              <h4 className="text-sm font-bold text-gray-900 mb-2">About documents</h4>
              <p className="text-xs text-gray-600 leading-relaxed mb-5">
                You can find examples of documents with full requirements{' '}
                <Link href="/faq" className="text-blue-600 underline">on this page</Link>.
              </p>

              <h4 className="text-sm font-bold text-gray-900 mb-2">What happens next</h4>
              <p className="text-xs text-gray-600 leading-relaxed mb-5">
                Our team reviews documents within 3 business days. You&apos;ll receive an email when verification is complete.
