function DocumentRow({
  doc,
  isUploading,
  onUpload,
  onReplace,
  fileInputRef,
  onFileChange,
  onPreview,
}: {
  doc: DocumentItem;
  isUploading: boolean;
  onUpload: () => void;
  onReplace: () => void;
  fileInputRef: (el: HTMLInputElement | null) => void;
  onFileChange: (files: FileList | null) => void;
  onPreview?: (url: string, name: string) => void;
}) {
  return (
    <div className="border border-gray-200 rounded-xl p-4 flex items-start gap-4">
      {/* Left bar accent */}
      <div className={`w-1 self-stretch rounded-full flex-shrink-0 ${
        doc.status === 'UPLOADED' ? 'bg-amber-400' :
        doc.status === 'APPROVED' ? 'bg-green-500' :
        doc.status === 'REJECTED' ? 'bg-red-500' :
        'bg-gray-200'
      }`} />

      {/* Info */}
      <div className="flex-1 min-w-0">
        <p className="text-sm font-semibold text-gray-900">{doc.label}</p>
        {doc.description && (
          <p className="text-xs text-gray-500 mt-1 leading-relaxed">{doc.description}</p>
        )}
        {doc.fileName && (
          <div className="flex flex-col gap-2 mt-2">
            {(() => {
              let parsedNames = [doc.fileName];
              let parsedUrls = [doc.fileUrl];
              try {
                if (doc.fileName.startsWith('[')) parsedNames = JSON.parse(doc.fileName);
                if (doc.fileUrl && doc.fileUrl.startsWith('[')) parsedUrls = JSON.parse(doc.fileUrl);
              } catch (e) {}

              return parsedNames.map((name, idx) => (
                <div key={idx} className="flex items-center gap-3">
                  <p className="text-xs font-medium text-green-700 truncate bg-green-50 px-2 py-1 rounded-md border border-green-100 flex items-center gap-1.5 max-w-[200px]" title={name}>
                    <span>📄</span> {name}
                  </p>
                  {parsedUrls[idx] && onPreview && (
                    <button
                      onClick={() => onPreview(getImageUrl(parsedUrls[idx]!), name)}
                      className="text-xs font-bold text-blue-600 hover:text-blue-700 hover:underline transition-colors flex items-center gap-1"
                    >
                      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" strokeWidth={2} viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                      View
                    </button>
                  )}
                </div>
              ));
            })()}
          </div>
        )}
        {doc.reviewNote && doc.status === 'REJECTED' && (
          <p className="text-xs text-red-500 mt-1.5">⚠️ {doc.reviewNote}</p>
        )}
      </div>

      {/* Status + action */}
      <div className="flex items-center gap-2 flex-shrink-0">
        <span className={`text-xs font-medium px-2.5 py-1 rounded-full ${
          doc.status === 'UPLOADED' ? 'bg-amber-50 text-amber-700 border border-amber-200' :
          doc.status === 'APPROVED' ? 'bg-green-50 text-green-700 border border-green-200' :
          doc.status === 'REJECTED' ? 'bg-red-50 text-red-700 border border-red-200' :
          'bg-gray-50 text-gray-500 border border-gray-200'
        }`}>
          {doc.status === 'UPLOADED' ? 'Uploaded' :
           doc.status === 'APPROVED' ? 'Approved' :
           doc.status === 'REJECTED' ? 'Rejected' :
           'Not provided'}
        </span>

        {isUploading ? (
          <div className="w-5 h-5 border-2 border-gray-200 border-t-blue-600 rounded-full animate-spin" />
        ) : doc.status === 'UPLOADED' || doc.status === 'REJECTED' ? (
          <button
            onClick={onReplace}
            className="text-xs font-medium text-gray-600 border border-gray-200 px-3 py-1.5 rounded-lg hover:bg-gray-50 transition-colors"
          >
            Replace
          </button>
        ) : doc.status === 'APPROVED' ? (
          <button
            onClick={onReplace}
            className="text-xs font-medium text-gray-600 border border-gray-200 px-3 py-1.5 rounded-lg hover:bg-gray-50 transition-colors"
          >
            Replace
          </button>
        ) : (
          <button
            onClick={onUpload}
            className="text-xs font-medium text-gray-600 border border-gray-200 px-3 py-1.5 rounded-lg hover:bg-gray-50 transition-colors"
          >
            Upload
          </button>
        )}
      </div>

      {/* Hidden file input */}
      <input
        ref={fileInputRef}
        type="file"
        multiple
        accept=".jpg,.jpeg,.png,.pdf"
        className="hidden"
        onChange={e => onFileChange(e.target.files)}
      />
    </div>
  );
}

