const formatDate = (d: string) => {
  const date = new Date(d);
  return date.toLocaleDateString('en-GB', {
    weekday: 'short',
    day: 'numeric',
    month: 'short',
    year: 'numeric',
  });
};

const formatSlot = (slot?: string) => {
  if (!slot) return '';
  return slot.replace('SLOT_', '').replace('_', ':00 – ') + ':00';
};

const STATUS_STYLE: Record<string, string> = {
  DELIVERED: 'bg-green-50 text-green-700 border-green-200',
  UNREACHABLE: 'bg-red-50 text-red-600 border-red-200',
  CANCELLED: 'bg-gray-100 text-gray-500 border-gray-200',
};

const STATUS_LABEL: Record<string, string> = {
  DELIVERED: 'Delivered',
  UNREACHABLE: 'Unreachable',
  CANCELLED: 'Cancelled',
};

// Simple img wrapper — no crossOrigin / referrerPolicy so the browser
// treats it exactly like typing the URL into the address bar.
function SafeImg({
  src,
  alt,
  className,
}: {
  src: string;
  alt: string;
  className?: string;
}) {
  const [broken, setBroken] = useState(false);

  if (broken) {
    return (
      <div className={`flex items-center justify-center bg-gray-100 text-gray-400 text-xs font-medium ${className}`}>
        No image
      </div>
    );
  }

  return (
    <img
      key={src}
      src={src}
      alt={alt}
      className={className}
      onError={() => setBroken(true)}
    />
  );
}

