  useEffect(() => {
    fetchHistory();
  }, []);

  const fetchHistory = async () => {
    try {
      // Use the new history endpoint which returns all past completed jobs
      const res = await fetch(`${API}/driver/history`, {
        headers: authHeaders(),
      });
      if (!res.ok) throw new Error('Failed to load history');
      const data: any[] = await res.json();

      // Keep only terminal statuses
      const done = data.filter(
        (b) =>
          b.status === 'DELIVERED' ||
          b.status === 'UNREACHABLE' ||
          b.status === 'CANCELLED',
      );

      // Most-recent first
      done.sort(
        (a, b) =>
          new Date(b.pickupDate || b.updatedAt || b.createdAt).getTime() -
          new Date(a.pickupDate || a.updatedAt || a.createdAt).getTime(),
      );
      setHistory(done);
