'use client';

import { getAccessToken } from '@/lib/auth-token';

import React, { useEffect, useState, useRef } from 'react';
import { usePrices } from '@/hooks/usePrices';
import { uploadFile } from '@/app/actions/upload';
import { io } from 'socket.io-client';
import { LifoModal } from '@/components/LifoModal';

const API = process.env.API_URL;
const authHeaders = () => ({
  Authorization: `Bearer ${getAccessToken()}`,
  'Content-Type': 'application/json',
});

import { getImageUrl } from '@/lib/image-url';

// Format time slot to human-readable
const formatSlot = (slot: string) => {
  if (!slot) return '';
  return slot.replace('SLOT_', '').replace('_', ':00 – ') + ':00';
};

// Format date nicely
const formatDate = (d: string) => {
  const date = new Date(d);
  const today = new Date();
  const isToday = date.toDateString() === today.toDateString();
  if (isToday) return 'Today';
  return date.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });
};

type StopType = 'PICKUP' | 'DROPOFF';

interface RouteStop {
  id: string;
  type: StopType;
  booking: any;
  status: 'pending' | 'active' | 'done';
}

interface DriverRoute {
  id: string; 
  type: 'FEW_ITEMS' | 'FULL_HOUSE';
  bookings: any[];
  isDone: boolean;
  isActive: boolean;
  stops: RouteStop[];
}

function groupAssignmentsIntoRoutes(assignments: any[]): DriverRoute[] {
  const routes: DriverRoute[] = [];
  const groupedByDate: Record<string, any[]> = {};

  for (const b of assignments) {
    // Skip only CANCELLED — keep DELIVERED so completed routes show up
    if (b.status === 'CANCELLED') continue;
    // D5: Group by London date to handle BST correctly
    const d = new Date(b.pickupDate).toLocaleDateString('en-GB', { timeZone: 'Europe/London', year: 'numeric', month: '2-digit', day: '2-digit' }).split('/').reverse().join('-');
    if (!groupedByDate[d]) groupedByDate[d] = [];
    groupedByDate[d].push(b);
  }

  for (const [date, dayBookings] of Object.entries(groupedByDate)) {
    const full = dayBookings.filter(b => b.type === 'FULL_HOUSE');
    const partial = dayBookings.filter(b => b.type === 'FEW_ITEMS');

    for (const b of full) {
      routes.push({
        id: `route-${b.id}`,
        type: 'FULL_HOUSE',
        bookings: [b],
        isDone: b.status === 'DELIVERED' || b.status === 'UNREACHABLE',
        isActive: false,
        stops: []
      });
    }

    if (partial.length > 0) {
      const isDone = partial.every(b => b.status === 'DELIVERED' || b.status === 'UNREACHABLE');
      routes.push({
        id: `route-batch-${date}`,
        type: 'FEW_ITEMS',
        bookings: partial,
        isDone,
        isActive: false,
        stops: []
      });
    }
  }

  for (const r of routes) {
    if (r.type === 'FULL_HOUSE') {
      const b = r.bookings[0];
      r.stops = [
        { id: `pickup-${b.id}`, type: 'PICKUP', booking: b, status: 'pending' },
        { id: `dropoff-${b.id}`, type: 'DROPOFF', booking: b, status: 'pending' }
      ];
    } else {
      // D5: Sort by time slot correctly — map SLOT_HH to numeric hour, EXACT sorts last
      const slotOrder = (s: string) => {
        if (!s || s === 'EXACT') return 99;
        const m = s.match(/SLOT_(\d+)/);
        return m ? parseInt(m[1], 10) : 98;
      };
      r.bookings.sort((a, b) => slotOrder(a.pickupTimeSlot) - slotOrder(b.pickupTimeSlot) || a.id.localeCompare(b.id));
      const pickups = r.bookings.map(b => ({ id: `pickup-${b.id}`, type: 'PICKUP' as StopType, booking: b, status: 'pending' as any }));
      const dropoffs = [...r.bookings].reverse().map(b => ({ id: `dropoff-${b.id}`, type: 'DROPOFF' as StopType, booking: b, status: 'pending' as any }));
      r.stops = [...pickups, ...dropoffs];
    }

    let foundActive = false;
    for (const s of r.stops) {
      // D1 fix: PICKUP is only done once items are fully loaded onto the truck.
      // ARRIVED and PACKED are intermediate sub-steps of the PICKUP stop,
      // not a reason to advance to the DROPOFF stop.
      const PICKUP_DONE_STATUSES = ['LOADED', 'IN_TRANSIT', 'UNLOADING', 'DELIVERED', 'UNREACHABLE'];
      const isDone = s.type === 'PICKUP'
        ? PICKUP_DONE_STATUSES.includes(s.booking.status)
        : (s.booking.status === 'DELIVERED' || s.booking.status === 'UNREACHABLE');

      if (isDone) {
        s.status = 'done';
      } else if (!foundActive && !r.isDone) {
        s.status = 'active';
        foundActive = true;
      } else {
        s.status = 'pending';
      }
    }
  }

  routes.sort((a, b) => {
    if (a.isDone !== b.isDone) return a.isDone ? 1 : -1;
    return a.bookings[0].pickupDate.localeCompare(b.bookings[0].pickupDate);
  });

  const firstActive = routes.find(r => !r.isDone);
  if (firstActive) firstActive.isActive = true;

  return routes;
}

export default function DriverAssignmentsPage() {
  const [assignments, setAssignments] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [updatingId, setUpdatingId] = useState<string | null>(null);

  // Completion Modal State
  const { prices, ready: pricesReady } = usePrices();
  const [completionModalOpen, setCompletionModalOpen] = useState(false);
  const [completingBooking, setCompletingBooking] = useState<any>(null);
  const [extraTimeNeeded, setExtraTimeNeeded] = useState<boolean | null>(null);
  const [extraHours, setExtraHours] = useState(0.5);
  const [extraTimePayment, setExtraTimePayment] = useState<'cash' | 'debt' | null>(null);

  // D6: Per-booking extras state to prevent bleed between batched bookings
  const [extraPackingNeeded, setExtraPackingNeededMap] = useState<Record<string, boolean>>({});
  const [extraPackingHours, setExtraPackingHoursMap] = useState<Record<string, number>>({});
  const [extraPackingMaterialsCost, setExtraPackingMaterialsCostMap] = useState<Record<string, number>>({});
  const [signatureMode, setSignatureMode] = useState(false);


  // Extra Items Modal State
  const [extraPromptOpen, setExtraPromptOpen] = useState(false);
  const [activeExtraBooking, setActiveExtraBooking] = useState<any>(null);
  const [showExtraForm, setShowExtraForm] = useState(false);
  const [extraItemPhoto, setExtraItemPhoto] = useState<string | null>(null);
  const [extraItemPrice, setExtraItemPrice] = useState<number | ''>('');
  const [extraPaymentMethod, setExtraPaymentMethod] = useState<'cash' | 'card' | 'debt' | null>(null);
  const [extraItemsData, setExtraItemsData] = useState<Record<string, any>>({});

  // Crew: track this driver's own ID to conditionally hide action buttons
  const [myDriverId, setMyDriverId] = useState<string | null>(null);

  // Loading Step State
  const [truckPhotos, setTruckPhotos] = useState<Record<string, string>>({});
  const [deliveryPhotos, setDeliveryPhotos] = useState<Record<string, string>>({});
  const [uploadingPhoto, setUploadingPhoto] = useState(false);
  const [showGuides, setShowGuides] = useState<Record<string, boolean>>({});

  // Item Flagging State
  const [flaggingItem, setFlaggingItem] = useState<{ bookingId: string, itemId: string } | null>(null);
  const [flagNote, setFlagNote] = useState('');

  // LIFO Modal State
  const [lifoBooking, setLifoBooking] = useState<any>(null);

  useEffect(() => {
    fetchAssignments();

    let socket: ReturnType<typeof io> | undefined;
    let cancelled = false;

    (async () => {
      try {
        const res = await fetch(`${API}/driver/status`, { headers: authHeaders() });
        if (!res.ok || cancelled) return;
        const driver = await res.json();
        if (!driver?.id || cancelled) return;

        setMyDriverId(driver.id);
        const socketUrl = API?.replace(/\/api$/, '') || 'http://localhost:3001';
        socket = io(`${socketUrl}/tracking`, {
          auth: (cb: (o: any) => void) => cb({ token: getAccessToken() }), // fresh token on every reconnect
          transports: ['polling', 'websocket'],
        });
        socket.on('connect', () => socket!.emit('subscribe-driver', { driverId: driver.id })); // re-join room
        socket.on('assignments-updated', fetchAssignments);
      } catch (err) {
        console.error('Failed to init socket', err);
      }
    })();

    return () => { cancelled = true; socket?.disconnect(); };
  }, []);

  const fetchAssignments = async () => {
    try {
      const res = await fetch(`${API}/driver/assignments`, { headers: authHeaders() });
      if (!res.ok) throw new Error('Failed to fetch assignments');
      const data = await res.json();
      setAssignments(data || []);
      if (data && data.length > 0) {
        setTruckPhotos(prev => {
          const next = { ...prev };
          let changed = false;
          data.forEach((b: any) => {
            if (b.loadProofPhoto && next[b.id] !== b.loadProofPhoto) {
              next[b.id] = b.loadProofPhoto;
              changed = true;
            }
          });
          return changed ? next : prev;
        });
      }
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const updateStatus = async (bookingId: string, status: string, extraPayload: any = {}) => {
    setUpdatingId(bookingId);
    try {
      const res = await fetch(`${API}/driver/assignments/${bookingId}/status`, {
        method: 'PATCH',
        headers: authHeaders(),
        body: JSON.stringify({ status, ...extraPayload }),
      });
      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        const msgs = Array.isArray(errData.message) ? errData.message : [errData.message || 'Failed to update status'];
        throw new Error(`ERROR: ${msgs.join(', ')}`);
      }
      fetchAssignments();
      return true;
    } catch (err: any) {
      alert(err.message);
      return false;
    } finally {
      setUpdatingId(null);
    }
  };

  // X1 fix: Dedicated undo via the new POST /driver/assignments/:id/undo endpoint.
  // Server enforces the allowed undo map and rejects DELIVERED undos.
  const undoStatus = async (bookingId: string) => {
    setUpdatingId(bookingId);
    try {
      const res = await fetch(`${API}/driver/assignments/${bookingId}/undo`, {
        method: 'POST',
        headers: authHeaders(),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.message || 'Cannot undo this step');
      }
      fetchAssignments();
    } catch (err: any) {
      alert(err.message);
    } finally {
      setUpdatingId(null);
    }
  };

  const handleConfirmDeliveryClick = (booking: any) => {
    setCompletingBooking(booking);
    setExtraTimeNeeded(null);
    setExtraHours(0.5);
    setExtraTimePayment(null);
    setCompletionModalOpen(true);
  };

  const submitCompletion = () => {
    setSignatureMode(true);
  };

  const finalComplete = async (signatureDataUrl: string) => {
    if (!completingBooking) return;

    const success = await updateStatus(completingBooking.id, 'DELIVERED', {
      extraTimeHours: extraTimeNeeded ? extraHours : 0,
      extraTimePayment: extraTimeNeeded ? extraTimePayment : null,
      customerSignature: signatureDataUrl,
      deliveryPhoto: deliveryPhotos[completingBooking.id],
    });
    if (success) {
      setCompletionModalOpen(false);
      setSignatureMode(false);
    }
  };

  const handleArrivedClick = async (booking: any) => {
    const success = await updateStatus(booking.id, 'ARRIVED');
    // D7: Only open extra-items modal if server accepts ARRIVED
    if (success) {
      setActiveExtraBooking(booking);
      setExtraPromptOpen(true);
      setShowExtraForm(false);
      setExtraItemPhoto(null);
      setExtraItemPrice('');
      setExtraPaymentMethod(null);
    }
  };

  const saveExtraItem = () => {
    if (activeExtraBooking && extraItemPhoto && extraItemPrice && extraPaymentMethod) {
      setExtraItemsData(prev => ({
        ...prev,
        [activeExtraBooking.id]: {
          photo: extraItemPhoto,
          price: Number(extraItemPrice),
          paymentMethod: extraPaymentMethod
        }
      }));
    }
    setExtraPromptOpen(false);
  };

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>, setter: (url: string) => void) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploadingPhoto(true);
    try {
      // Show local preview immediately
      const localPreview = URL.createObjectURL(file);
      setter(localPreview);
      // D8 fix: Upload to Azure via Server Action instead of ephemeral local disk
      const formData = new FormData();
      formData.append('file', file);

      const url = await uploadFile(formData);
      setter(url);
    } catch (err) {
      console.error('Photo upload failed:', err);
      alert('Photo upload failed. Please try again.');
      setter('');
    } finally {
      setUploadingPhoto(false);
    }
  };

  const handlePackCompleteClick = (booking: any) => {
    // D4 fix: key must be extraPackingTimeHours to match what the backend reads.
    updateStatus(booking.id, 'PACKED', {
      extraPackingTimeHours: extraPackingNeeded[booking.id] ? (extraPackingHours[booking.id] || 0) : 0,
      extraPackingMaterialsCost: extraPackingNeeded[booking.id] ? (extraPackingMaterialsCost[booking.id] || 0) : 0
    });
  };

  const submitLoaded = (booking: any) => {
    updateStatus(booking.id, 'LOADED', {
      truckPhoto: truckPhotos[booking.id],
      extraItem: extraItemsData[booking.id] || null,
      extraPackingTimeHours: extraPackingNeeded[booking.id] ? (extraPackingHours[booking.id] || 0) : undefined,
      extraPackingMaterialsCost: extraPackingNeeded[booking.id] ? (extraPackingMaterialsCost[booking.id] || 0) : undefined,
    });
  };

  const submitFlag = async (bookingId: string, itemId: string) => {
    try {
      const res = await fetch(`${API}/driver/assignments/${bookingId}/items/${itemId}/flag`, {
        method: 'PATCH',
        headers: authHeaders(),
        body: JSON.stringify({ note: flagNote })
      });
      if (!res.ok) throw new Error('Failed to flag item');
      fetchAssignments();
      setFlaggingItem(null);
      setFlagNote('');
    } catch (err) {
      alert('Failed to flag item');
    }
  };

  if (loading) return (
    <div className="space-y-4">
      {[1, 2].map(i => (
        <div key={i} className="animate-pulse">
          <div className="h-4 bg-gray-100 rounded w-32 mb-4" />
          <div className="h-48 bg-gray-50 rounded-2xl" />
        </div>
      ))}
    </div>
  );

  if (error) return (
    <div className="bg-red-50 border border-red-100 rounded-xl p-4 text-sm text-red-600">{error}</div>
  );


  const routes = groupAssignmentsIntoRoutes(assignments);
  const activeRoutes = routes.filter(r => !r.isDone);
  const completedRoutes = routes.filter(r => r.isDone);
  const nextRoute = activeRoutes[0];
  const now = new Date();

  return (
    <div>
