      <div className="mb-8">
        <h1 className="text-2xl font-bold text-gray-900 mb-1">My Route Assignments</h1>
        {routes.length > 0 ? (
          <p className="text-sm text-gray-500">
            {activeRoutes.length} active routes · {completedRoutes.length} completed
            {nextRoute && (
              <span className="text-blue-600 font-medium ml-2">
                · Next Route: {formatDate(nextRoute.bookings[0].pickupDate)}
