                className={`bg-white rounded-2xl border overflow-hidden transition-all ${
                  isDone ? 'border-gray-100 opacity-60' : isActive ? 'border-blue-200 shadow-md ring-1 ring-blue-100' : 'border-gray-200 shadow-sm'
