                      <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold ${
                        isDone ? 'bg-green-50 text-green-600' : isActive ? 'bg-blue-600 text-white shadow-sm' : 'bg-gray-100 text-gray-600'
