                                    <div className="flex items-center gap-2 mb-2">
                                      <span className="w-6 h-6 rounded-md bg-amber-100 text-amber-600 flex items-center justify-center flex-shrink-0">
                                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2 2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"/></svg>
                                      </span>
                                      <span className="font-bold text-amber-900">Packing Materials</span>
                                    </div>
                                    <div className="pl-8 space-y-1 text-amber-800">
                                      {booking.packingMaterials.map((mat: any, i: number) => (
                                        <div key={mat.id || i} className="flex justify-between">
                                          <span>{mat.type?.replace(/_/g, ' ').toLowerCase().replace(/\b\w/g, (l: string) => l.toUpperCase())}</span>
                                          <span className="font-bold">×{mat.quantity} · £{(mat.pricePerUnit * mat.quantity).toFixed(2)}</span>
                                        </div>
                                      ))}
                                      <div className="pt-1 mt-1 border-t border-amber-200 flex justify-between font-bold">
                                        <span>Materials Total</span>
                                        <span>£{booking.packingMaterials.reduce((sum: number, m: any) => sum + m.pricePerUnit * m.quantity, 0).toFixed(2)}</span>
                                      </div>
                                    </div>
                                  </div>
                                )}

                                {/* Access info — stairs, parking, exact time */}
                                {((booking.stairsFlights ?? 0) > 0 || (booking.parkingDistance ?? 0) > 20 || booking.exactPickupTime) && (
                                  <div className="bg-orange-50 border border-orange-100 rounded-xl p-3 text-xs">
                                    <div className="flex items-center gap-2 mb-2">
                                      <span className="w-6 h-6 rounded-md bg-orange-100 text-orange-600 flex items-center justify-center flex-shrink-0 text-sm">🪜</span>
                                      <span className="font-bold text-orange-900">Access Info</span>
                                    </div>
                                    <div className="pl-8 space-y-1 text-orange-800">
                                      {(booking.stairsFlights ?? 0) > 0 && (
                                        <p><strong>{booking.stairsFlights} flight{booking.stairsFlights > 1 ? 's' : ''} of stairs</strong> — no lift</p>
                                      )}
                                      {(booking.parkingDistance ?? 0) > 20 && (
                                        <p>Parking <strong>{booking.parkingDistance}m</strong> from entrance</p>
                                      )}
                                      {booking.exactPickupTime && (
                                        <p>Exact arrival: <strong>{booking.exactPickupTime}</strong></p>
                                      )}
                                    </div>
                                  </div>
                                )}

                                {/* Notes for driver */}
                                {booking.notesForDriver && (
                                  <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-3 text-xs">
                                    <div className="flex items-start gap-2">
                                      <span className="text-yellow-600 text-sm mt-0.5">📝</span>
                                      <div>
                                        <p className="font-bold text-yellow-900 mb-1">Notes from customer</p>
                                        <p className="text-yellow-800 leading-snug">{booking.notesForDriver}</p>
                                      </div>
                                    </div>
                                  </div>
                                )}
                              </div>
                            )}

                            {/* Render Active Actions */}
                            {state === 'active' && !canAct && (
                              <p className="mt-3 text-xs font-semibold text-gray-500 bg-gray-100 rounded-lg px-3 py-2">
                                You are crew on this job. The lead driver updates the status.
                              </p>
                            )}
                            {state === 'active' && canAct && (
                              <div className="mt-4 bg-white border border-blue-100 rounded-xl p-4 shadow-sm animate-fade-in">
                                {stop.type === 'PICKUP' && (
                                  <>
                                    {activeSubStep === 'arrive' && (
                                      <div className="space-y-3">
                                        <p className="text-xs text-gray-500 font-medium">Head to the pickup location and confirm arrival.</p>
                                        <div className="space-y-2">
                                          <button onClick={() => handleArrivedClick(booking)} className="w-full bg-blue-600 text-white py-2.5 rounded-xl text-sm font-bold hover:bg-blue-700 shadow-sm">
                                            Arrived at pickup ✓
                                          </button>
                                        </div>
                                      </div>
                                    )}

                                    {activeSubStep === 'pack' && (
                                      <div className="space-y-4">
                                        <h4 className="text-sm font-bold text-blue-900">Packing Service Required</h4>
                                        <p className="text-xs text-blue-800">Requested Time: {booking.packingTimeHours} hr</p>
                                        <div className="space-y-3 pt-3 border-t border-blue-100">
                                          <label className="flex items-center justify-between text-xs font-semibold text-gray-700">
                                            <span>Did packing take more time than expected?</span>
                                            <input type="checkbox" checked={extraPackingNeeded[booking.id] === true} onChange={(e) => setExtraPackingNeededMap({...extraPackingNeeded, [booking.id]: e.target.checked})} className="w-4 h-4 text-blue-600 rounded border-gray-300" />
                                          </label>
                                          {extraPackingNeeded[booking.id] && (
                                            <div className="pl-4 mt-2 border-l-2 border-blue-200 space-y-3">
                                              <div>
                                                <label className="block text-[11px] font-bold text-gray-600 mb-1">Extra Time (Hours)</label>
                                                <div className="flex items-center gap-3 bg-gray-50 border border-gray-200 rounded-lg p-1 max-w-[150px]">
                                                  <button onClick={() => setExtraPackingHoursMap({...extraPackingHours, [booking.id]: Math.max(0, (extraPackingHours[booking.id] || 0) - 0.5)})} className="w-8 h-8 font-bold">−</button>
                                                  <span className="flex-1 text-center font-bold text-sm">{extraPackingHours[booking.id] || 0}</span>
                                                  <button onClick={() => setExtraPackingHoursMap({...extraPackingHours, [booking.id]: (extraPackingHours[booking.id] || 0) + 0.5})} className="w-8 h-8 font-bold">+</button>
                                                </div>
                                              </div>
                                              <div>
                                                <label className="block text-[11px] font-bold text-gray-600 mb-1">Extra Materials Cost (£)</label>
                                                <input type="number" value={extraPackingMaterialsCost[booking.id] || ''} onChange={(e) => setExtraPackingMaterialsCostMap({...extraPackingMaterialsCost, [booking.id]: Number(e.target.value)})} className="w-full text-sm border-gray-300 rounded-lg p-2 max-w-[150px]" placeholder="0.00" />
                                              </div>
                                            </div>
                                          )}
                                        </div>
                                        <div className="space-y-2">
                                          <button onClick={() => handlePackCompleteClick(booking)} className="w-full bg-blue-600 text-white py-3 rounded-xl text-sm font-bold hover:bg-blue-700 shadow-sm">
                                            Packing Completed ✓
                                          </button>
                                          <button onClick={() => undoStatus(booking.id)} disabled={updatingId === booking.id} className="w-full bg-gray-100 text-gray-600 py-2 rounded-xl text-xs font-bold hover:bg-gray-200 disabled:opacity-40">
                                            {/* X1 fix: /undo endpoint — ARRIVED→SCHEDULED */}
                                            Go Back (Undo Arrival)
                                          </button>
                                        </div>
                                      </div>
                                    )}

                                    {activeSubStep === 'load' && (
                                      <div className="space-y-4">
                                        <div className="bg-gray-50 p-3 rounded-lg border border-gray-200 text-sm">
                                          <p className="font-bold text-gray-900 mb-1">Inventory ({booking.items?.length ?? 0} items)</p>
                                          <p className="text-xs text-gray-500">{booking.items?.map((i:any) => i.name).join(', ')}</p>
                                        </div>
                                        {extraItemsData[booking.id] && (
                                          <div className="bg-green-50 border border-green-100 p-2 rounded-lg text-xs font-bold text-green-800 flex gap-2">
                                            <span>📦</span> Extra items added (£{extraItemsData[booking.id].price})
                                          </div>
                                        )}

                                        {!isBatched && booking.type !== 'FULL_HOUSE' && (
                                          <div className="bg-stone-50 border border-stone-200 rounded-xl p-3 text-xs text-stone-700 mb-2">
                                            <strong>LIFO Warning:</strong> Load heavy items first.
                                          </div>
                                        )}

                                        <div>
                                          <p className="text-xs font-bold text-gray-900 mb-2">Proof of Load Structure (Required)</p>
                                          {truckPhotos[booking.id] ? (
                                            <div className="relative rounded-xl overflow-hidden border border-gray-200 h-28 group">
                                              <img key={truckPhotos[booking.id]} src={getImageUrl(truckPhotos[booking.id])} alt="Loaded truck" className="w-full h-full object-cover" referrerPolicy="no-referrer" />
                                              <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white text-sm font-bold cursor-pointer">
                                                Retake<input type="file" accept="image/*" className="sr-only" onChange={e => handlePhotoUpload(e, url => setTruckPhotos(p => ({ ...p, [booking.id]: url })))} />
                                              </label>
                                            </div>
                                          ) : (
                                            <label className="border-2 border-dashed border-gray-300 bg-stone-50 rounded-xl h-28 flex flex-col items-center justify-center cursor-pointer hover:border-blue-300 transition-colors">
                                              <span className="text-xl mb-1">📷</span>
                                              <span className="text-xs font-bold text-gray-700">Upload Photo</span>
                                              <input type="file" accept="image/*" className="sr-only" onChange={e => handlePhotoUpload(e, url => setTruckPhotos(p => ({ ...p, [booking.id]: url })))} />
                                            </label>
                                          )}
                                        </div>

                                        <div className="space-y-2">
                                          <button
                                            onClick={() => submitLoaded(booking)}
                                            disabled={updatingId === booking.id || !truckPhotos[booking.id] || truckPhotos[booking.id].startsWith('blob:') || uploadingPhoto}
                                            className="w-full bg-blue-600 text-white py-3 rounded-xl text-sm font-bold hover:bg-blue-700 shadow-sm disabled:opacity-40"
                                          >
                                            {uploadingPhoto ? 'Uploading photo…' : updatingId === booking.id ? 'Updating…' : 'Items loaded ✓'}
                                          </button>
                                          <button
                                            onClick={() => undoStatus(booking.id)}
                                            disabled={updatingId === booking.id}
                                            className="w-full bg-gray-100 text-gray-600 py-2 rounded-xl text-xs font-bold hover:bg-gray-200 disabled:opacity-40"
                                          >
                                            {/* X1 fix: /undo — PACKED→ARRIVED or ARRIVED→SCHEDULED */}
                                            Go Back
                                          </button>
                                        </div>
                                      </div>
                                    )}
                                  </>
                                )}

                                {stop.type === 'DROPOFF' && (
                                  <div className="space-y-4">
                                    <div className="bg-gray-50 border border-gray-200 rounded-xl p-4">
                                      <p className="text-xs font-bold text-gray-900 mb-2">Delivery Photo (Proof)</p>
                                      {deliveryPhotos[booking.id] ? (
                                        <div className="relative rounded-xl overflow-hidden border border-gray-200 h-28 group">
                                          <img key={deliveryPhotos[booking.id]} src={getImageUrl(deliveryPhotos[booking.id])} alt="Delivery proof" className="w-full h-full object-cover" referrerPolicy="no-referrer" />
                                          <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white text-sm font-bold cursor-pointer transition-opacity backdrop-blur-sm">
                                             Retake<input type="file" accept="image/*" className="sr-only" onChange={e => handlePhotoUpload(e, url => setDeliveryPhotos(p => ({ ...p, [booking.id]: url })))} />
                                          </label>
                                        </div>
                                      ) : (
                                        <label className="border-2 border-dashed border-gray-300 bg-white rounded-xl h-28 flex flex-col items-center justify-center cursor-pointer hover:border-blue-300 transition-colors">
                                          <span className="text-xl mb-1">📷</span>
                                          <span className="text-xs font-bold text-gray-700">Upload Photo</span>
                                           <input type="file" accept="image/*" className="sr-only" onChange={e => handlePhotoUpload(e, url => setDeliveryPhotos(p => ({ ...p, [booking.id]: url })))} />
                                        </label>
                                      )}
                                    </div>
                                    <a
                                      href={`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(booking.destinationAddress)}&travelmode=driving`}
                                      target="_blank"
                                      rel="noopener noreferrer"
                                      className="inline-flex items-center gap-1.5 text-xs font-bold text-white bg-indigo-600 hover:bg-indigo-700 px-4 py-2.5 rounded-xl shadow-sm"
                                    >
                                      Navigate to destination ↗
                                    </a>

                                    {booking.status === 'LOADED' ? (
                                      <div className="space-y-2 mt-2">
                                        <button
                                          onClick={() => updateStatus(booking.id, 'IN_TRANSIT')}
                                          disabled={updatingId === booking.id}
                                          className="w-full bg-emerald-600 text-white py-3 rounded-xl text-sm font-bold hover:bg-emerald-700 shadow-sm"
                                        >
                                          {updatingId === booking.id ? 'Updating…' : 'Start Drive to Dropoff ➔'}
                                        </button>
                                      </div>
                                    ) : booking.status === 'IN_TRANSIT' ? (
                                      <div className="space-y-2 mt-2">
                                        <button
                                          onClick={() => updateStatus(booking.id, 'UNLOADING')}
                                          disabled={updatingId === booking.id}
                                          className="w-full bg-emerald-600 text-white py-3 rounded-xl text-sm font-bold hover:bg-emerald-700 shadow-sm"
                                        >
                                          {updatingId === booking.id ? 'Updating…' : 'I arrived (Start Unloading) ✓'}
                                        </button>
                                        <button
                                          onClick={() => undoStatus(booking.id)}
                                          disabled={updatingId === booking.id}
                                          className="w-full bg-gray-100 text-gray-600 py-2 rounded-xl text-xs font-bold hover:bg-gray-200 disabled:opacity-40"
                                        >
                                          Undo Start Drive
                                        </button>
                                      </div>
                                    ) : (
                                      <div className="space-y-2 mt-2">
                                        <button
                                          onClick={() => handleConfirmDeliveryClick(booking)}
                                          disabled={updatingId === booking.id}
                                          className="w-full bg-blue-600 text-white py-3 rounded-xl text-sm font-bold hover:bg-blue-700 disabled:opacity-40 shadow-sm flex justify-center items-center gap-2"
                                        >
                                          {booking.withStorage ? 'Get Warehouse/Customer Signature' : 'Get Customer Signature'}
                                        </button>
                                        <button
                                          onClick={() => undoStatus(booking.id)}
                                          disabled={updatingId === booking.id}
                                          className="w-full bg-gray-100 text-gray-600 py-2 rounded-xl text-xs font-bold hover:bg-gray-200 disabled:opacity-40"
                                        >
                                          Undo Arrived at Destination
                                        </button>
                                      </div>
                                    )}
                                  </div>
                                )}
                              </div>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>

                  {/* Unreachable action for active route — lead driver only */}
                  {isActive && (() => {
                    const activeBooking = route.stops.find(s => s.status === 'active')?.booking || route.bookings[0];
                    return !myDriverId || activeBooking.driverId === myDriverId;
                  })() && (
                    <div className="mt-4 pt-4 border-t border-gray-200">
                      <button
                        onClick={() => {
                          const activeBooking = route.stops.find(s => s.status === 'active')?.booking || route.bookings[0];
                          updateStatus(activeBooking.id, 'UNREACHABLE');
                        }}
                        className="w-full border border-red-200 text-red-600 bg-red-50 py-3 rounded-xl text-sm font-bold hover:bg-red-100 transition-colors"
                      >
                        Can&apos;t reach customer at current stop
                      </button>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Extra Items Modal */}
      {extraPromptOpen && activeExtraBooking && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-3xl border border-gray-200 shadow-2xl max-w-md w-full p-6 sm:p-8 overflow-y-auto max-h-[90vh]">
            <h2 className="text-xl font-bold text-gray-900 mb-2">Customer Check</h2>

            {!showExtraForm ? (
              <>
                <p className="text-sm text-gray-500 mb-6 leading-relaxed">
                  You arrived at the pickup location. Does the customer want to add any <strong className="text-gray-900">extra items</strong> that are not on the original booking list?
                </p>
                <div className="space-y-3">
                  <button
                    onClick={() => setShowExtraForm(true)}
                    className="w-full bg-blue-600 text-white py-3.5 rounded-xl text-sm font-bold hover:bg-blue-700 transition-all shadow-sm flex items-center justify-center gap-2"
                  >
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M12 4v16m8-8H4" /></svg>
                    Yes, add extra items
                  </button>
                  <button
                    onClick={() => setExtraPromptOpen(false)}
                    className="w-full bg-stone-100 text-gray-700 py-3.5 rounded-xl text-sm font-bold hover:bg-stone-200 transition-all"
                  >
                    No, original items only
                  </button>
                </div>
              </>
            ) : (
              <div className="space-y-6 animate-fade-in">
                <p className="text-sm text-gray-500">Record the extra item and agree on the price with the customer.</p>

                {/* Photo Capture */}
                <div>
                  <p className="text-[13px] font-bold text-gray-900 mb-2">1. Take a photo of the item(s)</p>
                  {extraItemPhoto ? (
                    <div className="relative rounded-xl overflow-hidden border border-gray-200 w-full h-32 group">
                      <img key={extraItemPhoto} src={getImageUrl(extraItemPhoto)} alt="Extra item" className="w-full h-full object-cover" referrerPolicy="no-referrer" />
                      <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white text-sm font-bold cursor-pointer transition-opacity backdrop-blur-sm">
                        Retake Photo
                        <input type="file" accept="image/*" className="sr-only" onChange={e => handlePhotoUpload(e, setExtraItemPhoto)} />
                      </label>
                    </div>
                  ) : (
                    <label className="border-2 border-dashed border-gray-300 bg-stone-50 rounded-xl p-6 flex flex-col items-center justify-center text-center cursor-pointer hover:bg-stone-100 hover:border-blue-300 transition-colors">
                      <svg className="w-6 h-6 text-blue-500 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                      <span className="text-sm font-bold text-gray-700">Open Camera / Gallery</span>
                      <input type="file" accept="image/*" className="sr-only" onChange={e => handlePhotoUpload(e, setExtraItemPhoto)} />
                    </label>
                  )}
                </div>

                {/* Price */}
                <div>
                  <p className="text-[13px] font-bold text-gray-900 mb-2">2. Extra Price (£)</p>
                  <div className="relative">
                    <span className="absolute left-4 top-1/2 -translate-y-1/2 font-bold text-gray-400">£</span>
                    <input 
                      type="number" 
                      min="0"
                      value={extraItemPrice}
                      onChange={(e) => setExtraItemPrice(e.target.value ? Number(e.target.value) : '')}
                      placeholder="0"
                      className="w-full bg-gray-50 border border-gray-200 rounded-xl pl-9 pr-4 py-3 text-sm font-bold text-gray-900 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all"
                    />
                  </div>
                </div>

                {/* Payment Method */}
                <div>
                  <p className="text-[13px] font-bold text-gray-900 mb-2">3. Payment Method</p>
                  <div className="flex gap-3">
                    <button
                      onClick={() => setExtraPaymentMethod('cash')}
                      className={`flex-1 py-3 rounded-xl border font-bold text-sm transition-all flex flex-col items-center gap-1 ${
                        extraPaymentMethod === 'cash' 
                          ? 'bg-blue-50 border-blue-500 text-blue-700' 
                          : 'bg-white border-gray-200 text-gray-600 hover:bg-stone-50'
                      }`}
                    >
                      <span className="text-xl">💵</span> Cash
                    </button>
                    <button
                      onClick={() => setExtraPaymentMethod('card')}
                      className={`flex-1 py-3 rounded-xl border font-bold text-sm transition-all flex flex-col items-center gap-1 ${
                        extraPaymentMethod === 'card' 
                          ? 'bg-blue-50 border-blue-500 text-blue-700' 
                          : 'bg-white border-gray-200 text-gray-600 hover:bg-stone-50'
                      }`}
                    >
                      <span className="text-xl">💳</span> Card
                    </button>
                    <button 
                      onClick={() => setExtraPaymentMethod('debt')}
                      className={`flex-1 py-3 rounded-xl border font-bold text-sm transition-all flex flex-col items-center gap-1 ${
                        extraPaymentMethod === 'debt' 
                          ? 'bg-red-500 border-red-500 text-white' 
                          : 'bg-white border-gray-200 text-gray-600 hover:bg-stone-50'
                      }`}
                    >
                      <span className="text-xl">🧾</span> Add to Debt
                    </button>
                  </div>
                </div>

                {/* Actions */}
                <div className="pt-4 flex gap-3">
                  <button
                    onClick={() => { setShowExtraForm(false); setExtraPromptOpen(false); }}
                    className="flex-1 py-3.5 rounded-xl border border-gray-200 text-gray-600 font-bold text-sm hover:bg-stone-50 transition-all"
                  >
                    Cancel
                  </button>
                  <button
                    disabled={!extraItemPhoto || extraItemPrice === '' || !extraPaymentMethod}
                    onClick={saveExtraItem}
                    className="flex-1 py-3.5 rounded-xl bg-blue-600 text-white font-bold text-sm hover:bg-blue-700 transition-all disabled:opacity-50"
                  >
                    Save & Continue
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
      {/* Completion Modal */}
      {completionModalOpen && completingBooking && (
        <div className={`fixed inset-0 z-[60] flex items-center justify-center bg-gray-900/60 backdrop-blur-sm animate-fade-in ${signatureMode ? 'p-0' : 'p-4'}`}>
          {signatureMode ? (
            <div className="w-full h-full bg-white flex flex-col animate-slide-up">
              <SignatureCanvas 
                onSave={finalComplete} 
                onCancel={() => setSignatureMode(false)} 
              />
            </div>
          ) : (
            <div className="bg-white rounded-3xl border border-gray-200 shadow-2xl max-w-md w-full p-6 sm:p-8 overflow-y-auto max-h-[90vh]">
              <h2 className="text-xl font-bold text-gray-900 mb-2">Delivery Completed?</h2>
              <p className="text-sm text-gray-500 mb-6 leading-relaxed">
                You are about to mark this order as DELIVERED. Did the customer require extra time beyond the estimated duration?
              </p>

              <div className="space-y-4 mb-6">
                <label className="flex items-center justify-between p-4 border border-gray-200 rounded-2xl cursor-pointer hover:bg-stone-50 transition-colors">
                  <div className="flex items-center gap-3">
                    <div className={`w-5 h-5 rounded-full border-[1.5px] flex items-center justify-center transition-colors ${extraTimeNeeded === false ? 'border-blue-500 bg-white' : 'border-gray-300'}`}>
                      {extraTimeNeeded === false && <div className="w-3 h-3 bg-blue-500 rounded-full" />}
                    </div>
                    <span className="text-[15px] font-bold text-gray-900">No, completed on time</span>
                  </div>
                  <input type="radio" name="extraTime" className="sr-only" checked={extraTimeNeeded === false} onChange={() => setExtraTimeNeeded(false)} />
                </label>

                <label className="flex items-center justify-between p-4 border border-gray-200 rounded-2xl cursor-pointer hover:bg-stone-50 transition-colors">
                  <div className="flex items-center gap-3">
                    <div className={`w-5 h-5 rounded-full border-[1.5px] flex items-center justify-center transition-colors ${extraTimeNeeded === true ? 'border-blue-500 bg-white' : 'border-gray-300'}`}>
                      {extraTimeNeeded === true && <div className="w-3 h-3 bg-blue-500 rounded-full" />}
                    </div>
                    <span className="text-[15px] font-bold text-gray-900">Yes, extra time needed</span>
                  </div>
                  <input type="radio" name="extraTime" className="sr-only" checked={extraTimeNeeded === true} onChange={() => setExtraTimeNeeded(true)} />
                </label>
              </div>

              {extraTimeNeeded && (
                <div className="mb-6 animate-fade-in bg-blue-50/50 border border-blue-100 rounded-2xl p-5">
