                <button
                  disabled={!pricesReady || extraTimeNeeded === null || (extraTimeNeeded && !extraTimePayment)}
                  onClick={submitCompletion}
                  className="flex-1 py-3.5 rounded-xl bg-blue-600 text-white font-bold text-sm hover:bg-blue-700 transition-all disabled:opacity-50"
                >
                  Get Signature
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      {/* LIFO Modal */}
      {lifoBooking && (
        <LifoModal 
          isOpen={!!lifoBooking} 
          onClose={() => setLifoBooking(null)} 
          orders={Array.isArray(lifoBooking) ? lifoBooking : [lifoBooking]} 
        />
      )}
    </div>
  );
}

// ── Signature Canvas Component ─────────────────────────────
function SignatureCanvas({ onSave, onCancel }: { onSave: (dataUrl: string) => void, onCancel: () => void }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [hasSigned, setHasSigned] = useState(false);
  const lastCoords = useRef<{x: number, y: number} | null>(null);
  const strokeLength = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resize = () => {
      // D8 fix: preserve signature content during resize
      const tempCanvas = document.createElement('canvas');
      const tempCtx = tempCanvas.getContext('2d');
      if (tempCtx && canvas.width > 0 && canvas.height > 0) {
        tempCanvas.width = canvas.width;
        tempCanvas.height = canvas.height;
        tempCtx.drawImage(canvas, 0, 0);
      }

      canvas.width = canvas.parentElement?.clientWidth || window.innerWidth;
      canvas.height = (canvas.parentElement?.clientHeight || window.innerHeight);
      ctx.lineWidth = 3;
      ctx.lineCap = 'round';
      ctx.strokeStyle = '#000';

      if (tempCtx && tempCanvas.width > 0 && tempCanvas.height > 0) {
        ctx.drawImage(tempCanvas, 0, 0);
      }
    };
    resize();
    window.addEventListener('resize', resize);
    return () => window.removeEventListener('resize', resize);
  }, []);

  const getCoordinates = (e: React.MouseEvent | React.TouchEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return null;
    const rect = canvas.getBoundingClientRect();
    if ('touches' in e) {
      return { x: e.touches[0].clientX - rect.left, y: e.touches[0].clientY - rect.top };
    }
    return { x: (e as React.MouseEvent).clientX - rect.left, y: (e as React.MouseEvent).clientY - rect.top };
  };

  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    const coords = getCoordinates(e);
    if (!coords) return;
    const ctx = canvasRef.current?.getContext('2d');
    if (ctx) {
      ctx.beginPath();
      ctx.moveTo(coords.x, coords.y);
      setIsDrawing(true);
      lastCoords.current = coords;
    }
  };

  const draw = (e: React.MouseEvent | React.TouchEvent) => {
    e.preventDefault();
    if (!isDrawing) return;
    const coords = getCoordinates(e);
    if (!coords) return;
    const ctx = canvasRef.current?.getContext('2d');
    if (ctx) {
      ctx.lineTo(coords.x, coords.y);
      ctx.stroke();

      if (lastCoords.current) {
        const dx = coords.x - lastCoords.current.x;
        const dy = coords.y - lastCoords.current.y;
        strokeLength.current += Math.sqrt(dx * dx + dy * dy);

        // Require at least 20px of stroke to count as a signature
        if (strokeLength.current > 20) {
          setHasSigned(true);
        }
      }
      lastCoords.current = coords;
    }
  };

  const stopDrawing = () => {
    if (isDrawing) {
      canvasRef.current?.getContext('2d')?.closePath();
      setIsDrawing(false);
    }
  };

  const clear = () => {
    const canvas = canvasRef.current;
    if (canvas) {
      const ctx = canvas.getContext('2d');
      ctx?.clearRect(0, 0, canvas.width, canvas.height);
      setHasSigned(false);
      strokeLength.current = 0;
      lastCoords.current = null;
    }
  };

  return (
    <div className="flex flex-col h-full bg-white">
      <div className="p-5 bg-gray-50 border-b border-gray-200 flex justify-between items-center safe-area-top">
        <h3 className="font-bold text-gray-900 text-lg">Customer Signature</h3>
        <button onClick={clear} className="text-sm font-bold text-gray-500 hover:text-gray-700 bg-white px-3 py-1.5 rounded-lg border border-gray-200 shadow-sm">Clear</button>
      </div>
      <div className="flex-1 bg-white relative overflow-hidden" style={{ touchAction: 'none' }}>
        <canvas
          ref={canvasRef}
          onMouseDown={startDrawing}
          onMouseMove={draw}
          onMouseUp={stopDrawing}
          onMouseLeave={stopDrawing}
          onTouchStart={startDrawing}
          onTouchMove={draw}
          onTouchEnd={stopDrawing}
          className="cursor-crosshair w-full h-full"
        />
        <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
          <span className="text-gray-200 text-5xl font-extrabold uppercase tracking-widest opacity-30 -rotate-12">Sign Here</span>
        </div>
      </div>
      <div className="p-5 border-t border-gray-200 flex gap-3 bg-gray-50 safe-area-bottom">
        <button onClick={onCancel} className="flex-1 py-4 rounded-xl border border-gray-300 font-bold text-gray-700 bg-white shadow-sm hover:bg-gray-50">Cancel</button>
        <button 
          onClick={() => hasSigned && onSave(canvasRef.current?.toDataURL() || '')} 
          disabled={!hasSigned}
          className="flex-1 py-4 rounded-xl bg-blue-600 font-bold text-white shadow-md disabled:opacity-50 disabled:cursor-not-allowed hover:bg-blue-700"
        >
          Complete Order
        </button>
      </div>
    </div>
  );
}

'use client';
import { getAccessToken } from '@/lib/auth-token';

import { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';

const API = process.env.API_URL;

type PageView = 'loading' | 'form' | 'pending' | 'approved' | 'rejected';

export default function ManagerApplyPage() {
  const router = useRouter();
  const [view, setView] = useState<PageView>('loading');
  const [submitting, setSubmitting] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [adminNotes, setAdminNotes] = useState<string | null>(null);

  // Form fields (for non-logged-in users who register + apply in one go)
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [experience, setExperience] = useState('');
  const [phone, setPhone] = useState('');

  // Polling ref
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    checkState();
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, []);

  const checkState = async () => {
    const token = getAccessToken();
    if (!token) {
      setIsLoggedIn(false);
      setView('form');
      return;
    }
    setIsLoggedIn(true);
    try {
      const res = await fetch(`${API}/manager/application-status`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const data = await res.json();
        if (data) {
          if (data.status === 'APPROVED') {
            setView('approved');
            return;
          }
          if (data.status === 'REJECTED') {
            setAdminNotes(data.adminNotes || null);
            setView('rejected');
            return;
          }
          // PENDING — show waiting screen and start polling
          setView('pending');
          startPolling();
          return;
        }
      }
      setView('form');
    } catch {
      setView('form');
    }
  };

  const startPolling = () => {
    if (pollRef.current) clearInterval(pollRef.current);
    pollRef.current = setInterval(async () => {
      const token = getAccessToken();
      if (!token) return;
      try {
        const res = await fetch(`${API}/manager/application-status`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (res.ok) {
          const data = await res.json();
          if (data?.status === 'APPROVED') {
            if (pollRef.current) clearInterval(pollRef.current);
            setView('approved');
          } else if (data?.status === 'REJECTED') {
            if (pollRef.current) clearInterval(pollRef.current);
            setAdminNotes(data.adminNotes || null);
            setView('rejected');
          }
        }
      } catch { /* silent */ }
    }, 8000); // poll every 8 seconds
  };

  const handleApply = async (e: React.FormEvent) => {
    e.preventDefault();
    let token = getAccessToken();

    setSubmitting(true);
    setErrorMsg('');
    try {
      if (!isLoggedIn) {
        // 1. Register the user
        const regRes = await fetch(`${API}/auth/register`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name, email, password, phone }),
        });
        if (!regRes.ok) {
          const data = await regRes.json();
          throw new Error(data.message || 'Registration failed');
        }

        // 2. Log them in to get token
        const loginRes = await fetch(`${API}/auth/login`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ email, password }),
        });
        if (!loginRes.ok) {
          const data = await loginRes.json();
          throw new Error(data.message || 'Login failed after registration');
        }
        const loginData = await loginRes.json();
        token = loginData.accessToken;
        localStorage.setItem('accessToken', token as string);
        if (loginData.user) {
          localStorage.setItem('user', JSON.stringify(loginData.user));
        }
        setIsLoggedIn(true);
      }

      // 3. Apply as manager
      const res = await fetch(`${API}/manager/apply`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ experience, phone }),
      });
      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.message || 'Application failed');
      }
      setView('pending');
      startPolling();
    } catch (err: any) {
      setErrorMsg(err.message);
    } finally {
      setSubmitting(false);
    }
  };

  /* ═══════════════ LOADING ═══════════════ */
  if (view === 'loading') {
    return (
      <div className="min-h-[80vh] flex items-center justify-center bg-white">
        <div className="flex flex-col items-center gap-4">
          <div className="w-10 h-10 border-4 border-gray-200 border-t-blue-600 rounded-full animate-spin" />
          <p className="text-[15px] text-gray-500 font-medium">Checking application status…</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 md:p-8 lg:p-12 max-w-[1400px] mx-auto">
    <div className="min-h-[80vh] flex items-center justify-center px-4 py-16 bg-white">
      <div className="w-full max-w-xl">

        {/* ═══════════════ PENDING — the user stays here ═══════════════ */}
        {view === 'pending' && (
          <div className="bg-white rounded-3xl border border-gray-100 shadow-xl overflow-hidden animate-fade-in">
            {/* Header accent */}
            <div className="bg-[#EBE7DF]/60 px-8 pt-10 pb-8 text-center border-b border-gray-100">
              <div className="w-20 h-20 bg-white rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-sm border border-gray-100">
                <svg className="w-10 h-10 text-amber-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <h1 className="text-3xl font-bold text-gray-900 tracking-tight mb-3">Application Under Review</h1>
              <p className="text-[15px] text-gray-500 font-medium max-w-sm mx-auto leading-relaxed">
                Your manager application has been submitted successfully. Our team is reviewing it now.
              </p>
            </div>

            <div className="px-8 py-8 space-y-6">
              {/* Status badge */}
              <div className="flex items-center justify-center">
                <div className="inline-flex items-center gap-3 bg-amber-50 border border-amber-200 px-6 py-3 rounded-2xl">
                  <span className="relative flex h-3 w-3">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-amber-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-3 w-3 bg-amber-500"></span>
                  </span>
                  <span className="text-[15px] font-bold text-amber-700 uppercase tracking-wide">Pending Review</span>
                </div>
              </div>

              {/* Info items */}
              <div className="bg-stone-50 rounded-2xl p-6 space-y-4 border border-gray-100">
                <div className="flex items-start gap-4">
                  <div className="w-10 h-10 bg-blue-50 rounded-xl flex items-center justify-center shrink-0 border border-blue-100">
                    <svg className="w-5 h-5 text-blue-600" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                  </div>
                  <div>
                    <p className="text-[15px] font-bold text-gray-900 mb-0.5">Application received</p>
                    <p className="text-sm text-gray-500 font-medium">Your details have been securely submitted.</p>
                  </div>
                </div>
                <div className="flex items-start gap-4">
                  <div className="w-10 h-10 bg-amber-50 rounded-xl flex items-center justify-center shrink-0 border border-amber-100">
                    <svg className="w-5 h-5 text-amber-600" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
