                  </div>
                </div>
              </div>

              <p className="text-center text-xs text-gray-400 font-medium">
                This page checks for updates automatically — no need to refresh.
              </p>

              <button
                onClick={() => router.push('/')}
                className="w-full border border-gray-200 text-gray-600 py-3.5 rounded-2xl text-[15px] font-bold hover:bg-stone-50 transition-colors"
              >
                Back to Home
              </button>
            </div>
          </div>
        )}

        {/* ═══════════════ APPROVED ═══════════════ */}
        {view === 'approved' && (
