                      className="w-full border-2 border-gray-200 rounded-2xl px-4 py-3.5 text-[15px] font-medium text-gray-900 focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all placeholder:text-gray-400"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Email address <span className="text-red-400">*</span></label>
                    <input
                      required
                      type="email"
                      value={email}
                      onChange={e => setEmail(e.target.value)}
                      placeholder="john@example.com"
                      className="w-full border-2 border-gray-200 rounded-2xl px-4 py-3.5 text-[15px] font-medium text-gray-900 focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all placeholder:text-gray-400"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Password <span className="text-red-400">*</span></label>
                    <input
                      required
                      type="password"
                      value={password}
                      onChange={e => setPassword(e.target.value)}
                      placeholder="••••••••"
                      className="w-full border-2 border-gray-200 rounded-2xl px-4 py-3.5 text-[15px] font-medium text-gray-900 focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all placeholder:text-gray-400"
                    />
                  </div>
                </>
              )}

              <div>
                <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Phone number {!isLoggedIn && <span className="text-red-400">*</span>}</label>
                <input
                  type="tel"
                  required={!isLoggedIn}
                  value={phone}
                  onChange={e => setPhone(e.target.value)}
                  placeholder="+44 7700 900000"
                  className="w-full border-2 border-gray-200 rounded-2xl px-4 py-3.5 text-[15px] font-medium text-gray-900 focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all placeholder:text-gray-400"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Experience</label>
                <textarea
                  value={experience}
                  onChange={e => setExperience(e.target.value)}
                  rows={4}
                  placeholder="Describe your relevant management or logistics experience…"
                  className="w-full border-2 border-gray-200 rounded-2xl px-4 py-3.5 text-[15px] font-medium text-gray-900 resize-none focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all placeholder:text-gray-400"
                />
              </div>

              {errorMsg && (
                <div className="bg-red-50 border border-red-200 rounded-2xl p-4 text-center">
                  <p className="text-[15px] text-red-600 font-medium">{errorMsg}</p>
                </div>
              )}

              <button
                type="submit"
                disabled={submitting}
                className="w-full bg-blue-600 text-white py-3.5 rounded-2xl text-[15px] font-bold hover:bg-blue-700 hover:shadow-lg transition-all disabled:opacity-50"
              >
                {submitting ? 'Submitting…' : 'Submit Application'}
              </button>

              <p className="text-xs text-gray-400 text-center font-medium">
                Our team reviews applications within 1–3 business days.
              </p>
            </form>
          </div>
        )}

      </div>
    </div>
    </div>
  );
}

'use client';
import { getAccessToken } from '@/lib/auth-token';

import { useEffect, useState } from 'react';
import { cachedJson, invalidateCache } from '@/lib/client-cache';
import { getImageUrl } from '@/lib/image-url';

const API = process.env.API_URL || 'https://api.nglob.com/api';
// Handle both /api and /api/ endings safely
const BASE_URL = API.replace(/\/api\/?$/, '');
const authHeaders = () => ({
  Authorization: `Bearer ${getAccessToken()}`,
  'Content-Type': 'application/json',
});

// Parse JSON-stringified arrays stored by the driver upload flow
const parseJsonField = (val: string | null | undefined): string[] => {
  if (!val) return [];
  try {
    const parsed = JSON.parse(val);
    if (Array.isArray(parsed)) return parsed.filter(Boolean);
    if (typeof parsed === 'string') return [parsed];
  } catch { /* not JSON, treat as plain string */ }
  // Strip any accidental leading/trailing quotes if it fell through
  const cleanVal = val.replace(/^["']|["']$/g, '');
  return [cleanVal];
};

const getFileUrl = (path: string | null | undefined) => {
  if (!path) return null;
  const urls = parseJsonField(path);
  if (urls.length > 0) {
    return getImageUrl(urls[0]);
  }
  return getImageUrl(path);
};

const getFileUrls = (path: string | null | undefined): string[] => {
  const urls = parseJsonField(path);
  return urls.map(u => getImageUrl(u));
};

const getFileNames = (val: string | null | undefined): string[] => {
  return parseJsonField(val);
};

interface DriverDoc {
  id: string;
  docType: string;
  label: string;
  fileName: string | null;
  fileUrl?: string | null;
  status: 'NOT_PROVIDED' | 'UPLOADED' | 'APPROVED' | 'REJECTED';
  reviewNote: string | null;
  uploadedAt: string | null;
  reviewedAt: string | null;
}

interface DriverWithDocs {
  id: string;
  status: string;
  licensingAuthority: string | null;
  hasVan: boolean;
  createdAt: string;
  user: { name: string; email: string; phone: string | null };
  documents: DriverDoc[];
}

export default function DriverDocumentsPage() {
  const [drivers, setDrivers] = useState<DriverWithDocs[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedDriver, setSelectedDriver] = useState<DriverWithDocs | null>(null);
  const [reviewingDocId, setReviewingDocId] = useState<string | null>(null);
  const [rejectNote, setRejectNote] = useState('');
  const [showRejectModal, setShowRejectModal] = useState<string | null>(null);
  const [filter, setFilter] = useState<'all' | 'pending' | 'approved' | 'rejected'>('all');
  const [previewDocUrl, setPreviewDocUrl] = useState<string | null>(null);
  const [previewDocName, setPreviewDocName] = useState<string | null>(null);

  useEffect(() => { fetchDrivers(); }, []);

  const fetchDrivers = async () => {
    try {
      const data = await cachedJson<DriverWithDocs[]>(
        `${API}/manager/drivers-with-documents`,
        { headers: authHeaders() },
        { ttl: 30_000 },
      );
      setDrivers(data || []);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  const reviewDocument = async (docId: string, status: 'APPROVED' | 'REJECTED', note?: string) => {
    setReviewingDocId(docId);
    try {
      const res = await fetch(`${API}/manager/documents/${docId}/review`, {
        method: 'PATCH', headers: authHeaders(),
        body: JSON.stringify({ status, reviewNote: note || undefined }),
      });
      if (!res.ok) throw new Error('Review failed');
      invalidateCache('/manager/drivers');
      if (selectedDriver) {
        const updated = await cachedJson<DriverWithDocs>(
          `${API}/manager/drivers/${selectedDriver.id}/documents`,
          { headers: authHeaders() },
          { ttl: 30_000 },
        );
        setSelectedDriver(updated);
        setDrivers(prev => prev.map(d => d.id === updated.id ? updated : d));
      }
    } catch (err) { console.error(err); }
    finally { setReviewingDocId(null); setShowRejectModal(null); setRejectNote(''); }
  };

  const updateDriverStatus = async (driverId: string, status: string) => {
    try {
      await fetch(`${API}/manager/drivers/${driverId}/status`, {
        method: 'PATCH', headers: authHeaders(),
        body: JSON.stringify({ status }),
      });
      invalidateCache('/manager/drivers');
      await fetchDrivers();
      if (selectedDriver?.id === driverId) {
        const updated = await cachedJson<DriverWithDocs>(
          `${API}/manager/drivers/${driverId}/documents`,
          { headers: authHeaders() },
          { ttl: 30_000 },
        );
        setSelectedDriver(updated);
      }
    } catch (err) { console.error(err); }
  };

  const filteredDrivers = drivers.filter(d => {
    if (filter === 'pending') return d.status === 'PENDING';
    if (filter === 'approved') return d.status === 'APPROVED';
    if (filter === 'rejected') return d.status === 'REJECTED';
    return true;
  });

  const getDocStats = (docs: DriverDoc[]) => {
    const uploaded = docs.filter(d => d.status !== 'NOT_PROVIDED').length;
    const approved = docs.filter(d => d.status === 'APPROVED').length;
    const rejected = docs.filter(d => d.status === 'REJECTED').length;
    return { uploaded, approved, rejected, total: docs.length };
  };

  if (loading) return (
    <div className="space-y-8 animate-fade-in">
      <div className="h-10 bg-gray-200 rounded-2xl w-64 animate-pulse" />
      <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
        {[1, 2, 3, 4].map(i => <div key={i} className="h-32 bg-white rounded-3xl border border-gray-100 shadow-sm animate-pulse" />)}
      </div>
      <div className="h-64 bg-white rounded-3xl border border-gray-100 shadow-sm animate-pulse" />
    </div>
  );

  /* ═══════ DETAIL VIEW ═══════ */
  if (selectedDriver) {
    const stats = getDocStats(selectedDriver.documents);
    const driverDocTypes = ['dvla_driving_license', 'dvla_check_code', 'pco_driver_badge', 'private_hire_driver_licence', 'bank_statement'];
    const vehicleDocTypes = ['private_hire_vehicle_licence', 'mot_test_certificate', 'v5c_logbook', 'insurance_certificate'];
    const driverDocs = selectedDriver.documents.filter(d => driverDocTypes.includes(d.docType));
    const vehicleDocs = selectedDriver.documents.filter(d => vehicleDocTypes.includes(d.docType));
    const otherDocs = selectedDriver.documents.filter(d => !driverDocTypes.includes(d.docType) && !vehicleDocTypes.includes(d.docType));

    return (
      <div className="animate-fade-in max-w-4xl mx-auto space-y-8">
        <button onClick={() => setSelectedDriver(null)}
          className="flex items-center gap-2 text-[15px] font-bold text-gray-500 hover:text-blue-600 mb-2 transition-colors bg-white px-5 py-2.5 rounded-full shadow-sm border border-gray-200 w-fit hover:shadow-md hover:border-blue-200">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth={2} viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" /></svg>
          Back to all drivers
        </button>

        {/* Driver header */}
        <div className="bg-white rounded-3xl border border-gray-100 shadow-xl overflow-hidden">
          <div className="p-8 md:p-10 border-b border-gray-100">
            <div className="flex flex-col md:flex-row md:items-start justify-between gap-6">
              <div className="flex items-center gap-6">
                <div className="w-20 h-20 bg-blue-50 border-2 border-blue-100 rounded-full flex items-center justify-center text-3xl font-bold text-blue-600 shadow-inner">
                  {selectedDriver.user.name?.charAt(0) || 'D'}
                </div>
                <div>
                  <h2 className="text-3xl font-bold text-gray-900 mb-1">{selectedDriver.user.name}</h2>
                  <p className="text-[15px] text-gray-500 font-medium mb-3">{selectedDriver.user.email}{selectedDriver.user.phone ? ` · ${selectedDriver.user.phone}` : ''}</p>
                  <div className="flex flex-wrap items-center gap-3">
                    {selectedDriver.licensingAuthority && (
                      <span className="text-xs font-bold text-gray-600 bg-gray-100 px-3 py-1.5 rounded-lg border border-gray-200 uppercase tracking-wider">{selectedDriver.licensingAuthority}</span>
                    )}
                    {selectedDriver.hasVan && (
                      <span className="text-xs font-bold text-blue-700 bg-blue-50 px-3 py-1.5 rounded-lg border border-blue-200 uppercase tracking-wider">Has own van</span>
                    )}
                  </div>
                </div>
              </div>
              <div className="flex flex-wrap items-center gap-3">
                <span className={`px-4 py-2 rounded-xl text-sm font-bold uppercase tracking-wider ${selectedDriver.status === 'APPROVED' ? 'bg-green-50 text-green-700 border border-green-200' :
                    selectedDriver.status === 'REJECTED' ? 'bg-red-50 text-red-700 border border-red-200' :
                      'bg-amber-50 text-amber-700 border border-amber-200'
                  }`}>{selectedDriver.status}</span>

                {selectedDriver.status === 'PENDING' && (<>
                  <button onClick={() => updateDriverStatus(selectedDriver.id, 'APPROVED')}
                    className="bg-blue-600 text-white px-6 py-2.5 rounded-xl text-sm font-bold hover:bg-blue-700 shadow-sm hover:shadow-md transition-all">Approve Driver</button>
                  <button onClick={() => updateDriverStatus(selectedDriver.id, 'REJECTED')}
                    className="bg-white border border-gray-200 text-gray-700 px-6 py-2.5 rounded-xl text-sm font-bold hover:bg-red-50 hover:text-red-700 hover:border-red-200 transition-all shadow-sm hover:shadow-md">Reject</button>
                </>)}
                {selectedDriver.status === 'APPROVED' && (
                  <button onClick={() => updateDriverStatus(selectedDriver.id, 'REJECTED')} className="bg-white border border-gray-200 text-red-600 px-6 py-2.5 rounded-xl text-sm font-bold hover:bg-red-50 hover:border-red-200 transition-all shadow-sm">Revoke Approval</button>
                )}
                {selectedDriver.status === 'REJECTED' && (
                  <button onClick={() => updateDriverStatus(selectedDriver.id, 'APPROVED')} className="bg-blue-600 text-white px-6 py-2.5 rounded-xl text-sm font-bold hover:bg-blue-700 shadow-sm transition-all">Re-approve</button>
                )}
              </div>
            </div>
          </div>

          {/* Progress */}
          <div className="bg-[#EBE7DF]/30 p-8 md:p-10">
            <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-4">Verification Progress</p>
            <div className="flex flex-wrap items-center gap-6 text-[15px] font-bold">
              <span className="text-gray-900 bg-white px-4 py-2 rounded-xl shadow-sm border border-gray-100">{stats.uploaded}/{stats.total} Uploaded</span>
              <span className="text-green-700 bg-green-50 px-4 py-2 rounded-xl border border-green-200">{stats.approved} Approved</span>
              {stats.rejected > 0 && <span className="text-red-700 bg-red-50 px-4 py-2 rounded-xl border border-red-200 animate-pulse">{stats.rejected} Rejected</span>}
            </div>
            <div className="w-full bg-white border border-gray-200 rounded-full h-3 mt-6 overflow-hidden shadow-inner">
              <div className="bg-green-500 h-3 rounded-full transition-all duration-1000 ease-out" style={{ width: `${stats.total > 0 ? (stats.approved / stats.total) * 100 : 0}%` }} />
            </div>
          </div>
        </div>

        {/* Driver documents */}
        {driverDocs.length > 0 && (
          <section>
            <div className="flex items-center gap-3 mb-6 border-b border-gray-200/60 pb-4">
              <div className="w-2.5 h-2.5 rounded-full bg-blue-500"></div>
              <h3 className="text-sm font-bold text-gray-900 uppercase tracking-widest">Driver Documents</h3>
              <span className="text-[11px] font-bold text-gray-500 bg-gray-100 px-2.5 py-0.5 rounded-full">{driverDocs.length}</span>
            </div>
            <div className="space-y-4 mb-10">
              {driverDocs.map(doc => (
                <DocRow key={doc.id} doc={doc} isReviewing={reviewingDocId === doc.id}
                  allFileUrls={getFileUrls(doc.fileUrl)}
                  allFileNames={getFileNames(doc.fileName)}
                  fullFileUrl={getFileUrl(doc.fileUrl)}
                  onApprove={() => reviewDocument(doc.id, 'APPROVED')}
                  onReject={() => setShowRejectModal(doc.id)}
                  onPreview={(url?: string, name?: string) => { setPreviewDocUrl(url || getFileUrl(doc.fileUrl)!); setPreviewDocName(name || getFileNames(doc.fileName)[0] || doc.label); }}
                />
              ))}
            </div>
          </section>
        )}

        {/* Vehicle documents */}
        {vehicleDocs.length > 0 && (
          <section>
            <div className="flex items-center gap-3 mb-6 border-b border-gray-200/60 pb-4">
              <div className="w-2.5 h-2.5 rounded-full bg-amber-500"></div>
              <h3 className="text-sm font-bold text-gray-900 uppercase tracking-widest">Vehicle Documents</h3>
              <span className="text-[11px] font-bold text-gray-500 bg-gray-100 px-2.5 py-0.5 rounded-full">{vehicleDocs.length}</span>
            </div>
            <div className="space-y-4 mb-10">
              {vehicleDocs.map(doc => (
                <DocRow key={doc.id} doc={doc} isReviewing={reviewingDocId === doc.id}
                  allFileUrls={getFileUrls(doc.fileUrl)}
                  allFileNames={getFileNames(doc.fileName)}
                  fullFileUrl={getFileUrl(doc.fileUrl)}
                  onApprove={() => reviewDocument(doc.id, 'APPROVED')}
                  onReject={() => setShowRejectModal(doc.id)}
                  onPreview={(url?: string, name?: string) => { setPreviewDocUrl(url || getFileUrl(doc.fileUrl)!); setPreviewDocName(name || getFileNames(doc.fileName)[0] || doc.label); }}
                />
              ))}
            </div>
          </section>
        )}

        {/* Other/uncategorized documents */}
        {otherDocs.length > 0 && (
          <section>
            <div className="flex items-center gap-3 mb-6 border-b border-gray-200/60 pb-4">
              <div className="w-2.5 h-2.5 rounded-full bg-purple-500"></div>
              <h3 className="text-sm font-bold text-gray-900 uppercase tracking-widest">Other Documents</h3>
              <span className="text-[11px] font-bold text-gray-500 bg-gray-100 px-2.5 py-0.5 rounded-full">{otherDocs.length}</span>
            </div>
            <div className="space-y-4 mb-10">
              {otherDocs.map(doc => (
                <DocRow key={doc.id} doc={doc} isReviewing={reviewingDocId === doc.id}
                  allFileUrls={getFileUrls(doc.fileUrl)}
                  allFileNames={getFileNames(doc.fileName)}
                  fullFileUrl={getFileUrl(doc.fileUrl)}
                  onApprove={() => reviewDocument(doc.id, 'APPROVED')}
                  onReject={() => setShowRejectModal(doc.id)}
                  onPreview={(url?: string, name?: string) => { setPreviewDocUrl(url || getFileUrl(doc.fileUrl)!); setPreviewDocName(name || getFileNames(doc.fileName)[0] || doc.label); }}
                />
              ))}
            </div>
          </section>
        )}

        {/* Reject modal */}
        {showRejectModal && (
          <div className="fixed inset-0 bg-gray-900/40 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-fade-in" onClick={e => { if (e.target === e.currentTarget) { setShowRejectModal(null); setRejectNote(''); } }}>
            <div className="bg-white rounded-3xl w-full max-w-md shadow-2xl p-8 transform transition-all scale-100">
              <h3 className="text-xl font-bold text-gray-900 mb-2">Reject Document</h3>
              <p className="text-[15px] text-gray-500 mb-6">Provide a reason so the driver can re-upload correctly.</p>
              <textarea value={rejectNote} onChange={e => setRejectNote(e.target.value)}
                placeholder="e.g. Document is blurry, corners not visible…"
                className="w-full border-2 border-gray-200 rounded-2xl px-4 py-3 text-[15px] font-medium text-gray-900 focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all resize-none h-32 mb-6" />
              <div className="flex gap-3">
                <button onClick={() => { setShowRejectModal(null); setRejectNote(''); }}
                  className="flex-1 border border-gray-200 text-gray-700 py-3 rounded-2xl text-[15px] font-bold hover:bg-gray-50 transition-colors">Cancel</button>
                <button onClick={() => reviewDocument(showRejectModal, 'REJECTED', rejectNote)}
                  className="flex-1 bg-red-600 text-white py-3 rounded-2xl text-[15px] font-bold hover:bg-red-700 shadow-sm hover:shadow-lg transition-all">Reject Document</button>
              </div>
            </div>
          </div>
        )}

        {/* Preview modal */}
        {previewDocUrl && (
          <div className="fixed inset-0 bg-gray-900/80 backdrop-blur-md flex items-center justify-center z-50 p-4 animate-fade-in" onClick={() => { setPreviewDocUrl(null); setPreviewDocName(null); }}>
            <div className="bg-white rounded-3xl w-full max-w-5xl shadow-2xl flex flex-col overflow-hidden transform transition-all scale-100" style={{ maxHeight: '90vh' }} onClick={e => e.stopPropagation()}>
              <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 bg-stone-50">
                <h3 className="font-bold text-gray-900 text-lg truncate pr-4">{previewDocName || 'Document Preview'}</h3>
                <button onClick={() => { setPreviewDocUrl(null); setPreviewDocName(null); }} className="w-10 h-10 flex items-center justify-center bg-white rounded-full text-gray-500 hover:text-gray-900 shadow-sm border border-gray-200 hover:bg-gray-50 transition-all">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth={2} viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
              <div className="p-6 bg-stone-100/50 flex-1 overflow-auto flex items-center justify-center min-h-[50vh]">
                {previewDocUrl.toLowerCase().endsWith('.pdf') ? (
                  <iframe src={previewDocUrl} className="w-full h-[70vh] rounded-2xl border border-gray-200 shadow-sm" title={previewDocName || 'PDF'} />
                ) : (
                  <img src={previewDocUrl} alt={previewDocName || 'Document'} className="max-w-full max-h-[70vh] object-contain rounded-2xl shadow-sm border border-gray-200 bg-white" />
                )}
              </div>
              <div className="px-6 py-4 border-t border-gray-100 bg-white flex justify-end">
                <a href={previewDocUrl} target="_blank" rel="noopener noreferrer" className="bg-blue-50 text-blue-700 px-6 py-2.5 rounded-xl text-[15px] font-bold hover:bg-blue-100 transition-colors flex items-center gap-2 border border-blue-200">
                  Open in new tab
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth={2} viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
                </a>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  /* ═══════ LIST VIEW ═══════ */
  const pendingCount = drivers.filter(d => d.status === 'PENDING').length;
  const approvedCount = drivers.filter(d => d.status === 'APPROVED').length;
  const rejectedCount = drivers.filter(d => d.status === 'REJECTED').length;

  return (
    <div className="p-6 md:p-8 lg:p-12 max-w-[1400px] mx-auto">
    <div className="animate-fade-in space-y-12">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 tracking-tight">Driver Documents</h1>
        <p className="text-[15px] text-gray-500 mt-2">Review uploaded documents and manage driver applications.</p>
      </div>

      {/* Summary cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mb-8">
        {[
          { key: 'all' as const, label: 'Total', count: drivers.length, accent: 'text-blue-600' },
          { key: 'pending' as const, label: 'Pending', count: pendingCount, accent: 'text-amber-500' },
          { key: 'approved' as const, label: 'Approved', count: approvedCount, accent: 'text-green-600' },
          { key: 'rejected' as const, label: 'Rejected', count: rejectedCount, accent: 'text-gray-400' },
        ].map(fc => (
          <button key={fc.key} onClick={() => setFilter(fc.key)}
            className={`bg-white p-6 rounded-3xl border shadow-sm transition-all duration-300 text-left hover:shadow-xl group ${filter === fc.key ? 'border-blue-600 ring-1 ring-blue-600 bg-blue-50/20' : 'border-gray-100 hover:border-gray-300'
              }`}>
            <p className="text-[13px] font-semibold text-gray-500 uppercase tracking-wide mb-4">{fc.label}</p>
            <p className={`text-4xl font-bold ${fc.accent} group-hover:scale-105 transition-transform origin-left`}>{fc.count}</p>
          </button>
        ))}
      </div>

      {/* Driver list */}
      <section>
        {filteredDrivers.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {filteredDrivers.map(driver => {
              const s = getDocStats(driver.documents);
              return (
                <button key={driver.id} onClick={() => setSelectedDriver(driver)}
                  className="w-full bg-white rounded-3xl border border-gray-100 shadow-sm hover:shadow-xl transition-all duration-300 text-left group flex flex-col h-full">
                  <div className="p-6 flex-1">
                    <div className="flex items-start justify-between mb-6">
                      <div className="w-14 h-14 bg-stone-100 border border-gray-200 rounded-full flex items-center justify-center text-xl font-bold text-gray-700 shadow-sm">
                        {driver.user.name?.charAt(0) || 'D'}
                      </div>
                      <span className={`px-3 py-1.5 rounded-xl text-xs font-bold uppercase tracking-wider shadow-sm border ${driver.status === 'APPROVED' ? 'bg-green-50 text-green-700 border-green-200' :
                          driver.status === 'REJECTED' ? 'bg-red-50 text-red-700 border-red-200' :
                            'bg-amber-50 text-amber-700 border-amber-200'
                        }`}>{driver.status}</span>
                    </div>
                    <div>
                      <p className="text-xl font-bold text-gray-900 group-hover:text-blue-600 transition-colors mb-1">{driver.user.name}</p>
                      <p className="text-[15px] font-medium text-gray-500">{driver.user.email}</p>
                    </div>
                  </div>

                  <div className="bg-[#EBE7DF]/50 p-5 rounded-b-3xl border-t border-gray-100 flex items-center justify-between mt-auto">
                    <div>
                      <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Documents</p>
                      <p className="text-sm font-bold text-gray-700 flex items-center gap-2">
                        <span className={s.approved === s.total ? 'text-green-600' : 'text-amber-600'}>{s.approved} approved</span>
                        <span className="text-gray-400">of {s.total}</span>
                        {s.rejected > 0 && <span className="bg-red-100 text-red-700 px-2 py-0.5 rounded-md ml-1">{s.rejected} ✕</span>}
                      </p>
                    </div>
                    <div className="w-10 h-10 rounded-full bg-white shadow-sm flex items-center justify-center text-gray-400 group-hover:bg-blue-600 group-hover:text-white transition-all">
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
                    </div>
                  </div>
                </button>
              );
            })}
          </div>
        ) : (
          <div className="bg-white border border-gray-200 border-dashed rounded-3xl p-16 text-center shadow-sm">
            <div className="w-20 h-20 bg-stone-50 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-sm border border-gray-100">
              <span className="text-3xl text-gray-400">📄</span>
            </div>
            <p className="text-lg text-gray-900 font-bold mb-2">No drivers found</p>
            <p className="text-[15px] text-gray-500 font-medium">Try changing your filter criteria.</p>
          </div>
        )}
      </section>
    </div>
    </div>
  );
}

/* ═══════ Document Review Row ═══════ */
function DocRow({ doc, isReviewing, onApprove, onReject, onPreview, fullFileUrl, allFileUrls = [], allFileNames = [] }: {
  doc: DriverDoc; isReviewing: boolean; onApprove: () => void; onReject: () => void; onPreview: (url?: string, name?: string) => void; fullFileUrl: string | null; allFileUrls?: string[]; allFileNames?: string[];
}) {
  const canReview = doc.status === 'UPLOADED';
  const hasFiles = allFileUrls.length > 0;
  const statusIcon = doc.status === 'APPROVED' ? '✓' : doc.status === 'REJECTED' ? '✕' : doc.status === 'UPLOADED' ? '◉' : '○';

  return (
    <div className={`rounded-[2rem] border p-6 flex flex-col gap-5 transition-all bg-white hover:shadow-lg ${doc.status === 'UPLOADED' ? 'border-amber-200 shadow-[0_4px_20px_rgba(251,191,36,0.08)]' :
        doc.status === 'APPROVED' ? 'border-green-200/80 shadow-[0_4px_20px_rgb(0,0,0,0.03)]' :
          doc.status === 'REJECTED' ? 'border-red-200/80 shadow-[0_4px_20px_rgb(0,0,0,0.03)]' :
            'border-gray-200 border-dashed shadow-none'
      }`}>
      {/* Header row */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center gap-4 min-w-0">
          <div className={`w-10 h-10 rounded-2xl flex items-center justify-center text-lg font-bold shrink-0 ${doc.status === 'UPLOADED' ? 'bg-amber-100 text-amber-700' :
              doc.status === 'APPROVED' ? 'bg-green-100 text-green-700' :
                doc.status === 'REJECTED' ? 'bg-red-100 text-red-700' :
                  'bg-gray-100 text-gray-400'
            }`}>{statusIcon}</div>
          <div className="min-w-0">
            <p className="text-[15px] font-extrabold text-gray-900 tracking-tight">{doc.label}</p>
            <div className="flex flex-wrap items-center gap-2 mt-1">
              <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-widest ${doc.status === 'UPLOADED' ? 'bg-amber-50 text-amber-700 border border-amber-200' :
                  doc.status === 'APPROVED' ? 'bg-green-50 text-green-700 border border-green-200' :
                    doc.status === 'REJECTED' ? 'bg-red-50 text-red-700 border border-red-200' :
                      'bg-gray-50 text-gray-500 border border-gray-200'
                }`}>
                {doc.status === 'UPLOADED' ? 'Needs Review' : doc.status === 'APPROVED' ? 'Approved' : doc.status === 'REJECTED' ? 'Rejected' : 'Missing'}
              </span>
              {doc.uploadedAt && <span className="text-[11px] font-medium text-gray-400">Uploaded {new Date(doc.uploadedAt).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}</span>}
            </div>
          </div>
        </div>

        {/* Actions */}
        <div className="flex items-center gap-2 shrink-0">
          {isReviewing ? (
            <div className="w-6 h-6 border-[3px] border-gray-200 border-t-blue-600 rounded-full animate-spin" />
          ) : canReview ? (<>
            <button onClick={onApprove} className="bg-green-600 text-white px-5 py-2.5 rounded-full text-[12px] font-bold uppercase tracking-widest hover:bg-green-700 shadow-sm hover:shadow-md transition-all active:scale-95">Approve</button>
            <button onClick={onReject} className="bg-white border border-red-200 text-red-600 px-5 py-2.5 rounded-full text-[12px] font-bold uppercase tracking-widest hover:bg-red-50 transition-all active:scale-95">Reject</button>
          </>) : null}
        </div>
      </div>

      {/* File thumbnails */}
      {hasFiles ? (
        <div className="flex flex-wrap gap-3">
          {allFileUrls.map((url, i) => {
            const name = allFileNames[i] || `File ${i + 1}`;
            const isPdf = url.toLowerCase().includes('.pdf');
            return (
              <button key={i} onClick={() => onPreview(url, name)} className="group relative rounded-2xl overflow-hidden border border-gray-200 hover:border-blue-400 shadow-sm hover:shadow-lg transition-all bg-gray-50 flex flex-col items-center justify-center w-[140px] h-[100px] active:scale-95">
                {isPdf ? (
                  <div className="flex flex-col items-center justify-center gap-1">
                    <svg className="w-8 h-8 text-red-500" fill="currentColor" viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8l-6-6zm-1 2l5 5h-5V4zM8.5 13h1v4h-1v-4zm2.5 0h1.5l1 2.5L14.5 13H16v4h-1v-2.5l-1 2.5-1-2.5V17h-1v-4zm5 0h1v3h1.5v1H16v-4z" /></svg>
                    <span className="text-[10px] font-bold text-gray-500 uppercase tracking-wider">PDF</span>
                  </div>
                ) : (
                  <img src={url} alt={name} className="w-full h-full object-cover" />
                )}
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/30 transition-colors flex items-center justify-center">
                  <svg className="w-6 h-6 text-white opacity-0 group-hover:opacity-100 transition-opacity" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                </div>
                <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/60 to-transparent px-2 py-1.5">
                  <span className="text-[10px] font-bold text-white truncate block">{name}</span>
                </div>
              </button>
            );
          })}
        </div>
      ) : (
        <div className="bg-gray-50/80 border border-gray-200 border-dashed rounded-2xl px-5 py-4 flex items-center gap-3">
          <svg className="w-5 h-5 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}><path strokeLinecap="round" strokeLinejoin="round" d="M12 9v6m3-3H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          <p className="text-[13px] text-gray-500 font-medium">No file uploaded yet</p>
        </div>
      )}

      {/* Review note */}
      {doc.reviewNote && (
        <div className="bg-red-50/80 border border-red-200/80 rounded-2xl p-4 flex gap-3 items-start">
          <svg className="w-5 h-5 text-red-500 shrink-0 mt-0.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          <p className="text-[13px] font-medium text-red-700 leading-relaxed">{doc.reviewNote}</p>
        </div>
      )}
    </div>
  );
}

'use client';
import { getAccessToken } from '@/lib/auth-token';

import { useEffect, useState } from 'react';
import { cachedJson, invalidateCache } from '@/lib/client-cache';

import { getImageUrl } from '@/lib/image-url';

const API = process.env.API_URL;
const BASE_URL = API?.replace(/\/api$/, '') || '';
const authHeaders = () => ({
  Authorization: `Bearer ${getAccessToken()}`,
  'Content-Type': 'application/json',
});

const getFileUrl = (path: string | null | undefined) => {
  if (!path) return null;
  return getImageUrl(path);
};

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

interface DriverDoc {
  id: string;
  docType: string;
  label: string;
  fileName: string | null;
  fileUrl?: string | null;
  status: 'NOT_PROVIDED' | 'UPLOADED' | 'APPROVED' | 'REJECTED';
  reviewNote: string | null;
  uploadedAt: string | null;
  reviewedAt: string | null;
}

export default function FleetPage() {
  const [drivers, setDrivers] = useState<any[]>([]);
  const [driversWithDocs, setDriversWithDocs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [reviewingDocId, setReviewingDocId] = useState<string | null>(null);
  const [rejectNote, setRejectNote] = useState('');
  const [showRejectModal, setShowRejectModal] = useState<string | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [previewName, setPreviewName] = useState<string | null>(null);
  const [tab, setTab] = useState<'all' | 'pending' | 'approved' | 'rejected'>('all');

  useEffect(() => { fetchAll(); }, []);

  const fetchAll = async () => {
    try {
      const [driversData, driversWithDocsData] = await Promise.all([
        cachedJson<any[]>(`${API}/manager/drivers`, { headers: authHeaders() }, { ttl: 30_000 }),
        cachedJson<any[]>(`${API}/manager/drivers-with-documents`, { headers: authHeaders() }, { ttl: 30_000 }),
      ]);
      setDrivers(driversData || []);
      setDriversWithDocs(driversWithDocsData || []);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  const updateStatus = async (id: string, status: string) => {
    try {
      await fetch(`${API}/manager/drivers/${id}/status`, {
        method: 'PATCH', headers: authHeaders(),
        body: JSON.stringify({ status }),
      });
      invalidateCache('/manager/drivers');
      fetchAll();
    } catch (err: any) { alert(err.message); }
  };

  const reviewDocument = async (docId: string, status: 'APPROVED' | 'REJECTED', note?: string) => {
    setReviewingDocId(docId);
    try {
      await fetch(`${API}/manager/documents/${docId}/review`, {
        method: 'PATCH', headers: authHeaders(),
        body: JSON.stringify({ status, reviewNote: note || undefined }),
      });
      invalidateCache('/manager/drivers');
      fetchAll();
    } catch (err) { console.error(err); }
    finally { setReviewingDocId(null); setShowRejectModal(null); setRejectNote(''); }
  };

  if (loading) return (
    <div className="space-y-8 animate-fade-in">
      <div className="h-10 bg-gray-200 rounded-2xl w-64 animate-pulse" />
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {[1,2,3].map(i => <div key={i} className="h-32 bg-white rounded-3xl border border-gray-100 shadow-sm animate-pulse" />)}
      </div>
      <div className="h-64 bg-white rounded-3xl border border-gray-100 shadow-sm animate-pulse" />
    </div>
  );

  // Merge availability data
  const merged = driversWithDocs.map(dwd => {
    const driverData = drivers.find(d => d.id === dwd.id);
    return { ...dwd, availability: driverData?.availability || [], bookings: driverData?.bookings || [], isOnline: driverData?.isOnline ?? false };
  });

  const pending = merged.filter(d => d.status === 'PENDING' || !d.status);
  const approved = merged.filter(d => d.status === 'APPROVED');
  const rejected = merged.filter(d => d.status === 'REJECTED');
  const filtered = tab === 'pending' ? pending : tab === 'approved' ? approved : tab === 'rejected' ? rejected : merged;

  const todayDow = new Date().getDay();

  return (
    <div className="animate-fade-in space-y-12">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 tracking-tight">Drivers</h1>
        <p className="text-[15px] text-gray-500 mt-2">Manage applications, availability, and documents.</p>
      </div>

      {/* Summary */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {[
          { label: 'Approved', count: approved.length, accent: 'text-green-600', sub: `${approved.filter(d => d.isOnline).length} online` },
          { label: 'Pending', count: pending.length, accent: 'text-amber-500' },
          { label: 'Rejected', count: rejected.length, accent: 'text-gray-400' },
        ].map(c => (
          <div key={c.label} className="bg-white border border-gray-100 rounded-3xl p-6 shadow-sm hover:shadow-xl transition-all duration-300 group">
            <p className="text-[13px] font-semibold text-gray-500 uppercase tracking-wide mb-4">{c.label}</p>
            <h3 className={`text-4xl font-bold ${c.accent} group-hover:scale-105 transition-transform origin-left`}>{c.count}</h3>
            {c.sub && <p className="text-sm text-gray-400 mt-2 font-medium">{c.sub}</p>}
          </div>
        ))}
      </div>

      {/* Driver list section */}
      <section>
        {/* Filter tabs */}
        <div className="flex items-center gap-2 mb-8 bg-stone-50 p-1.5 rounded-full w-fit border border-gray-200/50">
          {(['all', 'pending', 'approved', 'rejected'] as const).map(t => (
            <button
              key={t}
              onClick={() => setTab(t)}
              className={`px-5 py-2.5 rounded-full text-sm font-bold transition-all capitalize ${
                tab === t 
                  ? 'bg-white text-blue-700 shadow-sm border border-gray-200' 
                  : 'text-gray-500 hover:text-gray-900 border border-transparent'
              }`}
            >
              {t} {t === 'pending' && pending.length > 0 ? <span className="ml-1.5 bg-amber-100 text-amber-700 px-2 py-0.5 rounded-full text-[10px]">{pending.length}</span> : ''}
            </button>
          ))}
        </div>

        {/* List */}
        {filtered.length > 0 ? (
          <div className="space-y-4">
            {filtered.map(driver => {
              const isExpanded = expandedId === driver.id;
              const docs: DriverDoc[] = driver.documents || [];
              const approvedDocs = docs.filter((d: DriverDoc) => d.status === 'APPROVED').length;
              const totalDocs = docs.length;
              const todaySlot = (driver.availability || []).find((s: any) => s.dayOfWeek === todayDow);
              const availableToday = todaySlot?.isActive;

              return (
                <div key={driver.id} className="bg-white border border-gray-100 rounded-3xl shadow-sm hover:shadow-lg transition-all duration-300 overflow-hidden group">
                  {/* Row header */}
                  <button
                    onClick={() => setExpandedId(isExpanded ? null : driver.id)}
                    className="w-full p-6 flex flex-col md:flex-row md:items-center justify-between text-left gap-4 bg-white hover:bg-stone-50 transition-colors"
                  >
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 bg-stone-100 rounded-full flex items-center justify-center text-lg font-bold text-gray-700 shadow-sm">
                        {driver.user?.name?.charAt(0) || 'D'}
                      </div>
                      <div>
                        <p className="text-[15px] font-bold text-gray-900 group-hover:text-blue-600 transition-colors">{driver.user?.name}</p>
                        <p className="text-sm text-gray-500 font-medium">{driver.user?.email}</p>
                      </div>
                    </div>

                    <div className="flex items-center gap-6 self-end md:self-auto">
                      {/* Availability today */}
                      <div className="hidden lg:flex items-center gap-2">
                        <span className={`w-2 h-2 rounded-full ${availableToday ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.4)]' : 'bg-gray-300'}`} />
                        <span className={`text-sm font-bold ${availableToday ? 'text-green-600' : 'text-gray-400'}`}>
                          {availableToday ? `${todaySlot.startTime}–${todaySlot.endTime}` : 'Off today'}
                        </span>
                      </div>

                      <div className="hidden sm:block text-right">
                        <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-0.5">Jobs</p>
                        <p className="text-sm font-bold text-gray-700">{driver.bookings?.length ?? 0}</p>
                      </div>

                      <div className="hidden sm:block text-right">
                        <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-0.5">Docs</p>
                        <p className="text-sm font-bold text-gray-700"><span className={approvedDocs === totalDocs ? 'text-green-600' : 'text-amber-600'}>{approvedDocs}</span><span className="text-gray-300 mx-1">/</span>{totalDocs}</p>
                      </div>

                      <div className="flex items-center gap-4">
                        <span className={`px-3 py-1 rounded-lg text-[11px] font-bold uppercase tracking-wider ${
                          driver.status === 'APPROVED' ? 'text-green-700 bg-green-50' :
                          driver.status === 'REJECTED' ? 'text-red-700 bg-red-50' :
                          'text-amber-700 bg-amber-50'
                        }`}>{driver.status || 'PENDING'}</span>
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center bg-gray-50 text-gray-400 transition-transform duration-300 ${isExpanded ? 'rotate-180 bg-blue-50 text-blue-600' : 'group-hover:bg-gray-100'}`}>
                          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                          </svg>
                        </div>
                      </div>
                    </div>
                  </button>

                  {/* Expanded detail */}
                  {isExpanded && (
                    <div className="border-t border-gray-100 bg-[#EBE7DF]/30">
                      <div className="p-6 md:p-8">
                        {/* Contact & Actions */}
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8 bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-y-3 gap-x-8 text-sm">
                            <div>
                              <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide mb-1">Phone</p>
                              <p className="font-bold text-gray-900">{driver.user?.phone || 'Not provided'}</p>
                            </div>
                            {driver.licensingAuthority && (
                              <div>
                                <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide mb-1">Authority</p>
                                <p className="font-bold text-gray-900">{driver.licensingAuthority}</p>
                              </div>
                            )}
                            {driver.hasVan && (
                              <div className="col-span-1 sm:col-span-2">
                                <span className="inline-flex items-center gap-1.5 bg-blue-50 text-blue-700 px-3 py-1 rounded-lg text-xs font-bold border border-blue-100 uppercase tracking-wider">
                                  <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" /></svg>
                                  Has own van
                                </span>
                              </div>
                            )}
                          </div>

                          <div className="flex flex-wrap items-center gap-3">
                            {(driver.status === 'PENDING' || !driver.status) && (<>
                              <button onClick={() => updateStatus(driver.id, 'APPROVED')} className="bg-blue-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-blue-700 hover:shadow-lg transition-all">Approve Driver</button>
                              <button onClick={() => updateStatus(driver.id, 'REJECTED')} className="bg-white border border-gray-200 text-gray-700 px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-red-50 hover:text-red-700 hover:border-red-200 transition-all">Reject</button>
                            </>)}
                            {driver.status === 'APPROVED' && (
                              <button onClick={() => updateStatus(driver.id, 'REJECTED')} className="bg-white border border-gray-200 text-red-600 px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-red-50 transition-all">Revoke Approval</button>
                            )}
                            {driver.status === 'REJECTED' && (
                              <button onClick={() => updateStatus(driver.id, 'APPROVED')} className="bg-blue-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-blue-700 hover:shadow-lg transition-all">Re-approve</button>
                            )}
                          </div>
                        </div>

                        {/* Weekly availability */}
                        <div className="mb-8">
                          <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-4">Weekly Availability</p>
                          <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-7 gap-2">
                            {DAYS.map((day, i) => {
                              const slot = (driver.availability || []).find((s: any) => s.dayOfWeek === i);
                              const active = slot?.isActive;
                              return (
                                <div key={i} className={`p-3 rounded-2xl border text-center transition-all ${
                                  active ? 'bg-blue-50 border-blue-200 shadow-sm' : 'bg-white border-gray-100 opacity-60'
                                }`}>
                                  <p className={`text-xs font-bold uppercase tracking-wider mb-1 ${active ? 'text-blue-900' : 'text-gray-400'}`}>{day}</p>
                                  {active ? (
                                    <p className="text-[11px] font-bold text-blue-600">{slot.startTime}–<br/>{slot.endTime}</p>
                                  ) : (
                                    <p className="text-[11px] font-medium text-gray-400">Off</p>
                                  )}
                                </div>
                              );
                            })}
                          </div>
                        </div>

                        {/* Documents */}
                        <div>
                          <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-4 flex items-center gap-2">
                            Documents
                            <span className="bg-white border border-gray-200 text-gray-600 px-2 py-0.5 rounded-full text-[10px] normal-case tracking-normal">{approvedDocs}/{totalDocs} approved</span>
                          </p>
                          <div className="space-y-3">
                            {docs.map((doc: DriverDoc) => {
                              const hasFile = doc.fileName && doc.fileUrl;
                              const fullUrl = getFileUrl(doc.fileUrl);
                              const canReview = doc.status === 'UPLOADED';
                              return (
                                <div key={doc.id} className={`flex flex-col sm:flex-row sm:items-center justify-between p-4 rounded-2xl border gap-4 transition-all shadow-sm ${
                                  doc.status === 'APPROVED' ? 'border-green-200 bg-green-50/50' :
                                  doc.status === 'REJECTED' ? 'border-red-200 bg-red-50/50' :
                                  doc.status === 'UPLOADED' ? 'border-amber-200 bg-amber-50/50' :
                                  'border-gray-200 bg-white'
                                }`}>
                                  <div className="flex-1 min-w-0">
                                    <div className="flex items-center gap-3 mb-1">
                                      <p className="font-bold text-gray-900 text-[15px]">{doc.label}</p>
                                      <span className={`px-2 py-0.5 rounded-lg text-[10px] font-bold uppercase tracking-wider ${
                                        doc.status === 'APPROVED' ? 'text-green-700 bg-green-100' :
                                        doc.status === 'REJECTED' ? 'text-red-700 bg-red-100' :
                                        doc.status === 'UPLOADED' ? 'text-amber-700 bg-amber-100 animate-pulse' :
                                        'text-gray-500 bg-gray-100'
                                      }`}>
                                        {doc.status === 'UPLOADED' ? 'Needs Review' : doc.status === 'NOT_PROVIDED' ? 'Missing' : doc.status}
                                      </span>
                                    </div>

                                    {hasFile && (
                                      <div className="flex flex-wrap items-center gap-3 mt-2 text-sm">
                                        <span className="text-gray-500 font-medium truncate max-w-[200px]">{doc.fileName}</span>
                                        <button onClick={() => { setPreviewUrl(fullUrl!); setPreviewName(doc.fileName); }} className="text-blue-600 hover:text-blue-700 font-bold hover:underline transition-all">View</button>
                                        <span className="text-gray-300">•</span>
                                        <a href={fullUrl!} download target="_blank" rel="noopener noreferrer" className="text-gray-500 hover:text-gray-700 font-bold hover:underline transition-all">Download</a>
                                      </div>
                                    )}
                                    {!hasFile && doc.status === 'NOT_PROVIDED' && <p className="text-sm text-gray-400 font-medium mt-1">Not uploaded yet</p>}
                                    {doc.reviewNote && <p className="text-sm text-red-600 font-medium mt-2 bg-red-100/50 p-2 rounded-lg inline-block border border-red-100">Note: {doc.reviewNote}</p>}
                                  </div>

                                  <div className="flex items-center gap-2 shrink-0">
                                    {reviewingDocId === doc.id ? (
                                      <div className="w-5 h-5 border-2 border-gray-200 border-t-blue-600 rounded-full animate-spin" />
                                    ) : canReview ? (<>
                                      <button onClick={() => reviewDocument(doc.id, 'APPROVED')} className="bg-white border border-green-200 text-green-700 px-4 py-2 rounded-xl text-sm font-bold hover:bg-green-50 transition-colors shadow-sm">Approve</button>
                                      <button onClick={() => setShowRejectModal(doc.id)} className="bg-white border border-red-200 text-red-600 px-4 py-2 rounded-xl text-sm font-bold hover:bg-red-50 transition-colors shadow-sm">Reject</button>
                                    </>) : null}
                                  </div>
                                </div>
                              );
                            })}
                          </div>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        ) : (
          <div className="bg-white border border-gray-200 border-dashed rounded-3xl p-12 text-center shadow-sm">
            <div className="w-16 h-16 bg-stone-50 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <span className="text-2xl text-gray-400">👥</span>
            </div>
            <p className="text-[15px] text-gray-500 font-medium">No drivers match the selected filter.</p>
          </div>
        )}
      </section>

      {/* Reject modal */}
      {showRejectModal && (
        <div className="fixed inset-0 bg-gray-900/40 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-fade-in" onClick={e => { if (e.target === e.currentTarget) { setShowRejectModal(null); setRejectNote(''); } }}>
          <div className="bg-white rounded-3xl w-full max-w-md shadow-2xl p-8 transform transition-all scale-100">
            <h3 className="text-xl font-bold text-gray-900 mb-2">Reject Document</h3>
            <p className="text-[15px] text-gray-500 mb-6">Provide a reason so the driver can re-upload correctly.</p>
            <textarea value={rejectNote} onChange={e => setRejectNote(e.target.value)}
              placeholder="e.g. Document is blurry, corners not visible…"
              className="w-full border-2 border-gray-200 rounded-2xl px-4 py-3 text-[15px] font-medium text-gray-900 focus:outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 transition-all resize-none h-32 mb-6" />
            <div className="flex gap-3">
              <button onClick={() => { setShowRejectModal(null); setRejectNote(''); }}
                className="flex-1 border border-gray-200 text-gray-700 py-3 rounded-2xl text-[15px] font-bold hover:bg-gray-50 transition-colors">Cancel</button>
              <button onClick={() => reviewDocument(showRejectModal, 'REJECTED', rejectNote)}
                className="flex-1 bg-red-600 text-white py-3 rounded-2xl text-[15px] font-bold hover:bg-red-700 shadow-sm hover:shadow-lg transition-all">Reject Document</button>
            </div>
          </div>
        </div>
      )}

      {/* Preview modal */}
      {previewUrl && (
        <div className="fixed inset-0 bg-gray-900/80 backdrop-blur-md flex items-center justify-center z-50 p-4 animate-fade-in" onClick={() => { setPreviewUrl(null); setPreviewName(null); }}>
          <div className="bg-white rounded-3xl w-full max-w-5xl shadow-2xl flex flex-col overflow-hidden transform transition-all scale-100" style={{ maxHeight: '90vh' }} onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 bg-stone-50">
              <h3 className="font-bold text-gray-900 text-lg truncate pr-4">{previewName || 'Document Preview'}</h3>
              <button onClick={() => { setPreviewUrl(null); setPreviewName(null); }} className="w-10 h-10 flex items-center justify-center bg-white rounded-full text-gray-500 hover:text-gray-900 shadow-sm border border-gray-200 hover:bg-gray-50 transition-all">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth={2} viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
            <div className="p-6 bg-stone-100/50 flex-1 overflow-auto flex items-center justify-center min-h-[50vh]">
              {previewUrl.toLowerCase().endsWith('.pdf') ? (
                <iframe src={previewUrl} className="w-full h-[70vh] rounded-2xl border border-gray-200 shadow-sm" title={previewName || 'PDF'} />
              ) : (
                <img src={previewUrl} alt={previewName || 'Document'} className="max-w-full max-h-[70vh] object-contain rounded-2xl shadow-sm border border-gray-200 bg-white" />
              )}
            </div>
            <div className="px-6 py-4 border-t border-gray-100 bg-white flex justify-end">
              <a href={previewUrl} target="_blank" rel="noopener noreferrer" className="bg-blue-50 text-blue-700 px-6 py-2.5 rounded-xl text-[15px] font-bold hover:bg-blue-100 transition-colors flex items-center gap-2 border border-blue-200">
                Open in new tab
                <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth={2} viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"/></svg>
              </a>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

