export default function ManagerLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const router = useRouter();
  const [authState, setAuthState] = useState<AuthState>('loading');
  const [user, setUser] = useState<any>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  // M13: managerCity removed — data is global, no per-city column exists
  const isPublicManagerRoute = pathname === '/manager/apply' || pathname === '/manager/apply/';

  // A5: debugInfo removed — don't expose role/error to users

  useEffect(() => {
    checkAccess();
  }, [pathname]);

  const checkAccess = async () => {
    if (isPublicManagerRoute) {
      setAuthState('authorized');
      return;
    }

    // getAccessToken() reads localStorage first, then falls back to the
    // shared .nglob.com cookie — which IS accessible across subdomains.
    let token = getAccessToken();
    if (!token) {
      const isLocalhost = window.location.hostname === 'localhost' || window.location.hostname.endsWith('.local');
      window.location.href = isLocalhost ? `http://nglob.local:3000/?login=true&redirect=/manager` : `https://www.nglob.com/?login=true&redirect=/manager`;
      return;
    }

    try {
      const res = await fetch(`${API}/users/me`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        clearAuth();
        const isLocalhost = window.location.hostname === 'localhost' || window.location.hostname.endsWith('.local');
        window.location.href = isLocalhost ? `http://nglob.local:3000/?login=true&redirect=/manager` : `https://www.nglob.com/?login=true&redirect=/manager`;
        return;
      }

      const userData = await res.json();
      setUser(userData);

      if (userData.role !== 'ADMIN' && userData.role !== 'MANAGER') {
        setAuthState('unauthorized');
        return;
      }

      // ADMINs always have full access; MANAGERs need an approved application
      if (userData.role === 'MANAGER') {
        const appRes = await fetch(`${API}/manager/application-status`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        // A5: appRes may return 204 No Content (no application) — guard against empty body
        if (appRes.ok && appRes.status !== 204) {
          const appData = await appRes.json().catch(() => null);
          if (!appData || appData?.status !== 'APPROVED') {
            setAuthState('pending');
            return;
          }
        } else {
          // No application found — treat as pending
          setAuthState('pending');
          return;
        }
      }

      // M13: managerCity removed

      setAuthState('authorized');
    } catch (e: any) {
      setAuthState('unauthorized');
    }
  };

  const handleLogout = async () => {
    const refreshToken = getRefreshToken();
    if (refreshToken) {
      try {
        await fetch(`${API}/auth/logout`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ refreshToken }),
        });
      } catch (e) {
        // ignore errors on logout
      }
    }
    clearAuth();
    const hostname = window.location.hostname;
    const isLocalhost = hostname === 'localhost' || hostname.endsWith('.local');
    window.location.href = isLocalhost ? `http://nglob.local:3000/` : `https://www.nglob.com/`;
  };

  if (isPublicManagerRoute) {
    return <>{children}</>;
  }

  if (authState === 'loading') {
    return (
      <div className="min-h-[85vh] flex items-center justify-center bg-white">
        <div className="flex flex-col items-center gap-3">
          <div className="w-8 h-8 border-2 border-gray-200 border-t-blue-600 rounded-full animate-spin" />
          <p className="text-gray-500 font-medium">Verifying access…</p>
        </div>
      </div>
    );
  }

  if (authState === 'pending') {
    return (
      <div className="min-h-[85vh] flex items-center justify-center bg-white px-6">
        <div className="bg-white rounded-3xl border border-gray-100 shadow-xl p-10 max-w-md text-center">
          <div className="w-16 h-16 bg-blue-50 rounded-2xl flex items-center justify-center mx-auto mb-6 text-3xl">
            ⏳
          </div>
          <h2 className="text-2xl font-bold text-gray-900 mb-3">Application Under Review</h2>
          <p className="text-sm text-gray-500 mb-4 leading-relaxed">
            Your manager application is being reviewed by the team. You'll gain full access once it's approved.
          </p>
          <div className="bg-blue-50 border border-blue-100 rounded-xl p-4 mb-6">
            <div className="flex items-center gap-3">
              <span className="w-2.5 h-2.5 bg-blue-600 rounded-full animate-pulse" />
              <span className="text-sm font-semibold text-blue-700">Status: Pending Approval</span>
            </div>
            <p className="text-xs text-blue-600 mt-2">This usually takes 1–2 business days.</p>
          </div>
          <button
            onClick={() => router.push('/')}
            className="w-full bg-blue-600 text-white py-3.5 rounded-2xl text-sm font-semibold hover:bg-blue-700 hover:shadow-lg transition-all"
          >
            Back to Home
          </button>
        </div>
      </div>
    );
  }

  if (authState === 'unauthorized') {
    return (
      <div className="min-h-[85vh] flex items-center justify-center bg-white px-6">
        <div className="bg-white rounded-3xl border border-gray-100 shadow-xl p-10 max-w-md text-center">
          <div className="w-16 h-16 bg-stone-50 rounded-2xl flex items-center justify-center mx-auto mb-6">
            <svg className="w-8 h-8 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
            </svg>
          </div>
          <h2 className="text-2xl font-bold text-gray-900 mb-3">Manager Access Only</h2>
          <p className="text-sm text-gray-500 mb-8 leading-relaxed">
            This area is restricted to authorized managers. Contact the system admin if you believe you should have access.
          </p>
          <div className="flex flex-col gap-3">
            <Link
              href="/manager/apply"
              className="w-full bg-blue-600 text-white py-3.5 rounded-2xl text-sm font-semibold hover:bg-blue-700 hover:shadow-lg transition-all"
            >
              Apply as a Manager
            </Link>
            <button
              onClick={() => router.push('/')}
              className="w-full border border-gray-200 text-gray-600 py-3.5 rounded-2xl text-sm font-medium hover:bg-gray-50 transition-colors"
            >
              Back to Home
            </button>
          </div>
        </div>
      </div>
    );
  }

  const links = [
    { name: 'Operations Hub', href: '/manager', icon: <IconGrid /> },
    { name: 'Live Tracking & Logistics', href: '/manager/live-rides', icon: <IconMap /> },
    { name: 'Drivers', href: '/manager/fleet', icon: <IconUsers /> },

    { name: 'Prices', href: '/manager/prices', icon: <IconCurrency /> },
    { name: 'Documents', href: '/manager/documents', icon: <IconDoc /> },
  ];

  return (
    <div className="min-h-[100vh] bg-stone-50 flex">
      {/* Mobile sidebar toggle */}
      <button
        onClick={() => setSidebarOpen(!sidebarOpen)}
        className="lg:hidden fixed top-20 left-6 z-30 bg-white border border-gray-200 rounded-xl p-2.5 shadow-sm hover:bg-stone-50 transition-colors"
        aria-label="Toggle sidebar"
      >
        <svg className="w-6 h-6 text-gray-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          {sidebarOpen ? (
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          ) : (
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          )}
        </svg>
      </button>

      {/* Sidebar overlay on mobile */}
      {sidebarOpen && (
        <div className="fixed inset-0 bg-gray-900/40 backdrop-blur-sm z-20 lg:hidden transition-opacity" onClick={() => setSidebarOpen(false)} />
      )}

      {/* Sidebar */}
      <aside className={`
        w-[260px] bg-white border-r border-gray-200 shrink-0 flex flex-col
        fixed lg:static inset-y-0 left-0 z-20 pt-16 lg:pt-0
        transition-transform duration-300 ease-out lg:translate-x-0
        ${sidebarOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full'}
      `}>
        <div className="flex-1 py-8">
          {/* Header */}
          <div className="px-8 mb-8">
            <h2 className="text-sm font-semibold text-gray-500 uppercase tracking-wide">Manager Portal</h2>
          </div>

          {/* Navigation */}
          <nav className="px-4 space-y-1">
            {links.map(link => {
              const active = pathname === link.href || (pathname.startsWith(link.href) && link.href !== '/manager');
              return (
                <Link
                  key={link.href}
                  href={link.href}
                  onClick={() => setSidebarOpen(false)}
                  className={`group flex items-center gap-3.5 px-4 py-3.5 rounded-2xl text-[15px] font-medium transition-all ${
                    active
                      ? 'bg-blue-50 text-blue-700 border border-blue-100/50'
                      : 'text-gray-600 hover:bg-stone-50 hover:text-gray-900 border border-transparent'
                  }`}
                >
                  <span className={`${active ? 'text-blue-600' : 'text-gray-400 group-hover:text-gray-600 group-hover:scale-110 transition-transform'}`}>
                    {link.icon}
                  </span>
                  {link.name}
                </Link>
              );
            })}
          </nav>
        </div>

        {/* User info + logout */}
        <div className="border-t border-gray-100 p-6">
          <div className="flex items-center gap-3.5 mb-6">
            <div className="w-10 h-10 bg-stone-50 border border-gray-100 rounded-full flex items-center justify-center text-sm font-bold text-gray-700">
              {user?.name?.charAt(0) || 'M'}
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-[15px] font-bold text-gray-900 truncate">{user?.name || 'Manager'}</p>
              <p className="text-xs text-gray-500 truncate">{user?.email}</p>
            </div>
          </div>
          <button
            onClick={handleLogout}
            className="w-full flex items-center justify-center gap-2.5 px-4 py-3 rounded-2xl text-[15px] font-medium text-gray-500 border border-gray-200 hover:text-red-600 hover:bg-red-50 hover:border-red-100 transition-all group"
          >
            <span className="group-hover:scale-110 transition-transform"><IconLogout /></span>
            Sign out
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">

          <ErrorBoundary>
            {children}
          </ErrorBoundary>

      </main>
    </div>
  );
}

