const MapPreview = dynamic(() => import('@/components/booking/MapPreview'), { ssr: false });

const API = process.env.API_URL || 'https://api.nglob.com/api';
const WS_URL = process.env.NEXT_PUBLIC_WS_URL || API?.replace(/\/api$/, '') || 'http://localhost:3001';

const authHeaders = () => ({
  Authorization: `Bearer ${getAccessToken()}`,
  'Content-Type': 'application/json',
});

import { getImageUrl } from '@/lib/image-url';

// Van definitions (Volume in m³)
const VAN_SIZES = [
  { id: 'small', name: 'Small Van', volume: 6, maxWeight: 800 },
  { id: 'medium', name: 'Medium Transit', volume: 10, maxWeight: 1200 },
  { id: 'large', name: 'Luton Van', volume: 15, maxWeight: 1500 },
];

export default function LiveRidesPage() {
  const [rides, setRides] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  // Selection & Filters
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<string | null>(null); // null = all

  // Tab state for the bottom section of right panel
  const [activeTab, setActiveTab] = useState<'details' | 'photos' | 'vehicle'>('details');
  const [showLifo, setShowLifo] = useState(false);
  const [showOldInfo, setShowOldInfo] = useState(false);

  const fetchRides = async () => {
    try {
      const activePromise = cachedJson<any[]>(
        `${API}/manager/active-rides`,
        { headers: authHeaders() },
        { ttl: 5_000 },
      );

      let data: any[] = [];
      if (showOldInfo) {
        const completedPromise = cachedJson<any[]>(
          `${API}/manager/completed-rides`,
          { headers: authHeaders() },
          { ttl: 5_000 },
        );
        const [active, completed] = await Promise.all([activePromise, completedPromise]);

        const all = [...(active || []), ...(completed || [])];
        const unique = Array.from(new Map(all.map(item => [item.id, item])).values());

        unique.sort((a: any, b: any) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime());
        data = unique;
      } else {
        const active = await activePromise;
        data = active || [];
      }

      const enhanced = data.map((b: any) => {
        const createdAt = new Date(b.createdAt || Date.now() - Math.random() * 86400000);
        const pickupDate = b.pickupDate ? new Date(b.pickupDate) : createdAt;

        const [, slotEndHour] = parseSlot(b.pickupTimeSlot);
        const deadline = new Date(pickupDate);
        deadline.setHours(slotEndHour, 0, 0, 0);

        const now = new Date();
        const isPastDeadline = now.getTime() > deadline.getTime();
        const isUncompleted = isPastDeadline && !b.driverId && b.status !== 'DELIVERED';

        let trackStatus = 'checking';
        if (b.status === 'CANCELLED') trackStatus = 'cancelled';
        else if (isUncompleted) trackStatus = 'uncompleted';
        else if (b.status === 'DELIVERED') trackStatus = 'delivered';
        else if (b.status === 'SCHEDULED' || (b.status === 'CONFIRMED' && b.driverId)) trackStatus = 'scheduled';
        else if (b.status === 'ARRIVED' || b.status === 'PACKED' || b.status === 'LOADED' || b.status === 'IN_TRANSIT' || b.status === 'UNLOADING') trackStatus = 'transit';

        return {
          ...b,
          trackStatus,
          timeChecking: new Date(createdAt.getTime() + 1000 * 60 * 30).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
          timeTransit: trackStatus !== 'checking' ? new Date(createdAt.getTime() + 1000 * 60 * 120).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '--:--',
          timeDelivered: trackStatus === 'delivered' ? new Date(createdAt.getTime() + 1000 * 60 * 240).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '--:--'
        };
      });

      setRides(enhanced);
      if (enhanced && enhanced.length > 0 && !selectedId) {
        setSelectedId(enhanced[0].id);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRides();

    const token = getAccessToken();
    if (!token) return;

    const socket: Socket = io(`${WS_URL}/tracking`, {
      auth: { token },
      transports: ['polling', 'websocket'],
    });

    socket.on('connect', () => socket.emit('subscribe-manager'));
    socket.on('dashboard-updated', () => {
      invalidateCache('/manager/active-rides');
      fetchRides();
    });

    socket.on('driver-location', (data: { bookingId: string, lat: number, lng: number, status: string }) => {
      setRides(prev => prev.map(ride => {
        if (ride.id === data.bookingId) {
          return {
            ...ride,
            status: data.status,
            driver: {
              ...ride.driver,
              currentLat: data.lat,
              currentLng: data.lng,
            }
          };
        }
        return ride;
      }));
    });

    return () => {
      socket.disconnect();
    };
  }, []);

  useEffect(() => { fetchRides(); }, [showOldInfo]);

  const parseSlot = (slot?: string): [number, number] => {
    if (!slot) return [8, 12];
    const parts = slot.replace('SLOT_', '').split('_').map(Number);
    return [parts[0] || 8, parts[1] || 12];
  };

  const areSlotsCompatible = (slotA?: string, slotB?: string): boolean => {
    const [startA, endA] = parseSlot(slotA);
    const [startB, endB] = parseSlot(slotB);
    return startA <= endB + 2 && startB <= endA + 2;
  };

  const isSameDay = (dateA?: string, dateB?: string): boolean => {
    if (!dateA || !dateB) return false;
    const a = new Date(dateA);
    const b = new Date(dateB);
    return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
  };

  const getSameTrajectoryOrders = (booking: any) => {
    if (!booking) return [];
    const pickupCity = booking.pickupAddress?.split(',').pop()?.trim()?.split(' ')[0] || '';
    return rides.filter(b => 
      b.id !== booking.id && 
      (b.trackStatus === 'checking') &&
      b.pickupAddress?.includes(pickupCity) &&
      isSameDay(b.pickupDate, booking.pickupDate) &&
      areSlotsCompatible(b.pickupTimeSlot, booking.pickupTimeSlot)
    );
  };

  const handleCancelOrder = async (id: string) => {
    if (!confirm('Are you sure you want to cancel this order?')) return;
    try {
      const res = await fetch(`${API}/manager/bookings/${id}/cancel`, {
        method: 'PATCH',
        headers: authHeaders(),
      });
      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        throw new Error(errData.message || 'Failed to cancel order. Please try again.');
      }
      invalidateCache('/manager/');
      fetchRides();
      setSelectedId(null);
    } catch (err: any) {
      alert(err.message);
    }
  };

  const filteredRides = useMemo(() => {
    return rides.filter(r => {
      const q = searchQuery.toLowerCase();
      const matchesSearch = r.bookingRef?.toLowerCase().includes(q) || 
                            r.user?.name?.toLowerCase().includes(q) ||
                            r.pickupAddress?.toLowerCase().includes(q) ||
                            r.driver?.user?.name?.toLowerCase().includes(q);
      const matchesStatus = statusFilter ? (
        statusFilter === 'checking' ? ['checking', 'scheduled', 'uncompleted'].includes(r.trackStatus) :
        r.trackStatus === statusFilter
      ) : true;
      return matchesSearch && matchesStatus;
    });
  }, [rides, searchQuery, statusFilter]);

  // F13.1: Clear selectedId if the selected ride is filtered out
  // AND clear it if filters yield 0 results entirely.
  useEffect(() => {
    if (selectedId && !filteredRides.find(r => r.id === selectedId)) {
      setSelectedId(null);
    } else if (filteredRides.length === 0 && selectedId) {
      setSelectedId(null);
    }
  }, [filteredRides, selectedId]);

  const selectedRide = rides.find(r => r.id === selectedId);
  const sameTrajectoryOrders = getSameTrajectoryOrders(selectedRide);

  const itemsVol = (selectedRide?.items || []).reduce((acc: number, item: any) => acc + (item.volumeM3 || 1) * (item.quantity || 1), 0);
  const totalVolume = itemsVol > 0 ? itemsVol : 2; 
  const selectedVan = VAN_SIZES[1]; 
  const fillPercentage = Math.min(100, Math.round((totalVolume / selectedVan.volume) * 100));

  const isPartial = selectedRide?.type === 'FEW_ITEMS' || selectedRide?.type === 'PARCEL';

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-white">
        <div className="w-8 h-8 border-4 border-gray-200 border-t-gray-900 rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="flex h-[calc(100vh-4rem)] bg-[#F7F6F3] p-6 gap-6 overflow-hidden">

      {/* LEFT PANE: ORDER FEED */}
      <div className="w-[350px] shrink-0 flex flex-col bg-white rounded-3xl border border-gray-200 h-full overflow-hidden shadow-sm">
        <div className="p-5 border-b border-gray-100 flex-none bg-white z-10">
          <div className="flex items-center justify-between mb-4">
            <h1 className="text-xl font-black text-gray-900 tracking-tight">Orders Feed</h1>
            <span className="bg-gray-100 text-gray-600 px-2 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider border border-gray-200">
              {rides.length} Active
            </span>
          </div>

          <div className="relative mb-3">
            <svg className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            <input 
              type="text" 
              placeholder="Search ref, name, location..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full bg-[#F7F6F3] border border-gray-200 rounded-xl pl-9 pr-3 py-2 text-[13px] font-medium text-gray-900 placeholder-gray-400 focus:outline-none focus:border-gray-400 transition-colors"
            />
          </div>

          <div className="flex items-center gap-1.5 no-scrollbar overflow-x-auto pb-1 hide-scrollbar">
            {['All', 'Checking', 'Transit', 'Delivered'].map(s => {
              const val = s === 'All' ? null : s.toLowerCase();
              const active = statusFilter === val;
              return (
                <button 
                  key={s}
                  onClick={() => setStatusFilter(val)}
                  className={`px-3 py-1.5 rounded-lg text-[11px] font-bold uppercase tracking-wider border transition-colors whitespace-nowrap ${
                    active ? 'bg-gray-900 text-white border-gray-900' : 'bg-white text-gray-500 border-gray-200 hover:bg-gray-50'
                  }`}
                >
                  {s}
                </button>
              );
            })}
          </div>

          <label className="flex items-center gap-2 cursor-pointer mt-4">
            <input 
              type="checkbox" 
              checked={showOldInfo}
              onChange={(e) => setShowOldInfo(e.target.checked)}
              className="rounded border-gray-300 text-gray-900 focus:ring-gray-900"
            />
            <span className="text-[12px] font-bold text-gray-500">Include historical orders</span>
          </label>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-3 space-y-2 bg-[#F7F6F3]">
          {filteredRides.length === 0 ? (
            <div className="text-center py-10 bg-white rounded-xl border border-dashed border-gray-300">
              <p className="text-sm font-bold text-gray-500">No results found.</p>
              {searchQuery || statusFilter ? (
                <p className="text-[11px] text-gray-400 mt-1">Try clearing your filters or search.</p>
              ) : null}
            </div>
          ) : (
            filteredRides.map(r => {
              const isActive = selectedId === r.id;
              const isChecking = r.trackStatus === 'checking';
              const isTransit = r.trackStatus === 'transit';
              const isDelivered = r.trackStatus === 'delivered';

              const badgeStyle = (r.trackStatus === 'checking' || r.trackStatus === 'scheduled') ? 'bg-amber-50 text-amber-700 border-amber-200' : 
                               isTransit ? 'bg-blue-50 text-blue-700 border-blue-200' : 
                               isDelivered ? 'bg-green-50 text-green-700 border-green-200' : 
                               r.trackStatus === 'uncompleted' ? 'bg-red-50 text-red-700 border-red-200' :
                               'bg-gray-100 text-gray-500 border-gray-200';

              return (
                <div 
                  key={r.id} 
                  onClick={() => setSelectedId(r.id)}
                  className={`p-3.5 rounded-2xl cursor-pointer border transition-all ${
                    isActive 
                      ? 'bg-white border-gray-900 shadow-md ring-1 ring-gray-900' 
                      : 'bg-white border-gray-200 hover:border-gray-300'
                  }`}
                >
                  <div className="flex items-center justify-between mb-2">
                    <p className={`text-[13px] font-black tracking-tight ${isActive ? 'text-gray-900' : 'text-gray-700'}`}>#{r.bookingRef}</p>
                    <span className={`text-[9px] font-bold px-2 py-0.5 rounded uppercase tracking-wider border ${badgeStyle}`}>
                      {r.trackStatus}
                    </span>
                  </div>
                  <p className="text-[12px] font-medium text-gray-500 truncate mb-1">
                    {r.user?.name || 'Guest'}
                  </p>
                  <p className="text-[11px] font-medium text-gray-400 truncate flex items-center gap-1">
                    <svg className="w-3 h-3 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                    {r.pickupAddress?.split(',')[0]}
                  </p>
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* CENTER PANE: THE MAP */}
      <div className="flex-1 bg-white rounded-3xl border border-gray-200 overflow-hidden relative shadow-sm">
        {selectedRide ? (
          <>
            <div className="absolute inset-0 z-0">
              <MapPreview 
                pickupStr={selectedRide.pickupAddress} 
                destinationStr={selectedRide.destinationAddress} 
                driverPos={(selectedRide.driver?.currentLat && selectedRide.driver?.currentLng) ? [selectedRide.driver.currentLat, selectedRide.driver.currentLng] : null}
              />
            </div>

            {/* Top overlay pills */}
            <div className="absolute top-4 left-4 right-4 flex justify-between items-start pointer-events-none z-[400]">
              <div className="flex gap-2">
                <div className="bg-white/90 backdrop-blur border border-gray-200 px-3 py-1.5 rounded-xl shadow-sm flex items-center gap-2 pointer-events-auto">
                  <div className={`w-2 h-2 rounded-full ${selectedRide.trackStatus === 'transit' ? 'bg-green-500 animate-pulse' : 'bg-gray-300'}`} />
                  <span className="text-[11px] font-bold text-gray-900 uppercase tracking-widest">
                    {selectedRide.trackStatus === 'transit' ? 'Live GPS' : 'Offline'}
                  </span>
                </div>
              </div>
            </div>

            {/* Bottom stats overlay */}
            <div className="absolute bottom-4 left-4 right-4 z-[400] pointer-events-auto flex justify-center">
              <div className="bg-white/95 backdrop-blur-md border border-gray-200 rounded-2xl shadow-lg p-2.5 flex items-center divide-x divide-gray-100 text-[12px]">
                <div className="px-4 flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center">
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                  </div>
                  <div>
                    <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Speed</p>
                    <p className="font-black text-gray-900">{selectedRide.trackStatus === 'transit' ? (selectedRide.driver?.speed || 'GPS offline') : '0 mph'}</p>
                  </div>
                </div>
                <div className="px-4 flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-stone-50 text-gray-600 flex items-center justify-center">
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7" /></svg>
                  </div>
                  <div>
                    <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Remaining</p>
                    <p className="font-black text-gray-900">{selectedRide.trackStatus === 'delivered' ? '0 mi' : selectedRide.trackStatus === 'transit' ? (selectedRide.driver?.distanceLeft || 'GPS offline') : 'N/A'}</p>
                  </div>
                </div>
              </div>
            </div>
          </>
        ) : (
          <div className="w-full h-full flex flex-col items-center justify-center bg-gray-50 text-gray-400">
             <svg className="w-12 h-12 mb-3 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1}><path strokeLinecap="round" strokeLinejoin="round" d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7" /></svg>
             <p className="text-[13px] font-bold text-gray-500">Select an order to view the map</p>
          </div>
        )}
      </div>

      {/* RIGHT PANE: ORDER SPOTLIGHT & TIMELINE */}
      {selectedRide ? (
        <div className="w-[400px] shrink-0 bg-white rounded-3xl border border-gray-200 overflow-hidden shadow-sm flex flex-col">
          {/* Header */}
          <div className="px-6 py-5 border-b border-gray-100">
            <div className="flex items-start justify-between mb-2">
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Order Spotlight</p>
                <h2 className="text-xl font-black text-gray-900 tracking-tight mt-1">#{selectedRide.bookingRef}</h2>
                <p className="text-[12px] text-gray-500 font-medium">{selectedRide.type.replace('_', ' ')}</p>
              </div>

              <div className="flex gap-2">
                 {isPartial && (
                  <button 
                    onClick={() => setShowLifo(true)}
                    className="w-8 h-8 rounded-xl bg-purple-50 text-purple-700 flex items-center justify-center hover:bg-purple-100 transition-colors tooltip-trigger"
                    title="Check LIFO Structure"
                  >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" /></svg>
                  </button>
                )}
                {selectedRide.status !== 'CANCELLED' && selectedRide.status !== 'DELIVERED' && (
                  <button 
                    onClick={() => handleCancelOrder(selectedRide.id)}
                    className="w-8 h-8 rounded-xl bg-red-50 text-red-600 flex items-center justify-center hover:bg-red-100 transition-colors tooltip-trigger"
                    title="Cancel Order"
                  >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
                  </button>
                )}
              </div>
            </div>

            {/* Quick Context Alerts */}
            {isPartial && selectedRide.trackStatus === 'checking' && sameTrajectoryOrders.length > 0 && (
              <div className="mt-4 bg-purple-50 border border-purple-100 rounded-xl px-3 py-2 flex items-center gap-2">
                <svg className="w-4 h-4 text-purple-600" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1" /></svg>
                <p className="text-[11px] font-bold text-purple-800">{sameTrajectoryOrders.length} time-matched orders on trajectory</p>
              </div>
            )}
          </div>

          <div className="flex-1 overflow-y-auto custom-scrollbar">
            {/* Prominent Timeline Step Bar */}
            <div className="px-6 py-6 border-b border-gray-100 bg-[#F7F6F3]">
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-4">Current Status</p>

              <div className="relative pl-3 space-y-5">
                <div className={`absolute left-[15px] top-[10px] bottom-[10px] w-0.5 bg-gray-200 rounded-full`}></div>

                {selectedRide.trackStatus === 'uncompleted' ? (
                  <div className="flex items-center justify-between relative z-10">
                    <div className="flex items-center gap-3">
                      <div className="w-2.5 h-2.5 rounded-full border-[3px] ring-4 ring-[#F7F6F3] bg-red-500 border-red-500"></div>
                      <span className="text-[13px] font-black tracking-tight text-red-600">Expired / Unassigned</span>
                    </div>
                  </div>
                ) : (
                  <>
                    <div className="flex items-center justify-between relative z-10">
                      <div className="flex items-center gap-3">
                        <div className={`w-2.5 h-2.5 rounded-full border-[3px] ring-4 ring-[#F7F6F3] ${['checking', 'scheduled'].includes(selectedRide.trackStatus) ? 'bg-gray-900 border-gray-900' : 'bg-gray-400 border-gray-400'}`}></div>
                        <span className={`text-[13px] font-black tracking-tight ${['checking', 'scheduled'].includes(selectedRide.trackStatus) ? 'text-gray-900' : 'text-gray-500'}`}>{selectedRide.trackStatus === 'scheduled' ? 'Scheduled' : 'Checking'}</span>
                      </div>
                      <span className="text-[11px] font-bold text-gray-400">{selectedRide.timeChecking}</span>
                    </div>

                    <div className="flex items-center justify-between relative z-10">
                      <div className="flex items-center gap-3">
                        <div className={`w-2.5 h-2.5 rounded-full border-[3px] ring-4 ring-[#F7F6F3] ${selectedRide.trackStatus === 'transit' ? 'bg-blue-600 border-blue-600 shadow-[0_0_10px_rgba(37,99,235,0.4)] animate-pulse' : 'bg-gray-300 border-gray-300'}`}></div>
                        <span className={`text-[13px] font-black tracking-tight ${selectedRide.trackStatus === 'transit' ? 'text-gray-900' : 'text-gray-500'}`}>In Transit</span>
                      </div>
                      <span className="text-[11px] font-bold text-gray-400">{selectedRide.timeTransit}</span>
                    </div>

                    <div className="flex items-center justify-between relative z-10">
                      <div className="flex items-center gap-3">
                        <div className={`w-2.5 h-2.5 rounded-full border-[3px] ring-4 ring-[#F7F6F3] ${selectedRide.trackStatus === 'delivered' ? 'bg-green-500 border-green-500' : 'bg-gray-200 border-gray-200'}`}></div>
                        <span className={`text-[13px] font-black tracking-tight ${selectedRide.trackStatus === 'delivered' ? 'text-gray-900' : 'text-gray-500'}`}>Delivered</span>
                      </div>
                      <span className="text-[11px] font-bold text-gray-400">{selectedRide.timeDelivered}</span>
                    </div>
                  </>
                )}
              </div>
            </div>

            {/* Quick Info Bar (Driver & Customer) */}
            <div className="grid grid-cols-2 divide-x divide-gray-100 border-b border-gray-100">
              <div className="p-4 flex items-center gap-3 hover:bg-gray-50 transition-colors">
                <div className="w-10 h-10 rounded-full bg-blue-50 border border-blue-100 text-blue-600 flex items-center justify-center font-bold text-[14px]">
                  {selectedRide.driver?.user?.name?.charAt(0) || '?'}
                </div>
                <div className="min-w-0">
                  <p className="text-[9px] font-bold text-gray-400 uppercase tracking-widest">Driver</p>
