function isDriverAvailableOnDate(driver: any, dateStr: string): { available: boolean; slot: string; reason?: string } {
  const date = new Date(dateStr);
  const dayOfWeek = date.getDay();
  const DAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const dayName = DAY_NAMES[dayOfWeek];
  const slots = driver.availability || [];
  // M4 fix: Defaults disagree. Drivers with no rows should be treated as Mon-Fri 08-18 to match driver app.
  if (slots.length === 0) {
    const isMonToFri = dayOfWeek >= 1 && dayOfWeek <= 5;
    return { 
      available: isMonToFri, 
      slot: isMonToFri ? '08:00–18:00' : '',
      reason: isMonToFri ? '' : `Off on ${dayName}s`
    };
  }
  const daySlot = slots.find((s: any) => s.dayOfWeek === dayOfWeek);
  // Day not explicitly listed in schedule → treat as unavailable
  if (!daySlot) return { available: false, slot: '', reason: `Not scheduled on ${dayName}s` };
  // Day exists but explicitly marked inactive → block
  if (!daySlot.isActive) return { available: false, slot: '', reason: `Off duty on ${dayName}s` };
  return { available: true, slot: `${daySlot.startTime}–${daySlot.endTime}` };
}

function checkDriverConflicts(driver: any, dateStr: string, bookingType: string, excludeBookingId?: string) {
  const targetDate = new Date(dateStr).toISOString().split('T')[0];
  const activeBookings = (driver.bookings || []).filter((b: any) => {
    if (b.id === excludeBookingId) return false;
    const bDate = new Date(b.pickupDate).toISOString().split('T')[0];
    if (bDate !== targetDate) return false;
    // M6 fix: FEW_ITEMS can overlap with other FEW_ITEMS
    if (bookingType === 'FEW_ITEMS' && b.type === 'FEW_ITEMS') return false;
    return true;
  });

  if (activeBookings.length > 0) {
    if (bookingType === 'FULL_HOUSE') return { hasConflict: true, reason: 'Busy' };
    else if (activeBookings.some((b: any) => b.type === 'FULL_HOUSE')) return { hasConflict: true, reason: 'Full Removal' };
    // Otherwise it's overlapping regular jobs that aren't FEW_ITEMS-to-FEW_ITEMS
    return { hasConflict: true, reason: 'Busy' };
  }
  return { hasConflict: false, reason: '' };
}

export default function ManagerOperationsHub() {
