      const data = await res.json();
      setAuditLogs(data.auditLogs || []);
    } catch { setAuditLogs([]); }
    finally { setLoadingAudit(false); }
  };

  // Confirmation & preview state
  const [confirming, setConfirming] = useState<string | null>(null);
  const [previewImage, setPreviewImage] = useState<{ url: string; title: string } | null>(null);

  // Assignment state (Full Removals)
  const [proposingId, setProposingId] = useState<string | null>(null);
  const [assigningId, setAssigningId] = useState<string | null>(null);
  const [proposedDrivers, setProposedDrivers] = useState<any[]>([]);
  const [selectedDriver, setSelectedDriver] = useState('');
  const [crewMembers, setCrewMembers] = useState<string[]>([]);

  // Batching state (Partial Removals)
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [batchDriver, setBatchDriver] = useState('');
  const [batching, setBatching] = useState(false);
  const [calculatingBatch, setCalculatingBatch] = useState(false);
const [assigningDriver, setAssigningDriver] = useState(false);
const [cancellingId, setCancellingId] = useState<string | null>(null);

  // Storage updates
  const [storageModalBooking, setStorageModalBooking] = useState<any>(null);
  const [storageDestination, setStorageDestination] = useState('');
  const [storageVolume, setStorageVolume] = useState<number>(0);
  const [updatingStorage, setUpdatingStorage] = useState(false);

  const submitStorageUpdate = async () => {
    if (!storageModalBooking) return;
    setUpdatingStorage(true);
    try {
      const res = await fetch(`${API}/manager/bookings/${storageModalBooking.id}/storage`, {
        method: 'PATCH',
        headers: authHeaders(),
        body: JSON.stringify({
          destinationAddress: storageDestination,
          volumeM3: storageVolume,
        }),
      });
      if (!res.ok) throw new Error('Failed to update storage details');
      setStorageModalBooking(null);
      invalidateCache('/manager/');
      fetchAll();
    } catch (err: any) {
      alert(err.message);
    } finally {
      setUpdatingStorage(false);
    }
  };

  useEffect(() => {
    fetchAll();
    // M3 fix: anchor the replace so it doesn't break api.nglob.com
    const socketUrl = API?.replace(/\/api$/, '') || 'http://localhost:3001';
    const socket = io(`${socketUrl}/tracking`, { 
      auth: { token: getAccessToken() },
      transports: ['polling', 'websocket'],
    });
    socket.emit('subscribe-manager');

    let t: ReturnType<typeof setTimeout>;
    const onUpdate = () => {                       // debounce bursts, always bypass the cache
      clearTimeout(t);
      t = setTimeout(() => {
        invalidateCache('/manager/');
        invalidateCache('/invoices/');
        fetchAll();
      }, 400);
    };
    socket.on('dashboard-updated', onUpdate);
    return () => { clearTimeout(t); socket.disconnect(); };
  }, []);

  // Clear batch proposed if selection cleared
  useEffect(() => {
    if (selectedIds.size === 0) {
      setProposedDrivers([]);
      setBatchDriver('');
    }
  }, [selectedIds]);

  // Pricing Settings State
  const [pricingSettings, setPricingSettings] = useState<any>(null);
  const [pricingSaving, setPricingSaving] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState<any>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // N29: AI insight is now triggered manually (button in the pricing tab) to avoid auto-firing on every tab switch.

  const fetchAll = async () => {
    try {
      const [b, d, p, i] = await Promise.allSettled([
        cachedJson<any>(`${API}/manager/bookings?includeHistorical=true`, { headers: authHeaders() }, { ttl: 15_000 }),
        cachedJson<any[]>(`${API}/manager/drivers`, { headers: authHeaders() }, { ttl: 30_000 }),
        cachedJson<any>(`${API}/pricing/settings`, { headers: authHeaders() }, { ttl: 30_000 }),
        cachedJson<any[]>(`${API}/invoices/all`, { headers: authHeaders() }, { ttl: 30_000 }),
      ]);

      const failed = [b, d, p, i].find((r) => r.status === 'rejected') as PromiseRejectedResult | undefined;
      if (failed?.reason instanceof ApiError && failed.reason.status === 401) { redirectToLogin(); return; }

      if (b.status === 'fulfilled') setBookings(b.value.bookings || []);
      if (d.status === 'fulfilled') setDrivers(d.value || []);
      if (p.status === 'fulfilled') setPricingSettings(p.value);
      if (i.status === 'fulfilled') setInvoices(i.value || []);
      setError(failed ? (failed.reason?.message || 'Some data failed to load') : '');
    } finally { setLoading(false); }
  };

  // --- ACTIONS ---

  const handleCancelOrder = async (id: string) => {
  if (!confirm('Are you sure you want to CANCEL this active order?')) return;
  setCancellingId(id);
  try {
    const res = await fetch(`${API}/manager/bookings/${id}/cancel`, { method: 'PATCH', headers: authHeaders() });
    if (!res.ok) {
      const errData = await res.json().catch(() => ({}));
      throw new Error(errData.message || 'Failed to cancel order. Please try again.');
    }
    invalidateCache('/manager/');
    fetchAll();
  } catch (err: any) { alert(err.message); }
  finally { setCancellingId(null); }
};

  // M10: Separate Decline (for PENDING/CONFIRMED before start) from Cancel
  const handleDeclineOrder = async (id: string) => {
    const reason = window.prompt('Reason for declining (optional):');
    if (reason === null) return; // user pressed Cancel
    setCancellingId(id);
    try {
      const res = await fetch(`${API}/manager/bookings/${id}/decline`, {
        method: 'PATCH',
        headers: authHeaders(),
        body: JSON.stringify({ reason }),
      });
      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        throw new Error(errData.message || 'Failed to decline order.');
      }
      invalidateCache('/manager/');
      fetchAll();
    } catch (err: any) { alert(err.message); }
    finally { setCancellingId(null); }
  };

  const confirmBooking = async (booking: any) => {
    setConfirming(booking.id);
    try {
      const res = await fetch(`${API}/manager/bookings/${booking.id}/confirm`, { method: 'PATCH', headers: authHeaders() });
      if (!res.ok) {
        const errorData = await res.json().catch(() => null);
        throw new Error(errorData?.message || 'Failed to confirm');
      }
      invalidateCache('/manager/');
      fetchAll();
    } catch (err: any) { alert(err.message); }
    finally { setConfirming(null); }
  };

  const handleSendReminder = async (invoiceId: string) => {
    setRemindingId(invoiceId);
    try {
      const res = await fetch(`${API}/invoices/${invoiceId}/remind`, { method: 'POST', headers: authHeaders() });
      if (!res.ok) throw new Error('Failed to send reminder');
      alert('Reminder sent successfully!');
    } catch (err: any) {
      alert(err.message);
    } finally {
      setRemindingId(null);
    }
  };

  // Single Assignment Logic (Full Removals)
  const findBestDrivers = async (booking: any) => {
    setSelectedIds(new Set());
    setProposingId(booking.id);
    setProposedDrivers([]);
    // Clear any previously-selected driver so stale selections never bleed through
    setSelectedDriver('');
    setCrewMembers([]);

    const approved = drivers.filter(d => d.status === 'APPROVED');
    if (approved.length === 0) {
      // Show panel with empty list + clear message immediately
      setAssigningId(booking.id);
      setProposingId(null);
      return;
    }

    // M7 fix: use stored lat/lng to skip geocoding
    const coords = (booking.pickupLat && booking.pickupLng) 
      ? { lat: booking.pickupLat, lng: booking.pickupLng } 
      : await geocodeAddress(booking.pickupAddress);
    if (!coords) {
      // Still show panel so manager can manually pick a driver
      setAssigningId(booking.id);
      setProposingId(null);
      setProposedDrivers(approved.map(d => ({ ...d, distanceMeters: 999999, durationSeconds: 999999 })));
      return;
    }

    const driversWithDist = await Promise.all(
      approved.map(async (d) => {
        const isFresh = d.locationUpdatedAt && (Date.now() - new Date(d.locationUpdatedAt).getTime() < 15 * 60 * 1000);
        if (d.currentLat && d.currentLng && isFresh) {
          const dist = await getDrivingDistance({ lat: d.currentLat, lng: d.currentLng }, coords);
          if (dist) return { ...d, distanceMeters: dist.distanceMeters, durationSeconds: dist.durationSeconds };
        }
        return { ...d, distanceMeters: 999999, durationSeconds: 999999 };
      })
    );
    const sorted = driversWithDist.sort((a, b) => a.durationSeconds - b.durationSeconds);
    setProposedDrivers(sorted);
    setAssigningId(booking.id);
    setProposingId(null);
    // Only auto-select if driver is approved, available, has no conflict, and has real GPS
    let firstValid = sorted.find(d => {
      if (d.durationSeconds === 999999) return false;
      if (d.status !== 'APPROVED') return false;
      const av = isDriverAvailableOnDate(d, booking.pickupDate);
      const conf = checkDriverConflicts(d, booking.pickupDate, booking.type, booking.id);
      return av.available && !conf.hasConflict;
    });
    // Fallback: if no on-duty driver, pick the closest approved driver without conflicts
    if (!firstValid) {
      firstValid = sorted.find(d => {
        if (d.status !== 'APPROVED') return false;
        const conf = checkDriverConflicts(d, booking.pickupDate, booking.type, booking.id);
        return !conf.hasConflict;
      });
