    setAssigningId(null);
    setProposingId(null);
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id); else next.add(id);
    setSelectedIds(next);
  };

  const findBatchDrivers = async () => {
    if (selectedIds.size === 0) return;

    // M6 fix: Ensure all selected bookings are on the same date
    const selectedBookings = Array.from(selectedIds).map(id => bookings.find(b => b.id === id)).filter(Boolean);
    const dates = new Set(selectedBookings.map((b: any) => new Date(b.pickupDate).toISOString().split('T')[0]));
    if (dates.size > 1) {
      alert('All bookings in a batch must be on the same date.');
      return;
    }

    setCalculatingBatch(true);
    setProposedDrivers([]);
    setBatchDriver('');

    const firstId = Array.from(selectedIds)[0];
    const firstBooking = bookings.find(b => b.id === firstId);
    if (!firstBooking) { setCalculatingBatch(false); return; }

    // M7 fix: use stored lat/lng to skip geocoding
    const coords = (firstBooking.pickupLat && firstBooking.pickupLng) 
      ? { lat: firstBooking.pickupLat, lng: firstBooking.pickupLng } 
      : await geocodeAddress(firstBooking.pickupAddress);
    const approved = drivers.filter(d => d.status === 'APPROVED');

    if (!coords) {
      alert('Failed to determine location coordinates for the batch.');
      setProposedDrivers([]);
      setCalculatingBatch(false);
      return;
    }

    const driversWithDist = await Promise.all(
      approved.map(async (d) => {
        const isFresh = d.locationUpdatedAt && (Date.now() - new Date(d.locationUpdatedAt).getTime() < 15 * 60 * 1000);
        if (d.currentLat && d.currentLng && isFresh) {
          const dist = await getDrivingDistance({ lat: d.currentLat, lng: d.currentLng }, coords);
          if (dist) return { ...d, distanceMeters: dist.distanceMeters, durationSeconds: dist.durationSeconds };
        }
        return { ...d, distanceMeters: 999999, durationSeconds: 999999 };
      })
    );
    const sorted = driversWithDist.sort((a, b) => a.durationSeconds - b.durationSeconds);
    setProposedDrivers(sorted);
    if (sorted.length > 0) setBatchDriver(sorted[0].id);
    setCalculatingBatch(false);
  };

  const batchAssign = async () => {
    if (!batchDriver || selectedIds.size === 0) return;
    setBatching(true);
    try {
      const assignments = Array.from(selectedIds).map(id => ({
        bookingId: id,
        driverId: batchDriver
      }));
      const res = await fetch(`${API}/manager/bookings/bulk-assign`, {
        method: 'POST',
        headers: authHeaders(),
        body: JSON.stringify({ assignments })
      });
      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        const msg = Array.isArray(errData.message) ? errData.message.join(', ') : (errData.message || 'Bulk assignment failed');
        throw new Error(msg);
      }
      const data = await res.json();
      const failures = (data.results || []).filter((r: any) => !r.success);
      const successes = (data.results || []).filter((r: any) => r.success);

      if (failures.length > 0 && successes.length > 0) {
        // Partial success — keep only failed IDs selected so manager can retry
        const failedIds = new Set<string>(failures.map((f: any) => f.bookingId as string));
        setSelectedIds(failedIds);
        setBatchDriver('');
        setProposedDrivers([]);
        const errorMsgs = failures.map((f: any) => {
          const ref = bookings.find(b => b.id === f.bookingId)?.bookingRef || f.bookingId;
          return `${ref}: ${f.error}`;
        }).join('\n');
        alert(`PARTIAL SUCCESS — ${successes.length} assigned, ${failures.length} failed.\n\nFailed bookings remain selected for retry:\n${errorMsgs}`);
      } else if (failures.length > 0) {
        const errorMsgs = failures.map((f: any) => {
          const ref = bookings.find(b => b.id === f.bookingId)?.bookingRef || f.bookingId;
          return `${ref}: ${f.error}`;
        }).join('\n');
        alert(`ERROR — No bookings were assigned:\n${errorMsgs}`);
      } else {
        // All succeeded — clear everything
        setSelectedIds(new Set());
        setBatchDriver('');
        setProposedDrivers([]);
        alert(`SUCCESS — All ${successes.length} booking${successes.length > 1 ? 's' : ''} assigned.`);
      }

      invalidateCache('/manager/');
      fetchAll();
