                      </div>
                    </div>

                    {!calculatingBatch && proposedDrivers.length === 0 && (
                      <button onClick={findBatchDrivers} className="w-full bg-blue-600 text-white px-6 py-4 rounded-2xl text-sm font-bold hover:bg-blue-700 hover:shadow-lg transition-all active:scale-95">
