                    {calculatingBatch && (
                      <div className="flex items-center justify-center p-8 bg-blue-50/50 rounded-2xl border border-blue-100/50">
                        <div className="flex flex-col items-center gap-3">
                          <div className="w-6 h-6 border-[3px] border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
                          <p className="text-sm font-bold text-blue-800">Optimizing routes...</p>
                        </div>
                      </div>
                    )}

                    {proposedDrivers.length > 0 && (
                      <div className="space-y-6 animate-fade-in">
                        <div>
                          <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Select Driver</p>
                          <div className="space-y-2 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                            {proposedDrivers.map(d => {
                              const conflict = checkDriverConflicts(d, unassignedPartial.find(b => b.id === Array.from(selectedIds)[0])?.pickupDate, 'FEW_ITEMS');
                              const isSelected = batchDriver === d.id;
                              const canAssign = !conflict.hasConflict;
                              return (
                                <label key={d.id} className={`group flex items-center justify-between p-4 rounded-2xl border cursor-pointer transition-all ${isSelected ? 'border-blue-600 bg-blue-50/50 shadow-[0_4px_20px_rgba(59,130,246,0.1)]' : 'border-gray-100 bg-white hover:border-blue-200 hover:bg-gray-50/50'} ${!canAssign ? 'opacity-40 grayscale cursor-not-allowed' : ''}`}>
                                  <div className="flex items-center gap-4">
                                    <input type="radio" disabled={!canAssign} checked={isSelected} onChange={() => setBatchDriver(d.id)} className="sr-only" />
                                    <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-colors ${isSelected ? 'border-blue-600' : 'border-gray-300 group-hover:border-blue-400'}`}>
                                      {isSelected && <div className="w-2.5 h-2.5 bg-blue-600 rounded-full" />}
                                    </div>
                                    <div>
                                      <p className={`text-sm font-bold ${isSelected ? 'text-blue-900' : 'text-gray-900'}`}>{d.user?.name}</p>
                                      <p className="text-[11px] text-gray-500 font-medium mt-0.5">
