                            })}
                          </div>
                        </div>
                        <button onClick={batchAssign} disabled={!batchDriver || batching} className="w-full bg-[#002244] text-white px-6 py-4 rounded-2xl text-sm font-bold disabled:opacity-50 hover:bg-[#00152b] hover:shadow-xl transition-all flex items-center justify-center gap-3 active:scale-95">
                          {batching && <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />}
                          {batching ? 'Assigning Batch...' : 'Confirm Batch Assignment'}
