const MstiliPage = () => {
  const router = useRouter();
  const [authModalOpen, setAuthModalOpen] = useState(false);
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    const token = getAccessToken();
    const hasToken = !!token;
    setIsLoggedIn(hasToken);

    const params = new URLSearchParams(window.location.search);
    const redirect = params.get('redirect');
    const login = params.get('login');

    if (hasToken && redirect) {
      window.location.href = redirect;
    } else if (!hasToken && login === 'true') {
      setAuthMode('login');
      setAuthModalOpen(true);
    }

    if (videoRef.current) {
      videoRef.current.play().catch(e => console.error("Auto-play failed", e));
    }
  }, []);

  const openLogin = () => { setAuthMode('login'); setAuthModalOpen(true); };
  const openRegister = () => { setAuthMode('register'); setAuthModalOpen(true); };

  return (
    <SmoothScroll>
      <div className="min-h-screen bg-white text-[#1d1d1f] selection:bg-[#0066cc] selection:text-white overflow-x-hidden w-full relative">
        <HeroHeader openLogin={openLogin} isLoggedIn={isLoggedIn} />
        <ServicesGrid />

        <ScrollVideo />

        <HowItWorks />
        <MadeForWhatsNext />
        <DarkFooter />

        <AuthModal
          open={authModalOpen}
          onClose={() => setAuthModalOpen(false)}
          initialMode={authMode}
          onSuccess={(role) => {
            setAuthModalOpen(false);
            const redirect = new URLSearchParams(window.location.search).get('redirect');
            if (redirect) {
              window.location.href = redirect;
              return;
            }
            if (role === 'ADMIN') window.location.href = 'https://admin.nglob.com/';
            else if (role === 'MANAGER') window.location.href = 'https://manager.nglob.com/';
            else if (role === 'DRIVER') window.location.href = 'https://driver.nglob.com/';
            else window.location.href = '/app/';
          }}
        />
      </div>
    </SmoothScroll>
  );
};

