const ScrollVideo = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [hasPlayed, setHasPlayed] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting && videoRef.current) {
            videoRef.current.play().catch(e => console.error("Video play failed", e));
            setHasPlayed(true);
          } else if (!entry.isIntersecting && videoRef.current && hasPlayed) {
            videoRef.current.pause();
          }
        });
      },
      { threshold: 0.1 }
    );

    if (videoRef.current) {
      observer.observe(videoRef.current);
    }

    return () => {
      if (videoRef.current) {
        observer.unobserve(videoRef.current);
      }
    };
  }, [hasPlayed]);

  return (
    <section className="w-full mx-auto my-6 md:my-16 relative">
      <div className="overflow-hidden shadow-2xl relative w-full bg-gray-100 flex items-center justify-center">
        <video
          ref={videoRef}
          loop
          muted
          playsInline
          preload="none"
          className="w-full h-[40vh] sm:h-[50vh] object-cover md:object-fill md:h-[100dvh]"
        >
          <source src="/videohero.webm" type="video/webm" />
          <source src="/videohero.mp4" type="video/mp4" />
        </video>
      </div>
    </section>
  );
};

