"use client";
import React, { useEffect, useId, useRef } from 'react';

export interface ModalProps {
  open: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
}

export function Modal(props: ModalProps) {
  const idPrefix = useId();
  const titleId = `ngs-modal-title-${idPrefix.replace(/:/g, '')}`;
  const dialogRef = useRef<HTMLDialogElement>(null);
  const titleRef = useRef<HTMLHeadingElement>(null);
  const returnFocusRef = useRef<HTMLElement | null>(null);
  const lockedBodyRef = useRef<HTMLElement | null>(null);
  const previousOverflowRef = useRef('');
  const previousTitleRef = useRef('');

  function releaseBackground() {
    if (lockedBodyRef.current) {
      lockedBodyRef.current.style.overflow = previousOverflowRef.current;
      lockedBodyRef.current = null;
    }
    const target = returnFocusRef.current;
    returnFocusRef.current = null;
    if (target?.isConnected) target.focus({ preventScroll: true });
  }

  function requestClose() {
    props.onClose();
  }

  useEffect(() => {
    const dialog = dialogRef.current;
    const open = props.open;
    const nextTitle = props.title;
    if (!dialog) return;
    if (open) {
      const opening = !dialog.open;
      if (opening) {
        returnFocusRef.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
        lockedBodyRef.current = document.body;
        previousOverflowRef.current = lockedBodyRef.current.style.overflow;
        lockedBodyRef.current.style.overflow = 'hidden';
        dialog.showModal();
      }
      if (opening || nextTitle !== previousTitleRef.current) {
        dialog.scrollTop = 0;
        titleRef.current?.focus({ preventScroll: true });
      }
      previousTitleRef.current = nextTitle;
    } else {
      if (dialog.open) dialog.close();
      releaseBackground();
    }
  }, [props.open, props.title]);

  useEffect(() => {
    return () => {
      if (dialogRef.current?.open) dialogRef.current.close();
      releaseBackground();
    };
  }, []);

  function closeFromBackdrop(event: React.MouseEvent<HTMLDialogElement>) {
    const dialog = dialogRef.current;
    if (!dialog || event.target !== dialog) return;
    const rect = dialog.getBoundingClientRect();
    if (
      event.clientX < rect.left ||
      event.clientX > rect.right ||
      event.clientY < rect.top ||
      event.clientY > rect.bottom
    ) {
      requestClose();
    }
  }

  return (
    <dialog
      ref={dialogRef}
      className="ngs-modal"
      aria-labelledby={titleId}
      onCancel={(event) => {
        event.preventDefault();
        requestClose();
      }}
      onClose={() => {
        if (dialogRef.current?.open) return; // Ignore a queued close event after a rapid reopen.
        releaseBackground();
        if (props.open) props.onClose();
      }}
      onClick={closeFromBackdrop}
    >
      <div className="ngs-modal-header">
        <span className="ngs-caption">NGLOB · STUDENTS</span>
        <button
          type="button"
          className="ngs-modal-close"
          aria-label="Close window"
          onClick={requestClose}
        >
          <span aria-hidden="true">×</span>
        </button>
      </div>
      <div className="ngs-modal-content">
        <h2 id={titleId} ref={titleRef} tabIndex={-1}>
          {props.title}
        </h2>
        {props.children}
      </div>
    </dialog>
  );
}

"use client";
import React, { useState, useEffect, useRef, useMemo, useId } from 'react';
import { Modal } from './Modal';
import type { VerificationConfig, VerificationPreviewState, VerificationResult } from './types';

type Step = VerificationPreviewState | 'preview-finish';

export interface VerificationDialogProps {
  open: boolean;
  onClose: () => void;
  config: VerificationConfig;
  contactUrl: string;
  quoteUrl?: string;
}

const MAX_FILE_BYTES = 10 * 1024 * 1024;
const ACCEPTED_TYPES = new Set(['image/jpeg', 'image/png', 'image/webp', 'application/pdf']);
const RESULT_STATUSES = new Set(['received', 'reviewing', 'approved', 'rejected']);

function hasNoticeUrl(value: string): boolean {
  if (!value?.trim() || value.trim().startsWith('#')) return false;
  try {
    const url = new URL(value, 'https://local.invalid/');
    return url.protocol === 'https:' || url.protocol === 'http:';
  } catch {
    return false;
  }
}

/** The host adapter owns authentication, server validation, storage and review. */
function validateResult(value: unknown, expectedId?: string): VerificationResult {
  if (!value || typeof value !== 'object') throw new Error('Invalid verification response');
  const result = value as Record<string, unknown>;
  if (
    typeof result.id !== 'string' ||
    !result.id.trim() ||
    result.id !== result.id.trim() ||
    result.id.length > 256 ||
    /[\u0000-\u001f\u007f]/.test(result.id) ||
    (expectedId !== undefined && result.id !== expectedId) ||
    typeof result.status !== 'string' ||
    !RESULT_STATUSES.has(result.status) ||
    (result.reason !== undefined &&
      (typeof result.reason !== 'string' || result.reason.length > 2000))
  ) {
    throw new Error('Invalid verification response');
  }
  return {
    id: result.id,
    status: result.status as VerificationResult['status'],
    ...(typeof result.reason === 'string' ? { reason: result.reason } : {}),
  };
}

function newRequestKey(): string {
  if (typeof globalThis.crypto?.randomUUID === 'function') return globalThis.crypto.randomUUID();
  const bytes = new Uint8Array(16);
  globalThis.crypto.getRandomValues(bytes);
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
}

export function VerificationDialog(props: VerificationDialogProps) {
  const initialPreviewStep = (): Step =>
    props.config.mode === 'preview' ? (props.config.initialState ?? 'choose') : 'choose';

  const [step, setStep] = useState<Step>(initialPreviewStep());
  const [file, setFile] = useState<File | null>(null);
  const [sample, setSample] = useState(
    props.config.mode === 'preview' && initialPreviewStep() !== 'choose'
  );
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [error, setError] = useState('');
  const [result, setResult] = useState<VerificationResult | null>(null);
  const [busy, setBusy] = useState(false);

  const idPrefix = useId().replace(/:/g, '');
  const helpId = `ngs-file-help-${idPrefix}`;
  const errorId = `ngs-file-error-${idPrefix}`;

  const fileInputRef = useRef<HTMLInputElement>(null);
  const chooseButtonRef = useRef<HTMLButtonElement>(null);
  const fileTitleRef = useRef<HTMLElement>(null);

  const objectUrlRef = useRef<string | null>(null);
  const requestKeyRef = useRef<string | null>(null);
  const requestVersionRef = useRef(0);
  const activeControllerRef = useRef<AbortController | null>(null);
  const wasOpenRef = useRef(false);
  const previousConfigRef = useRef<VerificationConfig | undefined>(undefined);

  const isPreview = props.config.mode === 'preview';
  const isLiveReady = () => {
    const config = props.config;
    return (
      config.mode === 'live' &&
      hasNoticeUrl(config.privacyNoticeUrl) &&
      Boolean(config.privacySummary?.trim()) &&
      typeof config.service?.submit === 'function' &&
      typeof config.service?.getStatus === 'function'
    );
  };
  const isAvailable = isPreview || isLiveReady();
  const hasDocument = Boolean(file || sample);

  function clearSelection() {
    if (objectUrlRef.current) URL.revokeObjectURL(objectUrlRef.current);
    objectUrlRef.current = null;
    requestKeyRef.current = null;
    setImageUrl(null);
    setFile(null);
    setSample(false);
    if (fileInputRef.current) fileInputRef.current.value = '';
  }

  function cancelOperation() {
    requestVersionRef.current += 1;
    activeControllerRef.current?.abort();
    activeControllerRef.current = null;
    setBusy(false);
  }

  function reset(config?: VerificationConfig) {
    cancelOperation();
    clearSelection();
    setResult(null);
    setError('');
    const next = config?.mode === 'preview' ? (config.initialState ?? 'choose') : 'choose';
    setStep(next);
    setSample(config?.mode === 'preview' && next !== 'choose');
  }

  useEffect(() => {
    const open = props.open;
    const config = props.config;
    if (config !== previousConfigRef.current) {
      reset(open ? config : undefined);
    } else if (!open) {
      if (config.mode === 'live') {
        cancelOperation();
        clearSelection();
        setError('');
        setStep(result?.status ?? 'choose');
      } else {
        reset();
      }
    } else if (!wasOpenRef.current) {
      if (config.mode === 'live') setStep(result?.status ?? 'choose');
      else reset(config);
    }
    wasOpenRef.current = open;
    previousConfigRef.current = config;
  }, [props.open, props.config, result]);

  useEffect(() => {
    return () => {
      cancelOperation();
      clearSelection();
      setResult(null);
    };
  }, []);

  function acceptFiles(files: readonly File[]) {
    if (activeControllerRef.current || !isAvailable) return;
    if (files.length !== 1) {
      setError('Please choose just one document.');
      return;
    }
    const chosen = files[0];
    if (!ACCEPTED_TYPES.has(chosen.type)) {
      setError('Choose a JPG, PNG, WebP or PDF file.');
      return;
    }
    if (chosen.size === 0) {
      setError('This file is empty. Choose another document.');
      return;
    }
    if (chosen.size > MAX_FILE_BYTES) {
      setError('This file is larger than 10 MB. Choose a smaller file.');
      return;
    }
    clearSelection();
    setFile(chosen);
    if (chosen.type.startsWith('image/')) {
      objectUrlRef.current = URL.createObjectURL(chosen);
      setImageUrl(objectUrlRef.current);
    }
    setResult(null);
    setError('');
    setStep('choose');
    queueMicrotask(() => {
      if (props.open && file === chosen) fileTitleRef.current?.focus({ preventScroll: true });
    });
  }

  function chooseFile() {
    if (busy) return;
    setError('');
    fileInputRef.current?.click();
  }

  function removeDocument() {
    if (busy) return;
    clearSelection();
    setResult(null);
    setError('');
    setStep('choose');
    chooseButtonRef.current?.focus();
  }

  function useSample() {
    if (!isPreview) return;
    clearSelection();
    setSample(true);
    setError('');
    setStep('choose');
  }

  function reviewDocument() {
    if (!hasDocument) {
      setError('Choose one document to continue.');
      chooseButtonRef.current?.focus();
      return;
    }
    setError('');
    setStep('review');
  }

  function replaceDocument() {
    if (busy) return;
    setResult(null);
    setStep('choose');
    chooseFile();
  }

  async function submitDocument() {
    if (activeControllerRef.current || !hasDocument) return;
    if (isPreview) {
      setError('');
      setStep('preview-finish');
      return;
    }
    const config = props.config;
    const selectedFile = file;
    if (config.mode !== 'live' || !isLiveReady() || !selectedFile) return;
    try {
      requestKeyRef.current = requestKeyRef.current ?? newRequestKey();
    } catch {
      setError('This browser could not start the request. Please contact us for help.');
      return;
    }
    const controller = new AbortController();
    requestVersionRef.current += 1;
    const version = requestVersionRef.current;
    activeControllerRef.current = controller;
    setBusy(true);
    setError('');
    setStep('uploading');
    try {
      const response = await config.service.submit(selectedFile, {
        signal: controller.signal,
        idempotencyKey: requestKeyRef.current,
      });
      if (controller.signal.aborted || version !== requestVersionRef.current || !props.open) return;
      const verifiedResponse = validateResult(response);
      setResult(verifiedResponse);
      clearSelection();
      setStep(verifiedResponse.status);
    } catch {
      if (controller.signal.aborted || version !== requestVersionRef.current || !props.open) return;
      setError(
        'We could not confirm whether your request was received. Try again to check this same request, or contact us for help.'
      );
      setStep('error');
    } finally {
      if (version === requestVersionRef.current) {
        activeControllerRef.current = null;
        setBusy(false);
      }
    }
  }

  async function refreshStatus() {
    const config = props.config;
    const current = result;
    if (activeControllerRef.current || config.mode !== 'live' || !isLiveReady() || !current) return;
    const controller = new AbortController();
    requestVersionRef.current += 1;
    const version = requestVersionRef.current;
    activeControllerRef.current = controller;
    setBusy(true);
    setError('');
    try {
      const response = await config.service.getStatus(current.id, { signal: controller.signal });
      if (controller.signal.aborted || version !== requestVersionRef.current || !props.open) return;
      const verifiedResponse = validateResult(response, current.id);
      setResult(verifiedResponse);
      setStep(verifiedResponse.status);
    } catch {
      if (controller.signal.aborted || version !== requestVersionRef.current || !props.open) return;
      setError(
        'We could not get an update. Your last confirmed status is shown. Try refreshing again or contact us for help.'
      );
    } finally {
      if (version === requestVersionRef.current) {
        activeControllerRef.current = null;
        setBusy(false);
      }
    }
  }

  const getTitle = () => {
    if (!isAvailable) return 'Student verification is not available yet.';
    switch (step) {
      case 'review':
        return 'A quick look before you continue.';
      case 'uploading':
        return isPreview ? 'Example: sending a document.' : 'Sending your document…';
      case 'received':
        return 'Document received.';
      case 'reviewing':
        return 'Your document is being reviewed.';
      case 'approved':
        return 'Student status verified.';
      case 'rejected':
        return 'We need a different document.';
      case 'error':
        return isPreview
          ? 'Example: submission not confirmed.'
          : 'Your submission could not be confirmed.';
      case 'preview-finish':
        return 'Preview complete. Nothing sent.';
      default:
        return 'Your student check. One document.';
    }
  };

  const renderDocumentCard = () => (
    <div className="ngs-file-card">
      <strong ref={fileTitleRef} tabIndex={-1}>
        {sample ? 'Example student proof — sample only' : file?.name}
      </strong>
      <p className="ngs-caption">
        {sample
          ? 'Fictional example · Not a valid document'
          : `${((file?.size ?? 0) / 1024 / 1024).toFixed(2)} MB`}
      </p>
      {sample && (
        <div className="ngs-info">
          <strong>SAMPLE · NOT A REAL DOCUMENT</strong>
          <p>
            Alex Student
            <br />
            Example University
            <br />
            Current student — 2026/27
          </p>
        </div>
      )}
      {imageUrl && (
        <img className="ngs-file-preview" src={imageUrl} alt="Preview of the document you selected" />
      )}
      <div className="ngs-actions">
        <button type="button" className="ngs-link" onClick={chooseFile}>
          Replace document
        </button>
        <button type="button" className="ngs-link" onClick={removeDocument}>
          Remove document
        </button>
      </div>
    </div>
  );

  return (
    <Modal open={props.open} onClose={props.onClose} title={getTitle()}>
      {!isAvailable ? (
        <>
          <p className="ngs-dialog-lead">
            Please contact Nglob about your student offer. Do not send your student document by email.
          </p>
          <p className="ngs-caption">No document can be submitted from this page.</p>
          <div className="ngs-actions">
            <a className="ngs-button ngs-button-primary" href={props.contactUrl}>
              Contact Nglob
            </a>
            <button type="button" className="ngs-button ngs-button-secondary" onClick={props.onClose}>
              Close
            </button>
          </div>
        </>
      ) : (
        <>
          {isPreview && <p className="ngs-preview-notice">Preview only. Nothing is uploaded or approved.</p>}
          <input
            ref={fileInputRef}
            type="file"
            hidden
            accept="image/jpeg,image/png,image/webp,application/pdf"
            aria-label="Choose one proof of student status"
            onChange={(event) => {
              const files = Array.from(event.currentTarget.files ?? []);
              event.currentTarget.value = '';
              if (files.length) acceptFiles(files);
            }}
          />
          {(() => {
            if (step === 'choose' || step === 'review') {
              return (
                <>
                  <p className="ngs-dialog-lead">
                    {step === 'review'
                      ? 'Check that your name, institution and current student status are readable.'
                      : 'Any one document showing your name, institution and current student status.'}
                  </p>
                  <details className="ngs-proof-help" id={helpId}>
                    <summary>What can I use and hide?</summary>
                    <p>
                      A student card, enrolment letter or official student-portal screenshot can work.
                      These are examples, not the only options.
                    </p>
                    <p>
                      You can cover your address, date of birth, student number, QR codes, grades and
                      financial details before choosing your file. Keep your name, institution and current
                      status readable.
                    </p>
                    <p>Please do not upload a passport or bank statement.</p>
                  </details>
                  {hasDocument ? (
                    renderDocumentCard()
                  ) : (
                    <div
                      className="ngs-upload"
                      onDragOver={(event) => event.preventDefault()}
                      onDrop={(event) => {
                        event.preventDefault();
                        acceptFiles(Array.from(event.dataTransfer?.files ?? []));
                      }}
                    >
                      <p>Choose one document, or drop it here.</p>
                      <button
                        ref={chooseButtonRef}
                        type="button"
                        className="ngs-button ngs-button-primary"
                        aria-describedby={`${helpId} ${errorId}`}
                        onClick={chooseFile}
                      >
                        Choose document
                      </button>
                      <p className="ngs-caption">JPG, PNG, WebP or PDF · Up to 10 MB</p>
                    </div>
                  )}
                  {isPreview && (
                    <button type="button" className="ngs-link" onClick={useSample}>
                      Use a sample document
                    </button>
                  )}
                  {props.config.mode === 'live' && isLiveReady() && (
                    <div className="ngs-info">
                      <p>{props.config.mode === 'live' ? props.config.privacySummary : ''}</p>
                      <a className="ngs-link" href={props.config.mode === 'live' ? props.config.privacyNoticeUrl : undefined}>
                        Read the Privacy Notice
                      </a>
                    </div>
                  )}
                  <div className="ngs-actions">
                    {step === 'review' ? (
                      <>
                        <button type="button" className="ngs-button ngs-button-secondary" onClick={() => { setError(''); setStep('choose'); }}>
                          Back
                        </button>
                        <button type="button" className="ngs-button ngs-button-primary" onClick={submitDocument}>
                          {isPreview ? 'Preview next step' : 'Submit for review'}
                        </button>
                      </>
                    ) : (
                      <button type="button" className="ngs-button ngs-button-primary" onClick={reviewDocument}>
                        Continue
                      </button>
                    )}
                  </div>
                  <p className="ngs-caption">
                    Choosing a document does not verify your status, apply a discount or create a booking.
                  </p>
                  {isPreview && (
                    <p className="ngs-caption">
                      Your selected file stays in this browser. Closing this window removes it from the preview.
                    </p>
                  )}
                </>
              );
            }

            if (step === 'uploading') {
              return (
                <>
                  <span className="ngs-status-icon" aria-hidden="true">…</span>
                  <p role="status">
                    {isPreview
                      ? 'This is an example of the sending state. No upload is taking place.'
                      : 'Sending your document for review. Your student status has not been verified.'}
                  </p>
                  {!isPreview && (
                    <p className="ngs-caption">
                      Closing this window stops waiting here. It may not cancel a request already received by Nglob.
                    </p>
                  )}
                </>
              );
            }

            if (step === 'preview-finish') {
              return (
                <>
                  <p className="ngs-dialog-lead">
                    You have reached the end of this preview. Your student status has not been checked. No offer or booking has been created.
                  </p>
                  <div className="ngs-actions">
                    <button type="button" className="ngs-button ngs-button-secondary" onClick={() => setStep('review')}>
                      Back to my document
                    </button>
                    <button type="button" className="ngs-button ngs-button-primary" onClick={props.onClose}>
                      Done
                    </button>
                  </div>
                </>
              );
            }

            if (step === 'error') {
              return (
                <>
                  {isPreview ? (
                    <p className="ngs-dialog-lead">Example error state. No document has been sent and no decision has been made.</p>
                  ) : (
                    <p className="ngs-dialog-lead">
                      The service may have received your document, but we could not confirm the response. Your student status is not confirmed here.
                    </p>
                  )}
                  <div className="ngs-actions">
                    {!isPreview && hasDocument && (
                      <button type="button" className="ngs-button ngs-button-primary" onClick={submitDocument}>
                        Try again
                      </button>
                    )}
                    <button type="button" className="ngs-button ngs-button-secondary" onClick={removeDocument}>
                      {isPreview ? 'Try the document preview' : 'Choose another document'}
                    </button>
                    <a className="ngs-link" href={props.contactUrl}>Get help</a>
                  </div>
                </>
              );
            }

            if (['received', 'reviewing', 'approved', 'rejected'].includes(step)) {
              return (
                <>
                  <span className="ngs-status-icon" aria-hidden="true">
                    {step === 'approved' ? '✓' : step === 'rejected' ? '!' : '…'}
                  </span>
                  {step === 'received' && (
                    <p className="ngs-dialog-lead">
                      Your student status has not been verified yet. Your document is waiting for review.
                    </p>
                  )}
                  {step === 'reviewing' && (
                    <p className="ngs-dialog-lead">
                      Your student check is in progress.
                      {!isPreview && ' You can request the latest status below.'}
                    </p>
                  )}
                  {step === 'approved' && (
                    <p className="ngs-dialog-lead">
                      Review your available student offer and its conditions before booking. Verification does not create a booking or apply a discount by itself.
                    </p>
                  )}
                  {step === 'rejected' && (
                    <p className="ngs-dialog-lead">
                      {isPreview
                        ? 'Example reason: the document does not show current student status.'
                        : result?.reason || 'This document did not confirm your student eligibility. Choose another suitable document or contact us for help.'}
                    </p>
                  )}
                  {!isPreview && (
                    <>
                      <div className="ngs-actions">
                        {step === 'approved' && props.quoteUrl && (
                          <a className="ngs-button ngs-button-primary" href={props.quoteUrl}>
                            Get my moving quote
                          </a>
                        )}
                        {(step === 'received' || step === 'reviewing') && (
                          <button type="button" className="ngs-button ngs-button-primary" disabled={busy} onClick={refreshStatus}>
                            {busy ? 'Checking status…' : 'Refresh status'}
                          </button>
                        )}
                        {step === 'rejected' && (
                          <button type="button" className="ngs-button ngs-button-primary" onClick={replaceDocument}>
                            Replace document
                          </button>
                        )}
                        <a className="ngs-link" href={props.contactUrl}>Get help</a>
                        <button type="button" className="ngs-button ngs-button-secondary" onClick={props.onClose}>
                          Close
                        </button>
                      </div>
                      {busy && <p className="ngs-caption" role="status">Checking for a status update.</p>}
                    </>
                  )}
                </>
              );
            }

            return null;
          })()}

          <p id={errorId} className="ngs-error" role="alert">{error}</p>
          {isPreview && ['uploading', 'received', 'reviewing', 'approved', 'rejected'].includes(step) && (
            <div className="ngs-actions">
              <button type="button" className="ngs-button ngs-button-secondary" onClick={removeDocument}>
                Try the document preview
              </button>
              <button type="button" className="ngs-button ngs-button-primary" onClick={props.onClose}>
                Close preview
              </button>
            </div>
          )}
        </>
      )}
    </Modal>
  );
}

