// components/booking/PackingServicePanel.tsx
// "Choose your packing service" panel, styled to match the
// nglob booking flow (coverage cards, feature checklist,
// access details row, expandable materials/time editor).
//
// Drop-in replacement / wrapper around the original
// FullPackingService.tsx logic — same props, same math,
// new shell.
// ═══════════════════════════════════════════════════════════════
import { useState, useEffect, useMemo, useRef } from 'react';
import { Check, Boxes, ChevronDown, ChevronRight, Warehouse, Truck } from 'lucide-react';
import Image from 'next/image';

interface PackingServicePanelProps {
  homeSize?: string;
  moversCount: number;
  confirmed: boolean;
  onConfirm: (hours: number, materials: any[], price: number) => void;
  onRemove: () => void;
  onUpdate: (hours: number, materials: any[], price: number) => void;
  initialHours?: number;
  initialMaterials?: any[];
  pricesConfig?: any;
  // Access info — owned at page level, passed as props
  stairsFlights: number;
  setStairsFlights: (v: number) => void;
  hasLift: boolean;
  setHasLift: (v: boolean) => void;
  parkingDistance: number;
  setParkingDistance: (v: number) => void;
  tier: TierId;
  setTier: (t: TierId) => void;
}

// ── Materials catalogue (unchanged from FullPackingService) ──────
const getMaterials = (size?: string, pricesConfig?: any) => {
  const multipliers: Record<string, number> = { Studio: 0.5, '1': 1, '2': 2, '3': 3, '4+ bedrooms': 4 };
  const mult = size ? multipliers[size] || 1 : 1;
  return [
    { id: 'MEDIUM_BOX', name: 'Medium box', defaultQty: Math.max(5, Math.round(15 * mult)), priceEach: pricesConfig?.materialMediumBox ?? 4 },
    { id: 'LARGE_BOX', name: 'Large box', defaultQty: Math.max(2, Math.round(5 * mult)), priceEach: pricesConfig?.materialLargeBox ?? 7 },
    { id: 'BUBBLE_WRAP', name: 'Bubble wrap large', defaultQty: Math.max(1, Math.round(1 * mult)), priceEach: pricesConfig?.materialBubbleWrap ?? 7 },
    { id: 'PAPER_ROLL', name: 'Brown paper roll', defaultQty: Math.max(1, Math.round(1 * mult)), priceEach: pricesConfig?.materialPaperRoll ?? 5 },
    { id: 'TAPE', name: 'Packing tape', defaultQty: Math.max(2, Math.round(3 * mult)), priceEach: pricesConfig?.materialTape ?? 1 },
  ];
};

const PACKING_TIME: Record<number, number> = { 1: 4, 2: 2.5, 3: 2 };

export type TierId = 'ESSENTIALS' | 'FULL' | 'PACK_UNPACK';

const getTiers = (homeSize?: string, moversCount: number = 2) => {
  const sizeStr = homeSize
    ? homeSize === 'Studio'
      ? 'studio'
      : homeSize === '1'
        ? '1 bedroom'
        : homeSize === '2' || homeSize === '3'
          ? `${homeSize} bedrooms`
          : homeSize.toLowerCase()
    : 'home';

  const packUnpackName = `Pack + unpack ${sizeStr}`;

  return [
    {
      id: 'ESSENTIALS',
      name: 'Essentials',
      blurb: 'Kitchen & fragile',
      multiplier: 0.6,
      features: [
        `${Math.max(1, moversCount - 1)} professional packer${Math.max(1, moversCount - 1) !== 1 ? 's' : ''}`,
        'Kitchen and fragile items',
        'Standard materials included',
      ],
    },
    {
      id: 'FULL',
      name: `Full ${sizeStr}`,
      blurb: 'Recommended',
      multiplier: 1,
      recommended: true,
      features: [
        `${moversCount} professional packer${moversCount !== 1 ? 's' : ''}`,
        'All items packed safely',
        'Standard materials included',
        'Furniture protection',
      ],
    },
    {
      id: 'PACK_UNPACK',
      name: packUnpackName,
      blurb: 'Full support',
      multiplier: 1.6,
      features: [
        `${moversCount} professional packer${moversCount !== 1 ? 's' : ''}`,
        'Full unpacking at delivery',
        'Standard materials included',
        'Furniture protection',
      ],
    },
  ] as Array<{
    id: TierId;
    name: string;
    blurb: string;
    multiplier: number;
    recommended?: boolean;
    features: string[];
  }>;
};

const SIZE_MULTIPLIERS: Record<string, number> = {
  studio: 0.8,
  '1': 1.0,
  '2': 1.5,
  '3': 2.0,
  '4+ bedrooms': 2.6,
};

const getBasePriceForSize = (size?: string, pricesConfig?: any) => {
  const base = pricesConfig?.fullPackingService ?? 230;
  if (!size) return base;
  const key = size === 'Studio' ? 'studio' : size === '1' ? '1' : size === '2' ? '2' : size === '3' ? '3' : '4+ bedrooms';
  const mult = SIZE_MULTIPLIERS[key] ?? 1;
  return Math.round(base * mult);
};

const getImagePath = (size?: string) => {
  if (!size) return '/fullpackingr/studio.png';
  const lower = size.toLowerCase();
  if (lower.includes('studio')) return '/fullpackingr/studio.png';
  if (lower.includes('1')) return '/fullpackingr/1.png';
  if (lower.includes('2')) return '/fullpackingr/2.png';
  if (lower.includes('3')) return '/fullpackingr/3.png';
  if (lower.includes('4')) return '/fullpackingr/4.png';
  return '/fullpackingr/studio.png';
};

export function PackingServicePanel({
  homeSize,
  moversCount,
  confirmed,
  onConfirm,
  onRemove,
  onUpdate,
  initialHours,
  initialMaterials,
  pricesConfig,
  stairsFlights,
  setStairsFlights,
  hasLift,
  setHasLift,
  parkingDistance,
  setParkingDistance,
  tier,
  setTier,
