  // stairsFlights, hasLift, parkingDistance are now props — no local state here

  const [qtys, setQtys] = useState<Record<string, number>>(() => {
    if (initialMaterials && initialMaterials.length > 0) {
      const obj: Record<string, number> = {};
      initialMaterials.forEach((m) => (obj[m.type] = m.quantity));
      materialsConfig.forEach((m) => {
        if (obj[m.id] === undefined) obj[m.id] = 0;
      });
      return obj;
    }
    return Object.fromEntries(materialsConfig.map((m) => [m.id, m.defaultQty]));
  });

  useEffect(() => {
    const newConfig = getMaterials(homeSize, pricesConfig);
    setQtys(Object.fromEntries(newConfig.map((m) => [m.id, m.defaultQty])));
  }, [homeSize]);

  const [packingHours, setPackingHours] = useState(initialHours || PACKING_TIME[moversCount] || 2.5);

  const setQty = (id: string, val: number) => {
    setQtys((prev) => {
      const next = { ...prev, [id]: Math.max(0, val) };
      return next;
    });
  };

  const adjustHours = (delta: number) => {
    setPackingHours((h) => {
      const next = Math.max(1, Math.round((h + delta) * 2) / 2);
      return next;
    });
  };

  const activeTier = tiers.find((t) => t.id === tier)!;

  const baseServicePrice = getBasePriceForSize(homeSize, pricesConfig);

  // Default hours for the current mover count (used as the baseline for per-hour pricing)
  const defaultHours = PACKING_TIME[moversCount] || 2.5;
  // Hourly rate = base price / default hours — price now scales with the chosen packing hours
  const hourlyRate = baseServicePrice / defaultHours;
  const tierPrice = useMemo(() => Math.round(hourlyRate * packingHours * activeTier.multiplier), [hourlyRate, packingHours, activeTier]);

  const lastReportedRef = useRef({ hours: -1, price: -1, mats: '' });

  useEffect(() => {
