  const totalCost = tierPrice + materialsTotal;

  const formatHours = (h: number) => {
    const hrs = Math.floor(h);
    const mins = Math.round((h - hrs) * 60);
    return mins === 0 ? `${hrs} hr` : `${hrs} hr ${mins} min`;
  };

  return (
    <div className="space-y-6">
      {/* ── Selected coverage summary card ─────────────────────── */}
      <div className="bg-white rounded-[24px] p-6 border border-black/5 relative overflow-hidden">
        <div className="flex flex-col sm:flex-row gap-6">
          {/* Illustration based on home size */}
          <div className="flex items-center justify-center rounded-[18px]">
            <Image
              src={getImagePath(homeSize)}
              width={480}
              height={480}
              alt="Packing illustration"
              className="max-w-full h-auto object-contain transition-all duration-300 hover:scale-[1.02] "
            />
          </div>

          <div className="flex-1">
            <div className="flex items-center gap-2 mb-1">
              <h3 className="text-[20px] font-bold text-[#171a20] tracking-tight">{activeTier.name} packing</h3>
              {activeTier.recommended && (
                <span className="text-[11px] font-bold text-[#3F78B1] bg-[#3F78B1]/10 px-2 py-1 rounded-md">Recommended</span>
              )}
            </div>
            <p className="text-[12px] font-semibold tracking-tight text-[#171a20] mb-2">£{tierPrice}.00</p>
            <p className="text-[13px] text-[#5c5e62] mb-4">Professional packing before your move.</p>

            <ul className="space-y-2 mb-5">
              {activeTier.features.map((f) => (
                <li key={f} className="flex items-center gap-2 text-[14px] text-[#1d1d1f] font-medium">
                  <span className="w-5 h-5 rounded-full bg-[#171a20]/5 flex items-center justify-center flex-shrink-0">
                    <Check size={12} strokeWidth={3} className="text-[#3F78B1]" />
                  </span>
                  {f}
                </li>
              ))}
            </ul>

            <button
              onClick={() => document.getElementById('coverage-selector')?.scrollIntoView({ behavior: 'smooth', block: 'center' })}
              className="text-[14px] font-bold text-[#3F78B1] border border-[#3F78B1]/30 rounded-full px-4 py-2 hover:bg-[#3F78B1]/5 transition-colors"
            >
              Change coverage
            </button>
          </div>
        </div>
      </div>

      {/* ── Coverage selector ───────────────────────────────────── */}
      <div id="coverage-selector">
        <p className="text-[13px] font-bold text-[#171a20] mb-3">Choose your coverage</p>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          {tiers.map((t) => {
            const price = Math.round(hourlyRate * packingHours * t.multiplier);
            const active = t.id === tier;
            return (
              <button
                key={t.id}
                onClick={() => setTier(t.id)}
                className={`text-left flex flex-row justify-between h-[100%] rounded-[18px] p-4 border transition-all duration-150 relative ${active ? 'border-[#3F78B1] bg-[#3F78B1]/5' : 'border-black/10 bg-white hover:border-black/20'
                  }`}
              >
                {/* {active && (
                  <span className="absolute top-3 right-3 w-5 h-5 rounded-full bg-[#3F78B1] flex  items-center justify-center">
                    <Check size={12} strokeWidth={3} className="text-white" />
                  </span>
                )} */}
                <div className='flex flex-col justify-between '>

                  <p className="text-[14px] font-bold text-[#171a20]">{t.name}</p>
                  <p className="text-[12px] text-[#8e8e8e] mb-3">{t.blurb}</p>
                </div>
                <p className="text-[20px] font-semibold text-[#171a20]">£{price}</p>
              </button>
            );
          })}
        </div>
      </div>



      {/* ── Extra packing materials (expandable) ─────────────────── */}
      {/* <div className="bg-[#171a20]/[0.03] rounded-[24px] border border-black/5 overflow-hidden">
        <button
          onClick={() => setMaterialsOpen((o) => !o)}
          className="w-full flex items-center justify-between gap-4 p-5 text-left"
        >
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 rounded-full bg-[#171a20]/5 flex items-center justify-center flex-shrink-0">
              <Truck size={18} strokeWidth={2} className="text-[#171a20]" />
            </div>
            <div>
              <p className="text-[14px] font-bold text-[#171a20]">Extra packing materials</p>
