              {currentMaterialsConfig.map((mat) => (
                <div key={mat.id} className="flex items-center justify-between text-[14px]">
                  <span className="text-[#5b6675] font-medium flex-1">{mat.name}</span>
                  <div className="flex items-center gap-3">
                    <div className="flex items-center gap-1 bg-[#f5f5f7] rounded-full px-1.5 py-1">
                      <button
                        onClick={() => setQty(mat.id, (qtys[mat.id] || 0) - 1)}
                        className="w-7 h-7 flex items-center justify-center text-[#1d1d1f] hover:bg-white rounded-full transition-all duration-200 font-medium shadow-sm hover:shadow-md"
                      >
                        −
                      </button>
                      <span className="w-6 text-center font-bold text-[#1d1d1f]">{qtys[mat.id] || 0}</span>
                      <button
                        onClick={() => setQty(mat.id, (qtys[mat.id] || 0) + 1)}
                        className="w-7 h-7 flex items-center justify-center text-[#1d1d1f] hover:bg-white rounded-full transition-all duration-200 font-medium shadow-sm hover:shadow-md"
                      >
                        +
                      </button>
                    </div>
                    <span className="w-10 text-right font-semibold text-[#1d1d1f]">
                      £{((qtys[mat.id] || 0) * mat.priceEach).toFixed(0)}
                    </span>
                  </div>
                </div>
              ))}
            </div>

            <div className="border-t border-black/5 pt-5">
              <div className="flex items-center justify-between mb-3">
                <p className="text-[14px] font-bold text-[#1d1d1f]">Estimated packing time</p>
                <span className="text-[11px] font-bold text-[#86868b] uppercase tracking-widest bg-[#f5f5f7] px-2 py-1 rounded-md">
                  For {moversCount} mover{moversCount > 1 ? 's' : ''}
                </span>
              </div>
              <div className="flex items-center justify-between">
                <p className="text-[13px] text-[#5b6675]">Adjust if you need more or less time</p>
                <div className="flex items-center gap-1 bg-[#f5f5f7] rounded-full px-1.5 py-1 w-fit">
                  <button
                    onClick={() => adjustHours(-0.5)}
                    className="w-8 h-8 flex items-center justify-center text-[#1d1d1f] hover:bg-white rounded-full transition-all duration-200 font-medium text-lg shadow-sm hover:shadow-md"
                  >
                    −
                  </button>
                  <span className="text-[14px] font-bold text-[#1d1d1f] min-w-[70px] text-center">{formatHours(packingHours)}</span>
                  <button
                    onClick={() => adjustHours(0.5)}
                    className="w-8 h-8 flex items-center justify-center text-[#1d1d1f] hover:bg-white rounded-full transition-all duration-200 font-medium text-lg shadow-sm hover:shadow-md"
                  >
                    +
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div> */}

      {/* ── Total + confirm/remove ───────────────────────────────── */}

    </div>
  );
}

