    </div>
  `,
  iconSize: [0, 0],
  iconAnchor: [0, 0],
});

const pickupIcon = createIcon('#5993CC', 'Origin');
const dropoffIcon = createIcon('#0F172A', 'Destination');

interface MapPreviewProps {
  pickupStr: string;
  destinationStr: string;
  driverPos?: [number, number] | null;
}

function FitBounds({ pickupPos, dropoffPos, driverPos }: { pickupPos: [number, number] | null, dropoffPos: [number, number] | null, driverPos?: [number, number] | null }) {
  const map = useMap();
  useEffect(() => {
    const points = [pickupPos, dropoffPos, driverPos].filter(Boolean) as [number, number][];
    if (points.length > 1) {
      const bounds = L.latLngBounds(points);
      map.fitBounds(bounds, { padding: [56, 56], maxZoom: 13 });
    } else if (points.length === 1) {
      map.setView(points[0], 13);
    }
  }, [pickupPos, dropoffPos, driverPos, map]);
  return null;
}

const driverIcon = createIcon('#22C55E', 'Driver');

export default function MapPreview({ pickupStr, destinationStr, driverPos }: MapPreviewProps) {
  const [pickupPos, setPickupPos] = useState<[number, number] | null>(null);
  const [dropoffPos, setDropoffPos] = useState<[number, number] | null>(null);
  const [routePath, setRoutePath] = useState<[number, number][] | null>(null);
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
    return () => setIsMounted(false);
  }, []);

  useEffect(() => {
    let cancelled = false;
    if (!pickupStr) {
      const resetTimer = setTimeout(() => {
        if (!cancelled) setPickupPos(null);
      }, 0);
      return () => { cancelled = true; clearTimeout(resetTimer); };
    }
    const timer = setTimeout(() => {
      fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(pickupStr)}`)
        .then(res => res.json())
        .then(data => {
          if (data && data.length > 0) {
            if (!cancelled) setPickupPos([parseFloat(data[0].lat), parseFloat(data[0].lon)]);
          }
        });
    }, 800);
    return () => { cancelled = true; clearTimeout(timer); };
  }, [pickupStr]);

  useEffect(() => {
    let cancelled = false;
    if (!destinationStr) {
      const resetTimer = setTimeout(() => {
        if (!cancelled) setDropoffPos(null);
      }, 0);
      return () => { cancelled = true; clearTimeout(resetTimer); };
    }
    const timer = setTimeout(() => {
      fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(destinationStr)}`)
        .then(res => res.json())
        .then(data => {
          if (data && data.length > 0) {
            if (!cancelled) setDropoffPos([parseFloat(data[0].lat), parseFloat(data[0].lon)]);
          }
        });
    }, 800);
    return () => { cancelled = true; clearTimeout(timer); };
  }, [destinationStr]);

  useEffect(() => {
    if (pickupPos && dropoffPos) {
      const url = `https://router.project-osrm.org/route/v1/driving/${pickupPos[1]},${pickupPos[0]};${dropoffPos[1]},${dropoffPos[0]}?geometries=geojson`;
      fetch(url)
        .then(res => res.json())
        .then(data => {
          if (data.routes && data.routes.length > 0) {
            const coordinates = data.routes[0].geometry.coordinates;
            // OSRM returns [lon, lat], Leaflet Polyline expects [lat, lon]
            const latLngs = coordinates.map((c: [number, number]) => [c[1], c[0]]);
            setRoutePath(latLngs);
          }
        })
        .catch(err => {
          console.error("OSRM route error", err);
          // Fallback to straight line
          setRoutePath([pickupPos, dropoffPos]);
        });
    } else {
      const resetTimer = setTimeout(() => setRoutePath(null), 0);
      return () => clearTimeout(resetTimer);
    }
  }, [pickupPos, dropoffPos]);

  const mapRef = useRef<L.Map | null>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    return () => {
      if (wrapperRef.current) {
        const container = wrapperRef.current.querySelector('.leaflet-container');
        if (container) {
          (container as any)._leaflet_id = null;
        }
      }
      if (mapRef.current) {
        try {
          const container = mapRef.current.getContainer();
          if (container) {
            (container as any)._leaflet_id = null;
          }
        } catch (e) {
          // Ignore
        }
      }
    };
  }, []);

  const defaultCenter: [number, number] = [51.505, -0.09]; // Default to London

  const mapCenter = pickupPos || dropoffPos || defaultCenter;

  if (!isMounted) return null;

  return (
    <div ref={wrapperRef} className="relative h-full min-h-[240px] overflow-hidden rounded-2xl bg-[#f3f4f6]">
      <MapContainer
        ref={mapRef}
        center={mapCenter}
        zoom={11}
        zoomControl={true}
        scrollWheelZoom={true}
        dragging={true}
        doubleClickZoom={true}
        touchZoom={true}
        attributionControl
        className="h-full min-h-[240px] w-full"
      >
        <TileLayer
          attribution="MapLibre | &copy; CARTO, &copy; OpenStreetMap contributors"
          url="https://basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}.png?key=cb1_2zkq_1_692c62ad17bffadae9701b6c"
        />
        <FitBounds pickupPos={pickupPos} dropoffPos={dropoffPos} driverPos={driverPos} />
        {pickupPos && <Marker position={pickupPos} icon={pickupIcon} />}
        {dropoffPos && <Marker position={dropoffPos} icon={dropoffIcon} />}
        {driverPos && <Marker position={driverPos} icon={driverIcon} />}
        {routePath && <Polyline positions={routePath} pathOptions={{ color: '#111827', weight: 3, opacity: 0.78, lineCap: 'round', lineJoin: 'round' }} />}
      </MapContainer>
      {!pickupPos && !dropoffPos && (
        <div className="pointer-events-none absolute inset-0 flex items-center justify-center bg-white/35 text-xs font-medium text-slate-500 backdrop-blur-[1px]">
          Add both addresses to see your route
        </div>
      )}
    </div>
  );
}

