interface NGLOBAddItemsModalProps {
  open: boolean;
  onClose: () => void;
  onConfirm: (items: { item: CatalogItem; qty: number }[]) => void;
  inline?: boolean;
  selectedQtys?: Record<string, number>;
}

export function NGLOBAddItemsModal({ open, onClose, onConfirm, inline, selectedQtys }: NGLOBAddItemsModalProps) {
  const [activeCategory, setActiveCategory] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [localQtys, setLocalQtys] = useState<Record<string, number>>({});

  const qtys = selectedQtys || localQtys;

  const handleAdd = (item: CatalogItem, delta: number) => {
    if (!selectedQtys) {
      setLocalQtys(prev => {
        const newQty = (prev[item.id] || 0) + delta;
        if (newQty <= 0) {
          const { [item.id]: _, ...rest } = prev;
          return rest;
        }
        return { ...prev, [item.id]: newQty };
      });
    }
    onConfirm([{ item, qty: delta }]);
  };

  const [localCatalog, setLocalCatalog] = useState<CatalogItem[]>(CATALOG);

  if (!open) return null;

  const ALL_CATEGORIES = [
    { id: 'all', label: 'All' },
    { id: 'tables', label: 'Tables & Chairs' },
    { id: 'sofas', label: 'Sofas' },
    { id: 'beds', label: 'Beds' },
    { id: 'storage', label: 'Storage & Units' },
    { id: 'Appliances', label: 'Appliances' },
    { id: 'Boxes', label: 'Boxes' },
    { id: 'Decor & other', label: 'Decor & other' },
  ];

  const visibleItems = localCatalog.filter(i => {
    if (searchQuery && !i.name.toLowerCase().includes(searchQuery.toLowerCase())) return false;
    if (activeCategory === 'all') return true;
    if (['tables', 'sofas', 'beds', 'storage'].includes(activeCategory)) {
      return i.sub === activeCategory;
    }
    return i.category === activeCategory;
  });

  return (
    <div className={inline ? "w-full flex flex-col" : "fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"}
      onClick={e => { if (!inline && e.target === e.currentTarget) onClose(); }}>
      <div className={`bg-white rounded-2xl w-full flex flex-col overflow-hidden ${inline ? 'h-[500px] border border-black/5 shadow-sm' : 'max-w-3xl max-h-[88vh] shadow-2xl'}`}>

        {/* Header */}
        {!inline && (
          <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 flex-shrink-0">
            <h2 className="font-bold text-gray-900">Add items for moving</h2>
            <div className="flex items-center gap-4">
              <button onClick={onClose} className="text-gray-400 hover:text-gray-700 text-2xl w-8 h-8 flex items-center justify-center">×</button>
            </div>
          </div>
        )}

        {/* Search and Category pills */}
        <div className="px-4 py-3 border-b border-gray-100 flex flex-col lg:flex-row gap-3 items-center flex-shrink-0">

          <div className="flex gap-2 overflow-x-auto [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none] w-full lg:w-auto pb-1 sm:pb-0">
            {ALL_CATEGORIES.map(cat => (
              <button key={cat.id} onClick={() => setActiveCategory(cat.id)}
                className={`px-4 py-1.5 rounded-full text-[12px] font-bold border whitespace-nowrap transition-all ${activeCategory === cat.id
                  ? 'border-blue-600 bg-blue-600 text-white shadow-sm'
                  : 'border-gray-200 bg-white text-gray-600 hover:border-gray-300'
                  }`}>
                {cat.label}
              </button>
            ))}
          </div>
          <div className="flex-1 w-full relative">
            <svg className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2"><path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            <input
              type="text"
              placeholder="Search items..."
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              className="w-full lg:min-w-[300px] xl:min-w-[400px] pl-9 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-xl text-sm font-medium focus:outline-none focus:border-blue-500 focus:bg-white transition-colors"
            />
          </div>
        </div>

        {/* Items grid */}
        <div className="flex-1 overflow-y-auto px-4 py-4">
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2.5">
            {visibleItems.map(item => {
              const qty = qtys[item.id] || 0;
              return (
                <div key={item.id}
                  className={`border rounded-[14px] overflow-hidden transition-all bg-white ${qty > 0 ? 'border-blue-400 shadow-sm shadow-blue-50' : 'border-gray-200 hover:border-gray-300'
                    }`}>
                  <div className="h-32 bg-[#F5F6F7] flex items-center justify-center p-2 relative">
                    {item.photo.startsWith('/') ? (
                      <img src={item.photo} alt={item.name} className="max-h-full max-w-full object-contain " />
                    ) : (
                      <span className="text-3xl">{item.photo}</span>
                    )}
                  </div>
                  <div className="p-2.5">
                    <p className="text-[11px] font-bold text-gray-900 leading-tight mb-0.5 truncate" title={item.name}>{item.name}</p>
                    <p className="text-[11px] font-semibold text-gray-500 mb-2">£{item.price}</p>

                    {qty === 0 ? (
                      <button onClick={() => handleAdd(item, 1)}
                        className="w-full border border-gray-200 text-gray-700 py-1.5 rounded-lg text-[11px] font-bold hover:border-gray-400 transition-colors bg-white hover:bg-gray-50 shadow-[0_1px_2px_rgba(0,0,0,0.02)]">
                        Add
                      </button>
                    ) : (
                      <div className="flex items-center justify-between">
                        <button onClick={() => handleAdd(item, -1)}
                          className="w-7 h-7 border border-gray-200 rounded-lg flex items-center justify-center text-gray-500 hover:border-gray-400 bg-white hover:bg-gray-50 text-sm">
                          −
                        </button>
                        <span className="text-[12px] font-bold text-gray-800">{qty}</span>
                        <button onClick={() => handleAdd(item, 1)}
                          className="w-7 h-7 border border-gray-200 rounded-lg flex items-center justify-center text-gray-500 hover:border-gray-400 bg-white hover:bg-gray-50 text-sm">
                          +
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}


