// 7. NGLOB PACKING MATERIALS MODAL — real product photos, 4 tabs
// ─────────────────────────────────────────────────────────────

type PMTab = 'Popular' | 'Boxes' | 'Wrapping' | 'Stationery';

export interface PackingMaterialItem {
  id: string;
  name: string;
  dims: string;
  price: number;
  photo: string;
  tabs: PMTab[];
}

interface NGLOBPackingMaterialsModalProps {
  open: boolean;
  onClose: () => void;
  onConfirm: (items: { item: PackingMaterialItem; qty: number }[]) => void;
  onViewPackingService?: () => void;
  pricesConfig?: any;
}

export function NGLOBPackingMaterialsModal({ open, onClose, onConfirm, onViewPackingService, pricesConfig }: NGLOBPackingMaterialsModalProps) {
  const [activeTab, setActiveTab] = useState<PMTab>('Popular');
  const [qtys, setQtys] = useState<Record<string, number>>({});

  if (!open) return null;

  const TABS: PMTab[] = ['Popular', 'Boxes', 'Wrapping', 'Stationery'];

  const pmItems: PackingMaterialItem[] = [
    { id: 'MEDIUM_BOX', name: 'Medium box — single walls', dims: '33×33×40cm', price: pricesConfig?.materialMediumBox ?? 2.30, photo: '/few_items/boxes_medium.png', tabs: ['Popular', 'Boxes'] },
    { id: 'LARGE_BOX', name: 'Large box — double walls', dims: '45×45×60cm', price: pricesConfig?.materialLargeBox ?? 4.00, photo: '/few_items/boxes_large.png', tabs: ['Popular', 'Boxes'] },
    { id: 'BUBBLE_WRAP', name: 'Large bubble wrap roll', dims: '1.5×10m roll', price: pricesConfig?.materialBubbleWrap ?? 15.00, photo: '🫧', tabs: ['Popular', 'Wrapping'] },
    { id: 'TAPE', name: 'Brown making tape pack', dims: '1 pack', price: pricesConfig?.materialTape ?? 6.00, photo: '📋', tabs: ['Popular', 'Stationery'] },
    { id: 'PAPER_ROLL', name: 'Paper roll', dims: 'Standard', price: pricesConfig?.materialPaperRoll ?? 8.00, photo: '🗞️', tabs: ['Wrapping'] },
  ];

  const setQty = (id: string, qty: number) => {
    if (qty > 99) qty = 99;
    setQtys(prev => qty <= 0 ? (({ [id]: _, ...rest }) => rest)(prev) : { ...prev, [id]: qty });
  };

  const visible = pmItems.filter(m => m.tabs.includes(activeTab));
  const totalItems = Object.values(qtys).reduce((a, b) => a + b, 0);
  const totalPrice = pmItems.filter(m => qtys[m.id]).reduce(
    (acc, m) => acc + m.price * (qtys[m.id] || 0), 0
  );

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="bg-white rounded-2xl w-full max-w-2xl max-h-[85vh] flex flex-col shadow-2xl overflow-hidden">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 flex-shrink-0">
          <h2 className="font-bold text-gray-900">Add packing materials</h2>
          <div className="flex items-center gap-4">
            {totalItems > 0 && (
              <span className="text-xs bg-blue-50 border border-blue-200 text-blue-700 px-3 py-1.5 rounded-full font-medium">
                {totalItems} item{totalItems !== 1 ? 's' : ''} for £{totalPrice.toFixed(2)}
              </span>
            )}
            <button onClick={onClose} className="text-gray-400 hover:text-gray-700 text-2xl w-8 h-8 flex items-center justify-center">×</button>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-100 px-6 flex-shrink-0">
          {TABS.map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab)}
              className={`py-3 px-3 text-sm border-b-2 transition-colors mr-1 ${activeTab === tab ? 'border-blue-600 text-blue-600 font-medium' : 'border-transparent text-gray-500 hover:text-gray-800'
                }`}>
              {tab}
            </button>
          ))}
        </div>

        {/* Items */}
        <div className="flex-1 overflow-y-auto px-6 py-4">
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
            {visible.map(mat => {
              const qty = qtys[mat.id] || 0;
              return (
                <div key={mat.id}
                  className={`border rounded-2xl overflow-hidden transition-all ${qty > 0 ? 'border-blue-300 shadow-sm' : 'border-gray-100 hover:border-gray-200'
                    }`}>
                  {/* Product photo */}
                  <div className="h-24 bg-gradient-to-br from-stone-50 to-stone-100 flex items-center justify-center p-3">
                    {mat.photo.startsWith('/') ? (
                      <img src={mat.photo} alt={mat.name} className="max-h-full max-w-full object-contain " />
                    ) : (
                      <span className="text-4xl">{mat.photo}</span>
                    )}
                  </div>
                  <div className="p-3">
                    <p className="text-xs font-medium text-gray-800 leading-snug mb-0.5">{mat.name}</p>
                    <p className="text-xs text-gray-400 mb-0.5">{mat.dims}</p>
                    <p className="text-sm font-semibold text-gray-800 mb-2">£{mat.price.toFixed(2)}</p>

                    {qty === 0 ? (
                      <button onClick={() => setQty(mat.id, 1)}
                        className="w-full border border-gray-200 text-gray-600 py-1.5 rounded-xl text-xs hover:border-gray-400 transition-colors">
                        Add
                      </button>
                    ) : (
                      <div className="flex items-center justify-between">
                        <button onClick={() => setQty(mat.id, qty - 1)}
                          className="w-8 h-8 border border-gray-200 rounded-xl flex items-center justify-center text-gray-500 hover:border-gray-400">
                          −
                        </button>
                        <span className="text-sm font-bold">{qty}</span>
                        <button onClick={() => setQty(mat.id, qty + 1)}
                          className="w-8 h-8 border border-gray-200 rounded-xl flex items-center justify-center text-gray-500 hover:border-gray-400">
                          +
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Footer */}
        <div className="border-t border-gray-100 px-6 py-4 flex gap-3 flex-shrink-0">
          <button onClick={() => {
            if (onViewPackingService) onViewPackingService();
            else onClose();
          }}
            className="flex-1 border border-gray-200 text-gray-600 py-3 rounded-xl text-sm font-medium hover:border-gray-400 transition-colors">
            View packing service instead
          </button>
          <button
            onClick={() => {
              const confirmedItems = pmItems.filter(m => qtys[m.id]).map(m => ({ item: m, qty: qtys[m.id] }));
              onConfirm(confirmedItems);
              onClose();
            }}
            disabled={totalItems === 0}
            className={`flex-1 py-3 rounded-xl text-sm font-medium transition-colors ${totalItems === 0 ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-blue-600 text-white hover:bg-blue-700'}`}>
            Confirm selection
          </button>
        </div>
      </div>
    </div>
  );
}


