"use client"

import { useEffect, useRef, useState } from "react"
import { motion, AnimatePresence } from "framer-motion"

// ─── Session gate: only show on first visit, or on import reset ───────────────
const SESSION_KEY = "nglob_preloader_v4"

interface PreloaderProps {
  onComplete?: () => void
  /** Pass true to force-show even if already seen (e.g. after hard events) */
  force?: boolean
}

const EASE: [number, number, number, number] = [0.76, 0, 0.24, 1]

export default function Preloader({ onComplete, force = false }: PreloaderProps) {
  const [render, setRender] = useState(false)
  const [exit, setExit] = useState(false)
  const didRun = useRef(false)

  useEffect(() => {
    if (didRun.current) return
    didRun.current = true

    if (typeof window === "undefined") return

    const seen = sessionStorage.getItem(SESSION_KEY)
    if (!force && seen) {
      onComplete?.()
      return
    }

    sessionStorage.setItem(SESSION_KEY, "1")
    setRender(true)

    // Timeline: exit at 1.4s → DOM removed at 2.05s
    const tExit     = setTimeout(() => setExit(true), 1400)
    const tComplete = setTimeout(() => { setRender(false); onComplete?.() }, 2050)

    return () => { clearTimeout(tExit); clearTimeout(tComplete) }
  }, [force, onComplete])

  return (
    <AnimatePresence>
      {render && (
        <motion.div
          className="fixed inset-0 z-[9999999] bg-white flex items-center justify-center pointer-events-none"
          initial={{ y: 0 }}
          animate={exit ? { y: "-100%" } : { y: 0 }}
          transition={{ duration: 0.65, ease: EASE }}
        >
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: exit ? 0 : 1, scale: exit ? 1.05 : 1 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
          >
            <img 
              src="/logo-dark1.png" 
              alt="Logo" 
              className="w-48 sm:w-64 h-auto object-contain"
            />
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

'use client';

// ═══════════════════════════════════════════════════════════════
// StorageServicePanel — "Secure storage, collected from your door"
// Restyled to match the nglob flat-card booking layout (violet
// accent), built on top of the existing StorageRoom3D logic:
// recommended-size math, seeded-layout 3D stage, size options.
// ═══════════════════════════════════════════════════════════════

import { useEffect, useMemo, useRef, useState } from 'react';
import { Check, Lock, ShieldCheck, Users, PackageCheck, Truck, Warehouse, Package } from 'lucide-react';

// ─── Types (unchanged from StorageRoom3D) ─────────────────────
type HomeSize = 'Studio' | '1' | '2' | '3' | '4+';
type BookingTab = 'moving_home' | 'moving_few_items';

interface SelectedItem {
  qty: number;
}

export interface StorageServicePanelProps {
  sqft: number;
  onSqftChange: (v: number) => void;
  homeSize: HomeSize;
  items: SelectedItem[];
  tab: BookingTab;
  storageAdded: boolean;
  setStorageAdded: (v: boolean) => void;
  storageDays: number;
  storageRequired: boolean;
  storageCost: number;
  returnAddress: string;
  setReturnAddress: (v: string) => void;
  /** optional — falls back to local state if not wired up by the parent */
  weeks?: number;
  onWeeksChange?: (weeks: number) => void;
  /** Weekly storage rate per sqft from /pricing/settings. Defaults to 0.8 */
  ratePerSqftPerWeek?: number;
}

const SIZE_OPTIONS = [25, 50, 75, 100, 150, 200, 250, 300] as const;
const WEEK_OPTIONS = [1, 2, 4, 8, 12] as const;

const HOME_SIZE_LABEL: Record<HomeSize, string> = {
  Studio: 'studio',
  '1': '1-bedroom home',
  '2': '2-bedroom home',
  '3': '3-bedroom home',
  '4+': '4+ bedroom home',
};

// ─── Recommendation math (unchanged) ───────────────────────────
export function recommendSqft(homeSize: HomeSize, items: SelectedItem[], tab: BookingTab): number {
  const byHome: Record<HomeSize, number> = { Studio: 50, '1': 75, '2': 100, '3': 150, '4+': 200 };
  let sqft = byHome[homeSize] ?? 75;
  if (tab === 'moving_few_items') {
    const totalQty = items.reduce((a, i) => a + (i.qty || 0), 0);
    if (totalQty >= 20) sqft = Math.min(300, sqft + 25);
    else if (totalQty > 0 && totalQty < 8) sqft = Math.min(sqft, 50);
  }
  return SIZE_OPTIONS.includes(sqft as (typeof SIZE_OPTIONS)[number])
    ? sqft
    : SIZE_OPTIONS.reduce((best, o) => (Math.abs(o - sqft) < Math.abs(best - sqft) ? o : best), SIZE_OPTIONS[0]);
}

const HOW_IT_WORKS = [
  { icon: Truck, title: 'We collect your items', body: 'From the address you choose' },
  { icon: Warehouse, title: 'We store them securely', body: 'At a closed-access nglob facility' },
  { icon: Package, title: 'You request a return', body: 'Choose all or selected items' },
  { icon: Truck, title: 'We deliver them back', body: 'See the delivery price first' },
];

const FACILITY_FEATURES = [
  { icon: Lock, label: 'Closed-access facility' },
  { icon: ShieldCheck, label: 'Monitored 24/7' },
  { icon: Users, label: 'Handled only by nglob teams' },
  { icon: PackageCheck, label: 'Return all or selected items' },
];

export function StorageRoom3D({
  sqft,
  onSqftChange,
  homeSize,
  items,
  tab,
  storageAdded,
  setStorageAdded,
  storageDays,
  storageRequired,
  storageCost,
