  const totalItemQty = useMemo(() => items.reduce((a, i) => a + (i.qty || 0), 0), [items]);

  const userTouched = useRef(false);
  const didAutoSelect = useRef(false);
  useEffect(() => {
    if (didAutoSelect.current || userTouched.current) return;
    const isValid = (SIZE_OPTIONS as readonly number[]).includes(sqft);
