        </p>

        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3">
          {WEEK_OPTIONS.map((w) => {
            const active = weeks === w;
            const disabled = w < minWeeks;
            return (
              <button
